<?php
/**
 * Analyst bot - single-file build (generated by tools/build.php, do not edit by hand).
 * Upload together with config.php. Webhook URL = the address of this file.
 * Setup in the browser: https://your-domain/path/bot.php?setup=<webhook_secret>
 */

declare(strict_types=1);

namespace {

define('HUB_ROOT', __DIR__);


/**
 * Loads config.php (falls back to config.example.php so tools still run on a fresh checkout).
 */
function app_config(): array
{
    static $config = null;
    if ($config !== null) {
        return $config;
    }
    $file = HUB_ROOT . '/config.php';
    if (!is_file($file)) {
        $file = HUB_ROOT . '/config.example.php';
    }
    $config = require $file;
    date_default_timezone_set($config['timezone'] ?? 'Asia/Tehran');
    \App\Support\Http::$proxy = (string) ($config['proxy'] ?? '');
    // Telegram Bot API address (only changed for testing with a local mock server)
    if (!defined('TG_API_BASE') && !empty($config['telegram_api_base'])) {
        define('TG_API_BASE', rtrim((string) $config['telegram_api_base'], '/'));
    }
    return $config;
}

/**
 * Writable data directory (config 'storage_dir', default ./storage), protected from web access.
 * With $sub a subdirectory is returned (and created).
 */
function app_storage(string $sub = ''): string
{
    static $ready = [];
    $dir = rtrim((string) (app_config()['storage_dir'] ?? ''), '/') ?: HUB_ROOT . '/storage';
    if (!isset($ready[$dir])) {
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }
        if (!is_file($dir . '/.htaccess')) {
            @file_put_contents($dir . '/.htaccess', "<IfModule mod_authz_core.c>\n    Require all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\n    Deny from all\n</IfModule>\n");
        }
        if (!is_file($dir . '/index.html')) {
            @file_put_contents($dir . '/index.html', '');
        }
        $ready[$dir] = true;
    }
    if ($sub === '') {
        return $dir;
    }
    if (!is_dir($dir . '/' . $sub)) {
        @mkdir($dir . '/' . $sub, 0775, true);
    }
    return $dir . '/' . $sub;
}

/** Analysis weights: brain/strategy.php, or the copy embedded in the single-file build. */
function app_brain(): array
{
    $file = HUB_ROOT . '/brain/strategy.php';
    if (is_file($file)) {
        return require $file;
    }
    return function_exists('app_brain_default') ? app_brain_default() : [];
}

/** Path of a Vazirmatn font weight; downloaded into storage on first use if not bundled. */
function app_font(string $weight): string
{
    $local = HUB_ROOT . '/assets/fonts/Vazirmatn-' . $weight . '.ttf';
    if (is_file($local)) {
        return $local;
    }
    $path = app_storage('fonts') . '/Vazirmatn-' . $weight . '.ttf';
    if (!is_file($path) || filesize($path) < 50000) {
        $sources = [
            'https://raw.githubusercontent.com/rastikerdar/vazirmatn/master/fonts/ttf/',
            'https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@master/fonts/ttf/',
        ];
        foreach ($sources as $base) {
            $res = \App\Support\Http::request('GET', $base . 'Vazirmatn-' . $weight . '.ttf', ['timeout' => 30]);
            if ($res['status'] === 200 && strlen($res['body']) > 50000) {
                file_put_contents($path, $res['body']);
                break;
            }
        }
    }
    return $path;
}

function app_log(string $message): void
{
    $dir = app_storage('logs');
    @file_put_contents($dir . '/bot-' . date('Y-m-d') . '.log', '[' . date('H:i:s') . '] ' . $message . "\n", FILE_APPEND);
}

}

namespace {

function app_brain_default(): array
{
/**
 * The bot's "brain": weights and parameters of the analysis engine.
 * Positive score = bullish, negative = bearish. Each weight is the maximum
 * number of points that factor can add or subtract.
 *
 * Custom indicators go in brain/indicators/ (see _example.php there).
 */
return [
    'swing_length' => 3,

    'weights' => [
        'htf_trend' => 22,       // trend of the higher timeframe (structure + EMA)
        'main_structure' => 20,  // HH/HL or LH/LL and last BOS/CHoCH on the requested timeframe
        'ema_alignment' => 10,   // close > EMA20 > EMA50 (or the opposite)
        'ema200' => 8,           // price above / below EMA200
        'rsi_momentum' => 8,
        'rsi_divergence' => 12,
        'macd' => 7,
        'volume' => 5,           // volume confirming the last move
        'zone_reaction' => 10,   // price sitting on a support / order block (or resistance)
        'ltf_momentum' => 6,     // lower timeframe agrees
    ],

    // |score| below this = range market (plan is built from the nearest zone)
    'neutral_threshold' => 15,

    // Stop distance limits, in ATR
    'stop_min_atr' => 0.7,
    'stop_max_atr' => 3.0,

    // Minimum reward/risk for the first target
    'min_rr' => 1.0,
];
}

}

namespace App {

use App\Render\Caption;
use App\Support\Fa;
use App\Telegram\Client;
use App\Telegram\Entities;

/**
 * /panel: inline-keyboard settings for admins. Values are stored in the settings
 * table and override config.php: publish channel, on/off, quota, days, Gemini, DM notice.
 */
final class AdminPanel
{
    // Display order of the week (Persian week starts on Saturday); values are PHP date('w')
    private const WEEK = [6, 0, 1, 2, 3, 4, 5];

    public function __construct(private array $config, private Client $tg, private Storage $db)
    {
    }

    // ---------------------------------------------------------------- effective settings

    public static function channel(Storage $db): ?array
    {
        $raw = $db->get('channel');
        $c = $raw ? json_decode($raw, true) : null;
        return is_array($c) && isset($c['id']) ? $c : null;
    }

    public static function quota(array $config, Storage $db): int
    {
        return (int) ($db->get('quota_per_user') ?? ($config['quota_per_user'] ?? 2));
    }

    /** @return int[] */
    public static function days(array $config, Storage $db): array
    {
        $raw = $db->get('analysis_days');
        if ($raw !== null) {
            return $raw === '' ? [] : array_map('intval', explode(',', $raw));
        }
        return array_map('intval', $config['analysis_days'] ?? [6, 0]);
    }

    public static function geminiOn(array $config, Storage $db): bool
    {
        return ($config['gemini']['api_key'] ?? '') !== '' && $db->get('gemini') !== 'off';
    }

    public static function dmNotice(Storage $db): bool
    {
        return $db->get('dm_notice') !== 'off';
    }

    // ---------------------------------------------------------------- view

    public function show(array $to, ?int $editId = null, string $view = 'main'): void
    {
        [$text, $kb] = match ($view) {
            'days' => $this->daysView(),
            'texts' => $this->textsView(),
            default => $this->mainView(),
        };
        if ($editId !== null) {
            $this->tg->editMessage($to['chat_id'], $editId, $text, $kb);
            return;
        }
        $this->tg->sendMessage($to, $text, ['reply_markup' => ['inline_keyboard' => $kb]]);
    }

    private function mainView(): array
    {
        $ch = self::channel($this->db);
        $paused = $this->db->get('paused') === '1';
        $quota = self::quota($this->config, $this->db);
        $days = self::days($this->config, $this->db);
        $gem = self::geminiOn($this->config, $this->db);
        $hasKey = ($this->config['gemini']['api_key'] ?? '') !== '';
        $dm = self::dmNotice($this->db);
        $log = $this->db->get('admin_log') === 'on';
        $gemStatus = (string) $this->db->get('gemini_status', '');
        $dayNames = $days ? implode('، ', array_map(static fn ($d) => Fa::weekday($d), array_values(array_filter(self::WEEK, static fn ($d) => in_array($d, $days, true))))) : 'هیچ روزی';

        $text = "📊 <b>پنل ربات تحلیل</b>\n\n"
            . '📢 کانال انتشار تحلیل‌ها: ' . ($ch ? '<b>' . htmlspecialchars($ch['title']) . '</b>' . (!empty($ch['username']) ? ' (@' . htmlspecialchars($ch['username']) . ')' : '') : '❌ تنظیم نشده (تحلیل در دایرکت ارسال می‌شود)') . "\n"
            . '⚙️ وضعیت ربات: ' . ($paused ? '⏸ متوقف' : '✅ فعال') . "\n"
            . '🎟 سهمیه هر کاربر: ' . Fa::digits((string) $quota) . " تحلیل در هفته\n"
            . '📅 روزهای تحلیل: ' . $dayNames . "\n"
            . '🧠 Gemini: ' . (!$hasKey ? 'کلید ندارد' : ($gem ? 'روشن' : 'خاموش'))
            . ($gem && $gemStatus !== '' ? "\n      └ آخرین وضعیت: <code>" . htmlspecialchars(mb_substr($gemStatus, 0, 160)) . '</code>' : '') . "\n"
            . '🔔 اطلاع‌رسانی در دایرکت بعد از انتشار: ' . ($dm ? 'روشن' : 'خاموش') . "\n"
            . '📝 گزارش هر تحلیل برای مدیر: ' . ($log ? 'روشن' : 'خاموش');

        $kb = [
            [['text' => $ch ? '📢 تغییر کانال' : '📢 تنظیم کانال', 'callback_data' => 'an:channel']],
        ];
        if ($ch) {
            $kb[0][] = ['text' => '🗑 حذف کانال', 'callback_data' => 'an:channel_clear'];
        }
        $kb[] = [
            ['text' => $paused ? '▶️ روشن کردن ربات' : '⏸ توقف ربات', 'callback_data' => 'an:pause'],
            ['text' => '🧠 Gemini: ' . ($gem ? 'روشن' : 'خاموش'), 'callback_data' => 'an:gemini'],
        ];
        $kb[] = [
            ['text' => '➖', 'callback_data' => 'an:quota:-1'],
            ['text' => '🎟 سهمیه: ' . Fa::digits((string) $quota), 'callback_data' => 'an:noop'],
            ['text' => '➕', 'callback_data' => 'an:quota:1'],
        ];
        $kb[] = [
            ['text' => '📅 روزهای تحلیل', 'callback_data' => 'an:days'],
            ['text' => '🔔 اطلاع دایرکت: ' . ($dm ? 'روشن' : 'خاموش'), 'callback_data' => 'an:dm'],
        ];
        $kb[] = [
            ['text' => '✏️ ویرایش متن‌ها و کپشن', 'callback_data' => 'an:texts'],
            ['text' => '📝 گزارش مدیر: ' . ($log ? 'روشن' : 'خاموش'), 'callback_data' => 'an:log'],
        ];
        $kb[] = [
            ['text' => '📊 آمار', 'callback_data' => 'an:stats'],
            ['text' => '🔄 بروزرسانی', 'callback_data' => 'an:refresh'],
        ];
        $kb[] = [['text' => '🏠 منوی اصلی ربات', 'callback_data' => 'hub:home']];
        return [$text, $kb];
    }

    private function textsView(): array
    {
        $texts = new Texts($this->db);
        $kb = [];
        $row = [];
        foreach (Texts::DEFS as $key => $def) {
            $row[] = ['text' => ($texts->isCustom($key) ? '✏️ ' : '') . $def['title'], 'callback_data' => 'an:text:' . $key];
            if (count($row) === 2) {
                $kb[] = $row;
                $row = [];
            }
        }
        if ($row) {
            $kb[] = $row;
        }
        $kb[] = [['text' => '↩️ بازگشت', 'callback_data' => 'an:back']];
        return ["✏️ <b>ویرایش متن‌های ربات</b>\n\nمتنی را که می‌خواهید تغییر دهید انتخاب کنید. متن‌هایی که ✏️ دارند قبلاً ویرایش شده‌اند.\n\nدر متن جدید می‌توانید از <b>بولد</b>، <i>ایتالیک</i>، نقل‌قول (Quote)، اسپویلر، لینک و ایموجی پریمیوم استفاده کنید.", $kb];
    }

    private function daysView(): array
    {
        $days = self::days($this->config, $this->db);
        $kb = [];
        $row = [];
        foreach (self::WEEK as $d) {
            $row[] = ['text' => (in_array($d, $days, true) ? '✅ ' : '▫️ ') . Fa::weekday($d), 'callback_data' => 'an:day:' . $d];
            if (count($row) === 3) {
                $kb[] = $row;
                $row = [];
            }
        }
        if ($row) {
            $kb[] = $row;
        }
        $kb[] = [['text' => '↩️ بازگشت', 'callback_data' => 'an:back']];
        return ["📅 <b>روزهای تحلیل</b>\nروی هر روز بزنید تا فعال یا غیرفعال شود.", $kb];
    }

    // ---------------------------------------------------------------- actions

    public function callback(array $cq): void
    {
        $data = (string) ($cq['data'] ?? '');
        $msg = $cq['message'] ?? [];
        $chatId = $msg['chat']['id'] ?? ($cq['from']['id'] ?? 0);
        $to = ['chat_id' => $chatId];
        $editId = isset($msg['message_id']) ? (int) $msg['message_id'] : null;
        $parts = explode(':', $data);
        $toast = '';
        $view = 'main';

        switch ($parts[1] ?? '') {
            case 'channel':
                $this->db->set('admin_state_' . $cq['from']['id'], 'await_channel');
                $this->tg->answerCallback($cq['id']);
                $this->tg->sendMessage($to, "📢 <b>تنظیم کانال انتشار</b>\n\n"
                    . "۱) ربات را در کانال <b>ادمین</b> کنید (با دسترسی ارسال پیام).\n"
                    . "۲) یکی از این‌ها را بفرستید:\n"
                    . "• آیدی کانال، مثلاً <code>@mychannel</code>\n"
                    . "• آیدی عددی، مثلاً <code>-1001234567890</code>\n"
                    . "• یا یک پیام از کانال را همین‌جا فوروارد کنید.\n\n"
                    . 'برای لغو: /cancel');
                return;
            case 'texts':
                $view = 'texts';
                break;
            case 'log':
                $this->db->set('admin_log', $this->db->get('admin_log') === 'on' ? null : 'on');
                break;
            case 'text':
                $key = (string) ($parts[2] ?? '');
                if (!isset(Texts::DEFS[$key])) {
                    break;
                }
                $this->tg->answerCallback($cq['id']);
                $this->startTextEdit($to, (int) $cq['from']['id'], $key);
                return;
            case 'text_reset':
                $key = (string) ($parts[2] ?? '');
                if (isset(Texts::DEFS[$key])) {
                    (new Texts($this->db))->set($key, null);
                    $this->db->set('admin_state_' . $cq['from']['id'], null);
                    $this->tg->answerCallback($cq['id'], 'متن پیش‌فرض برگشت');
                    $this->tg->sendMessage($to, '♻️ متن «' . Texts::DEFS[$key]['title'] . '» به حالت پیش‌فرض برگشت.');
                    $this->show($to, null, 'texts');
                    return;
                }
                break;
            case 'channel_clear':
                $this->db->set('channel', null);
                $toast = 'کانال حذف شد';
                break;
            case 'pause':
                $this->db->set('paused', $this->db->get('paused') === '1' ? null : '1');
                $toast = $this->db->get('paused') === '1' ? 'ربات متوقف شد' : 'ربات فعال شد';
                break;
            case 'gemini':
                if (($this->config['gemini']['api_key'] ?? '') === '') {
                    $toast = 'کلید Gemini در config.php خالی است';
                    break;
                }
                $this->db->set('gemini', $this->db->get('gemini') === 'off' ? null : 'off');
                break;
            case 'quota':
                $q = max(0, min(50, self::quota($this->config, $this->db) + (int) ($parts[2] ?? 0)));
                $this->db->set('quota_per_user', (string) $q);
                break;
            case 'days':
                $view = 'days';
                break;
            case 'day':
                $d = (int) ($parts[2] ?? -1);
                $days = self::days($this->config, $this->db);
                $days = in_array($d, $days, true) ? array_values(array_diff($days, [$d])) : array_merge($days, [$d]);
                sort($days);
                $this->db->set('analysis_days', implode(',', $days));
                $view = 'days';
                break;
            case 'dm':
                $this->db->set('dm_notice', self::dmNotice($this->db) ? 'off' : null);
                break;
            case 'stats':
                $s = $this->db->stats((new Bot($this->config, $this->tg, $this->db))->periodKey());
                $top = implode('، ', array_map(static fn ($r) => $r['symbol'] . ' (' . $r['n'] . ')', $s['top'])) ?: '-';
                $this->tg->answerCallback($cq['id']);
                $this->tg->sendMessage($to, "📊 <b>آمار ربات</b>\n"
                    . 'کاربران: ' . $s['users'] . "\n"
                    . 'تحلیل‌های این هفته: ' . $s['period_done'] . ' (برای ' . $s['period_users'] . " نفر)\n"
                    . 'کل تحلیل‌ها: ' . $s['total_done'] . "\n"
                    . 'پرتکرارها: ' . htmlspecialchars($top));
                return;
            case 'noop':
                $this->tg->answerCallback($cq['id']);
                return;
        }
        $this->tg->answerCallback($cq['id'], $toast);
        if ($editId !== null) {
            $this->show($to, $editId, $view);
        }
    }

    private function startTextEdit(array $to, int $adminId, string $key): void
    {
        $def = Texts::DEFS[$key];
        $texts = new Texts($this->db);
        $this->db->set('admin_state_' . $adminId, 'edit_text:' . $key);
        $info = '✏️ <b>ویرایش: ' . $def['title'] . "</b>\n\n"
            . (!empty($def['plain'])
                ? "متن جدید را بفرستید (فقط متن ساده).\n"
                : "متن جدید را با همان قالب‌بندی دلخواه بفرستید؛ بولد، نقل‌قول، لینک و ایموجی پریمیوم حفظ می‌شوند.\n"
                    . "پیشنهاد: پیام بعدی (متن فعلی) را کپی کنید، تغییر دهید و بفرستید.\n")
            . ($def['vars'] !== '' ? "\n🔤 متغیرها (عیناً بنویسید):\n<code>" . htmlspecialchars($def['vars']) . "</code>\n" : '')
            . ($key === 'caption' ? "\nℹ️ {summary} = خلاصه و ابطال Gemini، {reasons} = لیست دلایل، {liquidity} = نقدینگی. کپشن عکس حداکثر ۱۰۲۴ کاراکتر است.\n" : '')
            . "\nبرای لغو: /cancel";
        $this->tg->sendMessage($to, $info, ['reply_markup' => ['inline_keyboard' => [[
            ['text' => '♻️ بازگردانی متن پیش‌فرض', 'callback_data' => 'an:text_reset:' . $key],
        ]]]]);
        $current = $texts->get($key);
        if ($this->tg->sendMessage($to, !empty($def['plain']) ? htmlspecialchars($current) : $current) === null) {
            $this->tg->sendMessage($to, '<pre>' . htmlspecialchars($current) . '</pre>');
        }
    }

    private function finishTextEdit(array $to, array $msg, string $stateKey, string $key): void
    {
        $def = Texts::DEFS[$key];
        $raw = (string) ($msg['text'] ?? $msg['caption'] ?? '');
        if (trim($raw) === '') {
            $this->tg->sendMessage($to, 'متن خالی است. متن جدید را بفرستید یا /cancel');
            return;
        }
        $texts = new Texts($this->db);
        $old = $this->db->get('text_' . $key);
        if (!empty($def['plain'])) {
            $new = trim($raw);
        } else {
            $new = Entities::toHtml($raw, $msg['entities'] ?? $msg['caption_entities'] ?? []);
        }
        $texts->set($key, $new);

        $preview = !empty($def['plain']) ? htmlspecialchars($new) : Texts::fill($new, Texts::sampleVars());
        $note = '';
        if ($key === 'caption') {
            $len = Caption::length($preview);
            $note = "\n\n📏 طول کپشن با داده نمونه: " . Fa::digits((string) $len) . ' از ۱۰۲۴'
                . ($len > 1024 ? ' ⚠️ (طولانی است؛ بخش‌های اختیاری حذف می‌شوند یا متن جدا ارسال می‌شود)' : '');
        }
        $this->tg->sendMessage($to, '👁 <b>پیش‌نمایش با داده نمونه:</b>');
        if ($this->tg->sendMessage($to, $preview) === null) {
            $texts->set($key, $old);
            $this->tg->sendMessage($to, '❌ تلگرام این قالب را نپذیرفت و ذخیره نشد. دوباره بفرستید یا /cancel');
            return;
        }
        $this->db->set($stateKey, null);
        $this->tg->sendMessage($to, '✅ متن «' . $def['title'] . '» ذخیره شد.' . $note);
        $this->show($to, null, 'texts');
    }

    /**
     * Handles the admin's reply while the panel waits for input. Returns true if consumed.
     */
    public function handleState(array $to, array $msg): bool
    {
        $key = 'admin_state_' . $msg['from']['id'];
        $state = (string) $this->db->get($key, '');
        if ($state === '') {
            return false;
        }
        $text = trim((string) ($msg['text'] ?? ''));
        if ($text === '/cancel') {
            $this->db->set($key, null);
            $this->tg->sendMessage($to, 'لغو شد.');
            $this->show($to);
            return true;
        }
        if (str_starts_with($text, '/')) {
            // Any other command leaves the input mode and runs normally.
            $this->db->set($key, null);
            return false;
        }
        if (str_starts_with($state, 'edit_text:')) {
            $textKey = substr($state, 10);
            if (!isset(Texts::DEFS[$textKey])) {
                $this->db->set($key, null);
                return false;
            }
            $this->finishTextEdit($to, $msg, $key, $textKey);
            return true;
        }
        if ($state !== 'await_channel') {
            $this->db->set($key, null);
            return false;
        }

        // A forwarded channel post, @username, t.me link or numeric id
        $ref = null;
        if (($msg['forward_origin']['type'] ?? '') === 'channel') {
            $ref = $msg['forward_origin']['chat']['id'];
        } elseif (isset($msg['forward_from_chat']['id'])) {
            $ref = $msg['forward_from_chat']['id'];
        } elseif (preg_match('~(?:t\.me/|@)([A-Za-z0-9_]{4,})~', $text, $m)) {
            $ref = '@' . $m[1];
        } elseif (preg_match('/^-?\d{6,}$/', $text)) {
            $ref = $text;
        }
        if ($ref === null) {
            $this->tg->sendMessage($to, 'آیدی کانال را به شکل <code>@channel</code> بفرستید یا یک پیام از کانال فوروارد کنید. لغو: /cancel');
            return true;
        }

        $chat = $this->tg->call('getChat', ['chat_id' => $ref]);
        if ($chat === null || ($chat['type'] ?? '') !== 'channel') {
            $this->tg->sendMessage($to, '❌ کانال پیدا نشد. مطمئن شوید آیدی درست است و ربات عضو و ادمین کانال است.');
            return true;
        }
        $member = $this->tg->call('getChatMember', ['chat_id' => $chat['id'], 'user_id' => $this->tg->botId()]);
        $isAdmin = ($member['status'] ?? '') === 'administrator' && !empty($member['can_post_messages']);
        if (!$isAdmin) {
            $this->tg->sendMessage($to, '❌ ربات در کانال <b>' . htmlspecialchars((string) ($chat['title'] ?? '')) . '</b> ادمین نیست یا اجازه ارسال پیام ندارد. اول ربات را ادمین کنید و دوباره بفرستید.');
            return true;
        }
        $this->db->set('channel', json_encode(['id' => $chat['id'], 'title' => $chat['title'] ?? '', 'username' => $chat['username'] ?? ''], JSON_UNESCAPED_UNICODE));
        $this->db->set($key, null);
        $this->tg->sendMessage($to, '✅ کانال <b>' . htmlspecialchars((string) ($chat['title'] ?? '')) . '</b> تنظیم شد. از این به بعد تحلیل‌ها در این کانال منتشر می‌شوند.');
        $this->show($to);
        return true;
    }
}

}

namespace App\Ai {

use App\Support\Http;

/**
 * Google Gemini (AI Studio API key) as the senior analyst: it gets the engine's
 * findings, raw candles and the chart image, decides the final scenario and
 * writes the Persian explanation. The caller validates every number it returns.
 */
final class Gemini
{
    private array $models;

    /** Short description of why the last call returned null ('' after a success). */
    public string $lastError = '';

    /** Tried after the configured model when it is overloaded or unavailable. */
    private const FALLBACK = ['gemini-3.5-flash', 'gemini-3.8-flash', 'gemini-flash-latest', 'gemini-3.1-flash-lite'];

    public function __construct(private string $apiKey, string|array $model = 'gemini-3.5-flash', private string $proxy = '')
    {
        $this->models = array_values(array_unique(array_filter(array_merge((array) $model, self::FALLBACK))));
    }

    public function enabled(): bool
    {
        return $this->apiKey !== '';
    }

    /**
     * @param array $facts      engine output (levels, indicators, draft plan)
     * @param array $candles    ['4h' => [[o,h,l,c,v], ...], '1d' => [...]]
     * @param string|null $image path to a chart image (JPEG/PNG)
     * @return array|null decoded JSON following the schema below
     */
    public function analyze(array $facts, array $candles, ?string $image, string $brainNotes = ''): ?array
    {
        $this->lastError = '';
        if (!$this->enabled()) {
            $this->lastError = 'no api key';
            return null;
        }

        $prompt = <<<TXT
تو یک تحلیلگر ارشد و محتاط بازار کریپتو هستی که به سبک پرایس اکشن و اسمارت مانی (SMC) تحلیل می‌کنی و برای یک کانال تلگرام فارسی می‌نویسی.

ورودی‌ها:
۱) خروجی موتور تحلیل (ساختار بازار در سه تایم‌فریم، BOS/CHoCH، اوردر بلاک‌ها، FVG، زون‌های حمایت و مقاومت، نقدینگی BSL/SSL، دیوارهای اوردربوک، اندیکاتورها و یک پلن پیش‌نویس).
۲) کندل‌های خام (هر ردیف: open, high, low, close, volume؛ قدیمی به جدید).
۳) تصویر چارت همین داده‌ها (اگر ضمیمه شده باشد).

وظیفه:
- داده‌ها و تصویر را بررسی کن و سناریوی محتمل‌تر را انتخاب کن: side = long یا short.
- نقطه ورود (entry_low تا entry_high)، حد ضرر (stop) و سه تارگت را روی سطوح معنادار همین داده‌ها بگذار (اوردر بلاک، زون، FVG، نقدینگی). عدد خیالی نساز.
- حد ضرر باید پشت ساختار یا زونی باشد که سناریو را باطل می‌کند.
- برای long: stop < entry_low <= entry_high < target1 < target2 < target3. برای short برعکس.
- تارگت اول حداقل ۱ برابر ریسک فاصله داشته باشد.
- اگر شواهد ضعیف یا متناقض است، confidence را پایین بگذار (زیر ۵۰) و در summary صریح بگو.
- اگر پلن پیش‌نویس موتور منطقی است می‌توانی همان را تایید کنی.

خروجی فارسی:
- summary: حداکثر ۲ جمله (حداکثر ۲۲۰ کاراکتر)، سناریوی اصلی.
- invalidation: یک جمله کوتاه درباره شرط ابطال سناریو با ذکر قیمت.
- reasons: ۴ یا ۵ دلیل کوتاه (هر کدام حداکثر ۷۵ کاراکتر) که از داده‌ها می‌آیند.
بدون اغراق و بدون وعده سود بنویس.
TXT;
        if ($brainNotes !== '') {
            $prompt .= "\n\nسبک و قوانین اختصاصی مدیر کانال (اولویت بالاتر از قوانین عمومی، به جز قوانین اعداد):\n" . $brainNotes;
        }
        $prompt .= "\n\nخروجی موتور تحلیل:\n" . json_encode($facts, JSON_UNESCAPED_UNICODE);
        foreach ($candles as $tf => $rows) {
            $prompt .= "\n\nکندل‌های {$tf}:\n" . json_encode($rows);
        }

        $parts = [['text' => $prompt]];
        if ($image !== null && is_file($image)) {
            $mime = str_ends_with(strtolower($image), '.png') ? 'image/png' : 'image/jpeg';
            $parts[] = ['inline_data' => ['mime_type' => $mime, 'data' => base64_encode((string) file_get_contents($image))]];
        }

        $num = ['type' => 'NUMBER'];
        $schema = [
            'type' => 'OBJECT',
            'properties' => [
                'side' => ['type' => 'STRING', 'enum' => ['long', 'short']],
                'confidence' => ['type' => 'INTEGER'],
                'entry_low' => $num,
                'entry_high' => $num,
                'stop' => $num,
                'targets' => ['type' => 'ARRAY', 'items' => $num],
                'summary' => ['type' => 'STRING'],
                'invalidation' => ['type' => 'STRING'],
                'reasons' => ['type' => 'ARRAY', 'items' => ['type' => 'STRING']],
            ],
            'required' => ['side', 'confidence', 'entry_low', 'entry_high', 'stop', 'targets', 'summary', 'invalidation', 'reasons'],
        ];

        $body = [
            'contents' => [['role' => 'user', 'parts' => $parts]],
            'generationConfig' => [
                'temperature' => 0.3,
                'maxOutputTokens' => 8192,
                'responseMimeType' => 'application/json',
                'responseSchema' => $schema,
            ],
        ];

        // Total time budget so a user never waits more than ~1.5 minutes.
        $deadline = time() + 90;
        foreach ($this->models as $model) {
            for ($attempt = 0; $attempt < 2; $attempt++) {
                $left = $deadline - time();
                if ($left < 15) {
                    app_log('gemini: time budget exhausted');
                    $this->lastError = trim($this->lastError . ' | time budget exhausted', ' |');
                    return null;
                }
                $res = Http::request('POST', "https://generativelanguage.googleapis.com/v1beta/models/{$model}:generateContent", [
                    'headers' => ['x-goog-api-key: ' . $this->apiKey],
                    'json' => $body,
                    'timeout' => min(75, $left),
                ] + ($this->proxy !== '' ? ['proxy' => $this->proxy] : []));
                // Overloaded / rate limited: wait a moment and retry once before the next model.
                if (!in_array($res['status'], [429, 500, 503], true)) {
                    break;
                }
                sleep(2);
            }
            if ($res['status'] !== 200) {
                app_log("gemini {$model} HTTP {$res['status']}: " . substr($res['body'], 0, 300) . $res['error']);
                $msg = json_decode($res['body'], true)['error']['message'] ?? ($res['error'] ?: 'no response');
                $this->lastError = "{$model}: HTTP {$res['status']} " . mb_substr((string) $msg, 0, 160);
                continue;
            }
            $data = json_decode($res['body'], true);
            $text = '';
            foreach ($data['candidates'][0]['content']['parts'] ?? [] as $part) {
                if (empty($part['thought'])) {
                    $text .= $part['text'] ?? '';
                }
            }
            $text = trim(preg_replace('/^```(?:json)?|```$/m', '', trim($text)));
            $out = json_decode($text, true);
            if (is_array($out) && isset($out['side'], $out['stop'], $out['targets'])) {
                $out['model'] = $model;
                return $out;
            }
            app_log("gemini {$model} unparsable output: " . substr($text, 0, 300));
            $this->lastError = "{$model}: unparsable output";
        }
        return null;
    }
}

}

namespace App\Analysis {

use App\Market\MarketData;
use App\Market\Series;
use App\Support\Fa;

/**
 * The analysis engine: pulls candles on three timeframes, finds structure, zones,
 * order blocks and liquidity, scores the setup and builds a trade plan.
 */
final class Analyzer
{
    private const HIGHER = ['15m' => '1h', '30m' => '4h', '1h' => '4h', '2h' => '1d', '4h' => '1d', '6h' => '1d', '12h' => '1w', '1d' => '1w', '1w' => '1w'];
    private const LOWER = ['15m' => '5m', '30m' => '5m', '1h' => '15m', '2h' => '30m', '4h' => '1h', '6h' => '1h', '12h' => '2h', '1d' => '4h', '1w' => '1d'];

    public function __construct(private MarketData $market, private array $brain, private string $pluginDir = '')
    {
    }

    public function run(string $base, string $tf): array
    {
        $tf = isset(self::HIGHER[$tf]) ? $tf : '4h';
        $main = $this->market->candles($base, $tf, 300);
        $source = $this->market->lastProvider;
        $htf = $this->market->candles($base, self::HIGHER[$tf], 220);
        $ltf = $this->market->candles($base, self::LOWER[$tf], 200);
        $hourly = self::LOWER[$tf] === '1h' ? $ltf : $this->market->candles($base, '1h', 30);

        $len = (int) ($this->brain['swing_length'] ?? 3);
        $w = $this->brain['weights'] ?? [];
        $price = $main->lastClose();
        $n = $main->count();

        $ema20 = Indicators::ema($main->c, 20);
        $ema50 = Indicators::ema($main->c, 50);
        $ema200 = Indicators::ema($main->c, 200);
        $rsi = Indicators::rsi($main->c, 14);
        $atrSeries = Indicators::atr($main->h, $main->l, $main->c, 14);
        $atr = (float) Indicators::last($atrSeries);
        $macd = Indicators::macd($main->c);
        $volSma = Indicators::sma($main->v, 20);

        $swings = Structure::swings($main, $len);
        $structure = Structure::analyze($main, $swings, $len);
        $htfSwings = Structure::swings($htf, 2);
        $htfStructure = Structure::analyze($htf, $htfSwings, 2);
        $ltfStructure = Structure::analyze($ltf, Structure::swings($ltf, $len), $len);

        $zones = Levels::zones($main, array_values(array_filter($swings, static fn ($s) => $s['i'] >= $n - 260)), array_slice($htfSwings, -30), $atr);
        $orderBlocks = Levels::orderBlocks($main, $structure['events'], $atrSeries);
        $fvgs = Levels::fairValueGaps($main, $atr);
        $liquidity = Levels::liquidity($main, $swings, $atr);
        $walls = Levels::walls($this->market->orderBook($base), $price);
        $divergence = Structure::rsiDivergence($main, $swings, $rsi);

        // ---------------------------------------------------------------- scoring
        $score = 0.0;
        $reasons = [];
        $add = static function (float $points, string $text) use (&$score, &$reasons): void {
            if (abs($points) < 0.01) {
                return;
            }
            $score += $points;
            $reasons[] = ['w' => $points, 'fa' => $text];
        };

        $htfEma50 = Indicators::last(Indicators::ema($htf->c, 50));
        $htfEma200 = Indicators::last(Indicators::ema($htf->c, 200)) ?? Indicators::last(Indicators::ema($htf->c, 100));
        $htfName = Fa::tf(self::HIGHER[$tf]);
        $htfTrend = $htfStructure['trend'];
        $htfPts = ($w['htf_trend'] ?? 22);
        $htfDir = ['bullish' => 1, 'bearish' => -1, 'range' => 0][$htfTrend];
        $htfEmaDir = $htfEma50 !== null ? ($htf->lastClose() > $htfEma50 ? 1 : -1) : 0;
        if ($htfDir !== 0) {
            $add($htfDir * $htfPts * 0.6, "روند تایم‌فریم {$htfName} " . Fa::trend($htfTrend) . ' است');
        }
        if ($htfEmaDir !== 0) {
            $add($htfEmaDir * $htfPts * 0.4, 'قیمت ' . ($htfEmaDir > 0 ? 'بالای' : 'زیر') . " EMA50 تایم {$htfName}");
        }

        $tfName = Fa::tf($tf);
        $lastEvent = end($structure['events']) ?: null;
        $mainDir = ['bullish' => 1, 'bearish' => -1, 'range' => 0][$structure['trend']];
        $msPts = $w['main_structure'] ?? 20;
        if ($mainDir !== 0) {
            $txt = $mainDir > 0 ? 'سقف و کف‌های بالاتر' : 'سقف و کف‌های پایین‌تر';
            $add($mainDir * $msPts * 0.6, "ساختار {$tfName} " . Fa::trend($structure['trend']) . " ({$txt})");
        }
        if ($lastEvent && $n - 1 - $lastEvent['to'] <= 40) {
            $d = $lastEvent['dir'] === 'up' ? 1 : -1;
            $kind = $lastEvent['type'] === 'CHoCH' ? 'تغییر ساختار (CHoCH)' : 'شکست ساختار (BOS)';
            $add($d * $msPts * 0.4, $kind . ' ' . ($d > 0 ? 'صعودی' : 'نزولی') . ' در ' . Fa::price($lastEvent['level']));
        }

        $e20 = Indicators::last($ema20);
        $e50 = Indicators::last($ema50);
        $e200 = Indicators::last($ema200);
        if ($e20 !== null && $e50 !== null) {
            if ($price > $e20 && $e20 > $e50) {
                $add($w['ema_alignment'] ?? 10, 'چیدمان صعودی میانگین‌ها (قیمت > EMA20 > EMA50)');
            } elseif ($price < $e20 && $e20 < $e50) {
                $add(-($w['ema_alignment'] ?? 10), 'چیدمان نزولی میانگین‌ها (قیمت < EMA20 < EMA50)');
            }
        }
        if ($e200 !== null) {
            $add(($price > $e200 ? 1 : -1) * ($w['ema200'] ?? 8), 'قیمت ' . ($price > $e200 ? 'بالای' : 'زیر') . ' EMA200');
        }

        $r = (float) Indicators::last($rsi);
        $rsiPts = $w['rsi_momentum'] ?? 8;
        if ($r >= 70) {
            $add(-$rsiPts * 0.5, 'RSI در ناحیه اشباع خرید (' . round($r) . ')');
        } elseif ($r <= 30) {
            $add($rsiPts * 0.5, 'RSI در ناحیه اشباع فروش (' . round($r) . ')');
        } elseif ($r >= 55) {
            $add($rsiPts, 'مومنتوم مثبت RSI (' . round($r) . ')');
        } elseif ($r <= 45) {
            $add(-$rsiPts, 'مومنتوم منفی RSI (' . round($r) . ')');
        }
        if ($divergence) {
            $d = $divergence['type'] === 'bullish' ? 1 : -1;
            $add($d * ($w['rsi_divergence'] ?? 12), 'واگرایی ' . ($d > 0 ? 'مثبت' : 'منفی') . ' RSI');
        }

        $hist = $macd['hist'];
        $h0 = Indicators::last($hist);
        $h1 = Indicators::last($hist, 1);
        if ($h0 !== null && $h1 !== null) {
            $macdPts = $w['macd'] ?? 7;
            if ($h0 > 0 && $h0 >= $h1) {
                $add($macdPts, 'هیستوگرام MACD مثبت و صعودی');
            } elseif ($h0 < 0 && $h0 <= $h1) {
                $add(-$macdPts, 'هیستوگرام MACD منفی و نزولی');
            } elseif ($h0 > 0) {
                $add($macdPts * 0.3, 'MACD بالای خط صفر');
            } else {
                $add(-$macdPts * 0.3, 'MACD زیر خط صفر');
            }
        }

        $lastVol = array_sum(array_slice($main->v, -3)) / 3;
        $avgVol = (float) Indicators::last($volSma);
        if ($avgVol > 0 && $lastVol > 1.3 * $avgVol) {
            $dir = $main->c[$n - 1] >= $main->c[$n - 4] ? 1 : -1;
            $add($dir * ($w['volume'] ?? 5), 'افزایش حجم معاملات همراه با حرکت ' . ($dir > 0 ? 'صعودی' : 'نزولی'));
        }

        $zonePts = $w['zone_reaction'] ?? 10;
        foreach ($orderBlocks as $ob) {
            $near = $ob['dir'] === 'bull'
                ? $price >= $ob['bottom'] - 0.3 * $atr && $price <= $ob['top'] + 0.6 * $atr
                : $price <= $ob['top'] + 0.3 * $atr && $price >= $ob['bottom'] - 0.6 * $atr;
            if ($near) {
                $add(($ob['dir'] === 'bull' ? 1 : -1) * $zonePts, 'قیمت روی اوردر بلاک ' . ($ob['dir'] === 'bull' ? 'صعودی' : 'نزولی') . ' قرار دارد');
                break;
            }
        }
        $sup = $zones['support'][0] ?? null;
        $res = $zones['resistance'][0] ?? null;
        if ($sup && $price - $sup['hi'] < 0.5 * $atr) {
            $add($zonePts * 0.6, 'واکنش به حمایت ' . Fa::price($sup['mid']));
        } elseif ($res && $res['lo'] - $price < 0.5 * $atr) {
            $add(-$zonePts * 0.6, 'برخورد به مقاومت ' . Fa::price($res['mid']));
        }

        $ltfDir = ['bullish' => 1, 'bearish' => -1, 'range' => 0][$ltfStructure['trend']];
        if ($ltfDir !== 0) {
            $add($ltfDir * ($w['ltf_momentum'] ?? 6), 'تایم پایین‌تر (' . Fa::tf(self::LOWER[$tf]) . ') ' . Fa::trend($ltfStructure['trend']) . ' است');
        }

        foreach ($this->plugins() as $name => $plugin) {
            try {
                $res2 = $plugin(['main' => $main, 'htf' => $htf, 'ltf' => $ltf, 'price' => $price, 'atr' => $atr, 'tf' => $tf]);
            } catch (\Throwable $e) {
                app_log("plugin $name failed: " . $e->getMessage());
                continue;
            }
            if (is_array($res2) && isset($res2['score'])) {
                $add(max(-100, min(100, (float) $res2['score'])), (string) ($res2['reason'] ?? $name));
            }
        }

        $score = max(-100.0, min(100.0, $score));
        $neutral = abs($score) < ($this->brain['neutral_threshold'] ?? 15);
        if ($neutral) {
            $distSup = $sup ? $price - $sup['mid'] : INF;
            $distRes = $res ? $res['mid'] - $price : INF;
            $side = $distSup <= $distRes ? 'long' : 'short';
        } else {
            $side = $score > 0 ? 'long' : 'short';
        }

        $plan = $this->plan($side, $main, $price, $atr, $zones, $orderBlocks, $liquidity, $fvgs, $swings);
        $confidence = (int) round(min(92, 38 + abs($score) * 0.62 + min(8, max(0, ($plan['rr'][1] ?? 1) - 1.5) * 3)));
        if ($neutral) {
            $confidence = min($confidence, 52);
        }

        // Keep the reasons that support the chosen side first.
        $sign = $side === 'long' ? 1 : -1;
        usort($reasons, static fn ($a, $b) => ($b['w'] * $sign) <=> ($a['w'] * $sign));

        // 24h statistics from hourly candles
        $last24 = $hourly->tail(24);
        $open24 = $last24->o[0];
        $quoteVolume = 0.0;
        foreach ($last24->v as $i => $v) {
            $quoteVolume += $v * $last24->c[$i];
        }

        return [
            'base' => strtoupper($base),
            'quote' => $this->market->quote(),
            'symbol' => $main->symbol,
            'timeframe' => $tf,
            'htf' => self::HIGHER[$tf],
            'ltf' => self::LOWER[$tf],
            'source' => $source,
            'time' => time(),
            'price' => $price,
            'change24h' => $open24 > 0 ? ($price - $open24) / $open24 * 100 : 0.0,
            'high24h' => max($last24->h),
            'low24h' => min($last24->l),
            'volume24h' => $quoteVolume,
            'atr' => $atr,
            'rsi' => $r,
            'macd_hist' => $h0,
            'ema' => ['20' => $e20, '50' => $e50, '200' => $e200],
            'trend' => [self::HIGHER[$tf] => $htfTrend, $tf => $structure['trend'], self::LOWER[$tf] => $ltfStructure['trend']],
            'last_event' => $lastEvent,
            'events' => array_slice($structure['events'], -6),
            'labels' => array_slice($structure['labels'], -12),
            'zones' => ['support' => $zones['support'], 'resistance' => $zones['resistance']],
            'key_levels' => $zones['key'],
            'order_blocks' => $orderBlocks,
            'fvg' => $fvgs,
            'liquidity' => $liquidity,
            'walls' => $walls,
            'divergence' => $divergence,
            'score' => (int) round($score),
            'bias' => $neutral ? 'neutral' : $side,
            'confidence' => $confidence,
            'plan' => $plan,
            'reasons' => $reasons,
            'series' => $main,
            'htf_series' => $htf,
            'ema_series' => ['20' => $ema20, '50' => $ema50, '200' => $ema200],
            'rsi_series' => $rsi,
        ];
    }

    private function plan(string $side, Series $s, float $price, float $atr, array $zones, array $obs, array $liq, array $fvgs, array $swings): array
    {
        $long = $side === 'long';
        $sign = $long ? 1 : -1;

        // Entry: nearest order block / zone on our side, within 3.5 ATR.
        $candidates = [];
        foreach ($obs as $ob) {
            if ($ob['dir'] === ($long ? 'bull' : 'bear')) {
                $candidates[] = ['lo' => $ob['bottom'], 'hi' => $ob['top'], 'kind' => 'ob', 'prio' => 1];
            }
        }
        foreach ($zones[$long ? 'support' : 'resistance'] as $z) {
            $candidates[] = ['lo' => $z['lo'], 'hi' => $z['hi'], 'kind' => 'zone', 'prio' => 2];
        }
        foreach ($fvgs as $g) {
            if ($g['dir'] === ($long ? 'bull' : 'bear')) {
                $candidates[] = ['lo' => $g['bottom'], 'hi' => $g['top'], 'kind' => 'fvg', 'prio' => 3];
            }
        }
        $entry = null;
        $best = INF;
        foreach ($candidates as $c) {
            $edge = $long ? $c['hi'] : $c['lo'];
            $dist = ($price - $edge) * $sign; // >0 = zone is in the pullback direction
            if ($dist < -0.3 * $atr || $dist > 3.5 * $atr) {
                continue;
            }
            $rank = max($dist, 0) / $atr + $c['prio'] * 0.35;
            if ($rank < $best) {
                $best = $rank;
                $entry = $c;
            }
        }
        if ($entry === null || ($long ? $price < $entry['hi'] : $price > $entry['lo'])) {
            // Already inside the zone (or nothing close): enter around the current price.
            $lo = $long ? $price - 0.35 * $atr : $price - 0.1 * $atr;
            $hi = $long ? $price + 0.1 * $atr : $price + 0.35 * $atr;
            $entry = ['lo' => $lo, 'hi' => $hi, 'kind' => $entry['kind'] ?? 'market'];
        }
        $zoneLo = $entry['lo'];
        $zoneHi = $entry['hi'];
        if ($entry['hi'] - $entry['lo'] > 1.2 * $atr) {
            // Trim wide zones to the half closest to price.
            $mid = ($entry['lo'] + $entry['hi']) / 2;
            $long ? $entry['lo'] = $mid : $entry['hi'] = $mid;
        }
        $entryMid = ($entry['lo'] + $entry['hi']) / 2;

        // Stop: beyond the zone and the closest protective swing.
        $stop = $long ? $zoneLo - 0.3 * $atr : $zoneHi + 0.3 * $atr;
        foreach (array_reverse($swings) as $sw) {
            if ($long && $sw['type'] === 'low' && $sw['price'] < $entry['lo'] && $entry['lo'] - $sw['price'] < 1.2 * $atr) {
                $stop = min($stop, $sw['price'] - 0.2 * $atr);
                break;
            }
            if (!$long && $sw['type'] === 'high' && $sw['price'] > $entry['hi'] && $sw['price'] - $entry['hi'] < 1.2 * $atr) {
                $stop = max($stop, $sw['price'] + 0.2 * $atr);
                break;
            }
        }
        $risk = abs($entryMid - $stop);
        $minRisk = ($this->brain['stop_min_atr'] ?? 0.7) * $atr;
        $maxRisk = ($this->brain['stop_max_atr'] ?? 3.0) * $atr;
        $risk = max($minRisk, min($maxRisk, $risk));
        $stop = $entryMid - $sign * $risk;

        // Targets: opposing zones, order blocks, liquidity and gaps beyond 1R.
        $levels = [];
        foreach ($zones[$long ? 'resistance' : 'support'] as $z) {
            $levels[] = $long ? $z['lo'] : $z['hi'];
        }
        foreach ($obs as $ob) {
            if ($ob['dir'] === ($long ? 'bear' : 'bull')) {
                $levels[] = $long ? $ob['bottom'] : $ob['top'];
            }
        }
        foreach ($liq as $l) {
            if ($l['side'] === ($long ? 'buy' : 'sell')) {
                $levels[] = $l['price'];
            }
        }
        foreach ($fvgs as $g) {
            if ($g['dir'] === ($long ? 'bear' : 'bull')) {
                $levels[] = $long ? $g['bottom'] : $g['top'];
            }
        }
        $minRR = $this->brain['min_rr'] ?? 1.0;
        $levels = array_values(array_filter($levels, static fn ($p) => ($p - $entryMid) * $sign >= $minRR * $risk));
        usort($levels, static fn ($a, $b) => ($a <=> $b) * $sign);
        $targets = [];
        foreach ($levels as $p) {
            if ($targets && abs($p - end($targets)) < 0.6 * $atr) {
                continue;
            }
            $targets[] = $p;
            if (count($targets) === 3) {
                break;
            }
        }
        $mult = [1.5, 2.5, 3.5];
        while (count($targets) < 3) {
            $k = count($targets);
            $candidate = $entryMid + $sign * $risk * $mult[$k];
            if ($targets && ($candidate - end($targets)) * $sign < 0.8 * $risk) {
                $candidate = end($targets) + $sign * $risk;
            }
            $targets[] = $candidate;
        }

        return self::finalizePlan($side, $entry['lo'], $entry['hi'], $stop, $targets, $price, $atr) + ['entry_kind' => $entry['kind']];
    }

    /** Builds the plan array (R multiples, risk %, projected path) from raw levels. */
    public static function finalizePlan(string $side, float $entryLo, float $entryHi, float $stop, array $targets, float $price, float $atr): array
    {
        $entryMid = ($entryLo + $entryHi) / 2;
        $risk = max(abs($entryMid - $stop), 1e-12);
        return [
            'side' => $side,
            'entry' => [min($entryLo, $entryHi), max($entryLo, $entryHi)],
            'entry_mid' => $entryMid,
            'stop' => $stop,
            'targets' => array_values($targets),
            'rr' => array_map(static fn ($t) => round(abs($t - $entryMid) / $risk, 2), array_values($targets)),
            'risk_pct' => $risk / $entryMid * 100,
            'path' => self::path($side === 'long', $price, $entryMid, array_values($targets), $atr),
        ];
    }

    /** Projected price path as [bars ahead, price] points for the chart. */
    private static function path(bool $long, float $price, float $entry, array $targets, float $atr): array
    {
        $sign = $long ? 1 : -1;
        $bars = static fn (float $a, float $b) => max(3, abs($a - $b) / $atr * 1.6);
        $pts = [[0, $price]];
        $x = 0.0;
        if (abs($price - $entry) > 0.4 * $atr) {
            $x += $bars($price, $entry);
            $pts[] = [$x, $entry];
            $from = $entry;
        } else {
            $dip = $price - $sign * 0.6 * $atr;
            $x += 3;
            $pts[] = [$x, $dip];
            $from = $dip;
        }
        $x += $bars($from, $targets[0]);
        $pts[] = [$x, $targets[0]];
        $pull = $targets[0] - $sign * abs($targets[0] - $from) * 0.38;
        $x += $bars($targets[0], $pull) * 0.8;
        $pts[] = [$x, $pull];
        $x += $bars($pull, $targets[1]);
        $pts[] = [$x, $targets[1]];
        return $pts;
    }

    /** @return array<string, callable> */
    private function plugins(): array
    {
        if ($this->pluginDir === '' || !is_dir($this->pluginDir)) {
            return [];
        }
        $out = [];
        foreach (glob($this->pluginDir . '/*.php') ?: [] as $file) {
            if (str_starts_with(basename($file), '_')) {
                continue;
            }
            $fn = require $file;
            if (is_callable($fn)) {
                $out[basename($file, '.php')] = $fn;
            }
        }
        return $out;
    }
}

}

namespace App\Analysis {

/**
 * Classic indicators. Every function returns an array aligned with the input
 * (index i = value at candle i, null while there is not enough history).
 */
final class Indicators
{
    public static function sma(array $values, int $period): array
    {
        $out = array_fill(0, count($values), null);
        $sum = 0.0;
        foreach ($values as $i => $v) {
            $sum += $v;
            if ($i >= $period) {
                $sum -= $values[$i - $period];
            }
            if ($i >= $period - 1) {
                $out[$i] = $sum / $period;
            }
        }
        return $out;
    }

    public static function ema(array $values, int $period): array
    {
        $n = count($values);
        $out = array_fill(0, $n, null);
        if ($n < $period) {
            return $out;
        }
        $k = 2 / ($period + 1);
        $prev = array_sum(array_slice($values, 0, $period)) / $period;
        $out[$period - 1] = $prev;
        for ($i = $period; $i < $n; $i++) {
            $prev = $values[$i] * $k + $prev * (1 - $k);
            $out[$i] = $prev;
        }
        return $out;
    }

    /** Wilder's RSI */
    public static function rsi(array $closes, int $period = 14): array
    {
        $n = count($closes);
        $out = array_fill(0, $n, null);
        if ($n <= $period) {
            return $out;
        }
        $gain = 0.0;
        $loss = 0.0;
        for ($i = 1; $i <= $period; $i++) {
            $d = $closes[$i] - $closes[$i - 1];
            $gain += max($d, 0);
            $loss += max(-$d, 0);
        }
        $gain /= $period;
        $loss /= $period;
        $out[$period] = $loss == 0.0 ? 100.0 : 100 - 100 / (1 + $gain / $loss);
        for ($i = $period + 1; $i < $n; $i++) {
            $d = $closes[$i] - $closes[$i - 1];
            $gain = ($gain * ($period - 1) + max($d, 0)) / $period;
            $loss = ($loss * ($period - 1) + max(-$d, 0)) / $period;
            $out[$i] = $loss == 0.0 ? 100.0 : 100 - 100 / (1 + $gain / $loss);
        }
        return $out;
    }

    /** Wilder's ATR */
    public static function atr(array $highs, array $lows, array $closes, int $period = 14): array
    {
        $n = count($closes);
        $out = array_fill(0, $n, null);
        if ($n <= $period) {
            return $out;
        }
        $tr = [];
        for ($i = 0; $i < $n; $i++) {
            $tr[$i] = $i === 0
                ? $highs[0] - $lows[0]
                : max($highs[$i] - $lows[$i], abs($highs[$i] - $closes[$i - 1]), abs($lows[$i] - $closes[$i - 1]));
        }
        $prev = array_sum(array_slice($tr, 1, $period)) / $period;
        $out[$period] = $prev;
        for ($i = $period + 1; $i < $n; $i++) {
            $prev = ($prev * ($period - 1) + $tr[$i]) / $period;
            $out[$i] = $prev;
        }
        return $out;
    }

    /** @return array{macd: array, signal: array, hist: array} */
    public static function macd(array $closes, int $fast = 12, int $slow = 26, int $signal = 9): array
    {
        $n = count($closes);
        $emaFast = self::ema($closes, $fast);
        $emaSlow = self::ema($closes, $slow);
        $macd = array_fill(0, $n, null);
        $compact = [];
        for ($i = 0; $i < $n; $i++) {
            if ($emaFast[$i] !== null && $emaSlow[$i] !== null) {
                $macd[$i] = $emaFast[$i] - $emaSlow[$i];
                $compact[$i] = $macd[$i];
            }
        }
        $sig = array_fill(0, $n, null);
        $hist = array_fill(0, $n, null);
        if ($compact) {
            $keys = array_keys($compact);
            $sigCompact = self::ema(array_values($compact), $signal);
            foreach ($keys as $j => $i) {
                if ($sigCompact[$j] !== null) {
                    $sig[$i] = $sigCompact[$j];
                    $hist[$i] = $macd[$i] - $sig[$i];
                }
            }
        }
        return ['macd' => $macd, 'signal' => $sig, 'hist' => $hist];
    }

    /** @return array{upper: array, middle: array, lower: array} */
    public static function bollinger(array $closes, int $period = 20, float $mult = 2.0): array
    {
        $n = count($closes);
        $mid = self::sma($closes, $period);
        $up = array_fill(0, $n, null);
        $lo = array_fill(0, $n, null);
        for ($i = $period - 1; $i < $n; $i++) {
            $slice = array_slice($closes, $i - $period + 1, $period);
            $mean = $mid[$i];
            $var = 0.0;
            foreach ($slice as $v) {
                $var += ($v - $mean) ** 2;
            }
            $sd = sqrt($var / $period);
            $up[$i] = $mean + $mult * $sd;
            $lo[$i] = $mean - $mult * $sd;
        }
        return ['upper' => $up, 'middle' => $mid, 'lower' => $lo];
    }

    public static function last(array $series, int $offset = 0)
    {
        $i = count($series) - 1 - $offset;
        return $i >= 0 ? $series[$i] : null;
    }
}

}

namespace App\Analysis {

use App\Market\Series;

/**
 * Price levels: support/resistance zones, order blocks, fair value gaps and liquidity.
 */
final class Levels
{
    /**
     * Clusters swing points into support/resistance zones and scores how important each one is.
     *
     * Strength grows with: number of touches, higher-timeframe swings at the same price,
     * size of the reactions away from the level, role reversal (support <-> resistance)
     * and round psychological numbers.
     *
     * @return array{support: array, resistance: array, key: array{support: array, resistance: array}}
     *   support/resistance = up to 3 nearby zones (used by the engine),
     *   key = only the strongest levels (drawn on the chart)
     */
    public static function zones(Series $s, array $swings, array $htfSwings, float $atr): array
    {
        $price = $s->lastClose();
        $n = $s->count();
        $points = [];
        foreach ($swings as $sw) {
            $points[] = ['price' => $sw['price'], 'i' => $sw['i'], 'htf' => false, 'type' => $sw['type'], 'react' => self::reaction($s, $sw, $atr)];
        }
        foreach ($htfSwings as $sw) {
            $points[] = ['price' => $sw['price'], 'i' => -1, 'htf' => true, 'type' => $sw['type'], 'react' => 0.0];
        }
        usort($points, static fn ($a, $b) => $a['price'] <=> $b['price']);

        $tol = 0.6 * $atr;
        $clusters = [];
        foreach ($points as $p) {
            $last = count($clusters) - 1;
            if ($last >= 0 && $p['price'] - $clusters[$last]['mean'] <= $tol) {
                $c = &$clusters[$last];
                $c['pts'][] = $p;
                $c['mean'] = array_sum(array_column($c['pts'], 'price')) / count($c['pts']);
                unset($c);
                continue;
            }
            $clusters[] = ['mean' => $p['price'], 'pts' => [$p]];
        }

        $zones = [];
        foreach ($clusters as $c) {
            $mainPts = array_values(array_filter($c['pts'], static fn ($p) => !$p['htf']));
            $htf = count($c['pts']) - count($mainPts);
            $touches = count($mainPts);
            $mid = $c['mean'];
            $dist = abs($mid - $price) / $atr;
            if ($dist > 14) {
                continue;
            }
            $prices = array_column($c['pts'], 'price');
            // Role reversal: the level has acted both as a top and as a bottom on this timeframe
            $flip = count(array_unique(array_column($mainPts, 'type'))) === 2;
            $react = 0.0;
            foreach ($mainPts as $p) {
                $react += min($p['react'], 6.0);
            }
            $lastI = $mainPts ? max(array_column($mainPts, 'i')) : 0;
            $strength = $touches * 1.0
                + min($htf, 3) * 2.0
                + min($react, 15.0) * 0.4
                + ($flip ? 2.5 : 0.0)
                + self::roundBonus($mid, $atr)
                + ($lastI / max($n, 1)) * 1.0;

            $lo = max(min($prices), $mid - 0.6 * $atr);
            $hi = min(max($prices), $mid + 0.6 * $atr);
            $zones[] = [
                'mid' => $mid,
                'lo' => min($lo, $mid - 0.18 * $atr),
                'hi' => max($hi, $mid + 0.18 * $atr),
                'touches' => $touches,
                'htf' => $htf > 0,
                'htf_touches' => $htf,
                'flip' => $flip,
                'react' => round($react, 1),
                'score' => round($strength, 2),
                'last_i' => $lastI,
            ];
        }

        $support = array_values(array_filter($zones, static fn ($z) => $z['mid'] < $price));
        $resistance = array_values(array_filter($zones, static fn ($z) => $z['mid'] >= $price));
        $nearby = static function (array $list, bool $below): array {
            usort($list, static fn ($a, $b) => $b['score'] <=> $a['score']);
            $list = array_slice($list, 0, 4);
            usort($list, static fn ($a, $b) => $below ? $b['mid'] <=> $a['mid'] : $a['mid'] <=> $b['mid']);
            return array_slice($list, 0, 3);
        };
        // Key levels: only the clearly dominant ones (close to the strongest level on the chart,
        // tested repeatedly or confirmed on the higher timeframe), max 2 per side.
        $top = $zones ? max(array_column($zones, 'score')) : 0;
        $cut = max(self::KEY_STRENGTH, self::KEY_RELATIVE * $top);
        $key = static function (array $list, bool $below) use ($cut): array {
            usort($list, static fn ($a, $b) => $b['score'] <=> $a['score']);
            $strong = array_values(array_filter($list, static fn ($z) => $z['score'] >= $cut && ($z['touches'] >= 2 || $z['htf_touches'] >= 2)));
            $strong = array_slice($strong, 0, 2);
            usort($strong, static fn ($a, $b) => $below ? $b['mid'] <=> $a['mid'] : $a['mid'] <=> $b['mid']);
            return $strong;
        };
        return [
            'support' => $nearby($support, true),
            'resistance' => $nearby($resistance, false),
            'key' => ['support' => $key($support, true), 'resistance' => $key($resistance, false)],
        ];
    }

    /** A key level needs at least this strength and this share of the strongest level's score. */
    public const KEY_STRENGTH = 9.0;
    public const KEY_RELATIVE = 0.7;

    /** How far price moved away from a swing in the next candles, in ATR. */
    private static function reaction(Series $s, array $sw, float $atr, int $look = 12): float
    {
        $n = $s->count();
        $end = min($n - 1, $sw['i'] + $look);
        if ($end <= $sw['i'] || $atr <= 0) {
            return 0.0;
        }
        if ($sw['type'] === 'high') {
            return ($sw['price'] - min(array_slice($s->l, $sw['i'] + 1, $end - $sw['i']))) / $atr;
        }
        return (max(array_slice($s->h, $sw['i'] + 1, $end - $sw['i'])) - $sw['price']) / $atr;
    }

    /** Bonus for psychological round numbers (e.g. 100,000 / 95,000 for BTC). */
    private static function roundBonus(float $price, float $atr): float
    {
        if ($price <= 0) {
            return 0.0;
        }
        $step = 10 ** floor(log10($price));
        foreach ([[$step, 1.5], [$step / 2, 0.75]] as [$unit, $bonus]) {
            if (abs($price - round($price / $unit) * $unit) <= 0.35 * $atr) {
                return $bonus;
            }
        }
        return 0.0;
    }

    /**
     * Order blocks: the last opposite candle before the impulsive leg that caused a structure break.
     * Only blocks that were never closed through are kept.
     */
    public static function orderBlocks(Series $s, array $events, array $atrSeries): array
    {
        $n = $s->count();
        $blocks = [];
        foreach ($events as $ev) {
            $from = $ev['from'];
            $to = $ev['to'];
            if ($to - $from < 1) {
                continue;
            }
            $bull = $ev['dir'] === 'up';
            // Origin of the impulsive leg = extreme between the broken swing and the break candle.
            $m = $from;
            for ($i = $from; $i <= $to; $i++) {
                if ($bull ? $s->l[$i] < $s->l[$m] : $s->h[$i] > $s->h[$m]) {
                    $m = $i;
                }
            }
            $idx = null;
            for ($i = $m; $i >= max(0, $m - 6); $i--) {
                $isOpposite = $bull ? $s->c[$i] < $s->o[$i] : $s->c[$i] > $s->o[$i];
                if ($isOpposite) {
                    $idx = $i;
                    break;
                }
            }
            $idx ??= $m;
            $atr = $atrSeries[$idx] ?? $atrSeries[$n - 1];
            $top = $s->h[$idx];
            $bottom = $s->l[$idx];
            if ($atr && $top - $bottom > 1.8 * $atr) {
                // Very large candle: use its body so the zone stays tradable.
                $top = max($s->o[$idx], $s->c[$idx]);
                $bottom = min($s->o[$idx], $s->c[$idx]);
            }

            $valid = true;
            $tested = false;
            for ($j = $to + 1; $j < $n; $j++) {
                if ($bull ? $s->c[$j] < $bottom : $s->c[$j] > $top) {
                    $valid = false;
                    break;
                }
                if ($bull ? $s->l[$j] <= $top : $s->h[$j] >= $bottom) {
                    $tested = true;
                }
            }
            if (!$valid) {
                continue;
            }
            $blocks[] = [
                'dir' => $bull ? 'bull' : 'bear',
                'top' => $top,
                'bottom' => $bottom,
                'i' => $idx,
                'event' => $ev['type'],
                'tested' => $tested,
            ];
        }

        // Drop overlapping blocks, keeping the newest.
        usort($blocks, static fn ($a, $b) => $b['i'] <=> $a['i']);
        $kept = [];
        foreach ($blocks as $b) {
            foreach ($kept as $k) {
                if ($k['dir'] === $b['dir'] && $b['bottom'] <= $k['top'] && $b['top'] >= $k['bottom']) {
                    continue 2;
                }
            }
            $kept[] = $b;
        }

        $price = $s->lastClose();
        $bulls = array_values(array_filter($kept, static fn ($b) => $b['dir'] === 'bull' && $b['bottom'] < $price));
        $bears = array_values(array_filter($kept, static fn ($b) => $b['dir'] === 'bear' && $b['top'] > $price));
        usort($bulls, static fn ($a, $b) => $b['top'] <=> $a['top']);
        usort($bears, static fn ($a, $b) => $a['bottom'] <=> $b['bottom']);
        return array_merge(array_slice($bulls, 0, 2), array_slice($bears, 0, 2));
    }

    /** Unfilled fair value gaps (three-candle imbalances) closest to price. */
    public static function fairValueGaps(Series $s, float $atr, int $lookback = 120): array
    {
        $n = $s->count();
        $gaps = [];
        for ($i = max(2, $n - $lookback); $i < $n; $i++) {
            if ($s->l[$i] > $s->h[$i - 2] && $s->l[$i] - $s->h[$i - 2] > 0.25 * $atr) {
                $gaps[] = ['dir' => 'bull', 'top' => $s->l[$i], 'bottom' => $s->h[$i - 2], 'i' => $i - 1];
            } elseif ($s->h[$i] < $s->l[$i - 2] && $s->l[$i - 2] - $s->h[$i] > 0.25 * $atr) {
                $gaps[] = ['dir' => 'bear', 'top' => $s->l[$i - 2], 'bottom' => $s->h[$i], 'i' => $i - 1];
            }
        }
        $open = [];
        foreach ($gaps as $g) {
            $filled = false;
            for ($j = $g['i'] + 2; $j < $n; $j++) {
                if ($g['dir'] === 'bull' ? $s->l[$j] <= $g['bottom'] : $s->h[$j] >= $g['top']) {
                    $filled = true;
                    break;
                }
            }
            if (!$filled) {
                $open[] = $g;
            }
        }
        $price = $s->lastClose();
        usort($open, static fn ($a, $b) => abs(($a['top'] + $a['bottom']) / 2 - $price) <=> abs(($b['top'] + $b['bottom']) / 2 - $price));
        return array_slice($open, 0, 2);
    }

    /**
     * Resting liquidity: equal highs/lows and untouched range extremes.
     * 'buy' side sits above price (stops of shorts), 'sell' side below.
     */
    public static function liquidity(Series $s, array $swings, float $atr, int $lookback = 160): array
    {
        $n = $s->count();
        $price = $s->lastClose();
        $recent = array_values(array_filter($swings, static fn ($p) => $p['i'] >= $n - $lookback));
        $swept = static function (array $p) use ($s, $n): bool {
            for ($j = $p['i'] + 1; $j < $n; $j++) {
                if ($p['type'] === 'high' ? $s->h[$j] > $p['price'] : $s->l[$j] < $p['price']) {
                    return true;
                }
            }
            return false;
        };

        $out = [];
        foreach (['high', 'low'] as $type) {
            $pts = array_values(array_filter($recent, static fn ($p) => $p['type'] === $type && !$swept($p)));
            $c = count($pts);
            for ($a = 0; $a < $c; $a++) {
                for ($b = $a + 1; $b < $c; $b++) {
                    if (abs($pts[$a]['price'] - $pts[$b]['price']) <= 0.2 * $atr) {
                        $lvl = $type === 'high' ? max($pts[$a]['price'], $pts[$b]['price']) : min($pts[$a]['price'], $pts[$b]['price']);
                        $out[] = ['side' => $type === 'high' ? 'buy' : 'sell', 'price' => $lvl, 'kind' => $type === 'high' ? 'EQH' : 'EQL', 'i' => $pts[$a]['i'], 'i2' => $pts[$b]['i']];
                    }
                }
            }
            if ($pts) {
                usort($pts, static fn ($x, $y) => $type === 'high' ? $y['price'] <=> $x['price'] : $x['price'] <=> $y['price']);
                $ext = $pts[0];
                $out[] = ['side' => $type === 'high' ? 'buy' : 'sell', 'price' => $ext['price'], 'kind' => 'swing', 'i' => $ext['i'], 'i2' => $ext['i']];
            }
        }

        // Dedupe nearby levels
        usort($out, static fn ($a, $b) => ($a['kind'] === 'swing') <=> ($b['kind'] === 'swing'));
        $kept = [];
        foreach ($out as $l) {
            if (($l['side'] === 'buy' && $l['price'] <= $price) || ($l['side'] === 'sell' && $l['price'] >= $price)) {
                continue;
            }
            foreach ($kept as $k) {
                if (abs($k['price'] - $l['price']) < 0.4 * $atr) {
                    continue 2;
                }
            }
            $kept[] = $l;
        }
        usort($kept, static fn ($a, $b) => abs($a['price'] - $price) <=> abs($b['price'] - $price));
        $buy = array_values(array_filter($kept, static fn ($l) => $l['side'] === 'buy'));
        $sell = array_values(array_filter($kept, static fn ($l) => $l['side'] === 'sell'));
        return array_merge(array_slice($buy, 0, 2), array_slice($sell, 0, 2));
    }

    /**
     * Largest order-book walls within ±6% of price, bucketed in 0.25% bins.
     */
    public static function walls(?array $book, float $price): array
    {
        if (!$book) {
            return [];
        }
        $bin = $price * 0.0025;
        $out = [];
        foreach (['bids' => 'bid', 'asks' => 'ask'] as $key => $side) {
            $bins = [];
            foreach ($book[$key] as [$p, $q]) {
                if (abs($p - $price) > $price * 0.06) {
                    continue;
                }
                $k = (int) floor($p / $bin);
                $bins[$k] = ($bins[$k] ?? 0) + $p * $q;
            }
            if (count($bins) < 3) {
                continue;
            }
            $vals = array_values($bins);
            sort($vals);
            $median = $vals[intdiv(count($vals), 2)];
            arsort($bins);
            foreach (array_slice($bins, 0, 2, true) as $k => $notional) {
                if ($notional >= 2.5 * $median) {
                    $out[] = ['side' => $side, 'price' => ($k + 0.5) * $bin, 'notional' => $notional];
                }
            }
        }
        return $out;
    }
}

}

namespace App\Analysis {

use App\Market\Series;

/**
 * Swing points, market structure (HH/HL/LH/LL) and structure breaks (BOS / CHoCH).
 */
final class Structure
{
    /**
     * Pivot highs/lows confirmed by $len candles on each side, compressed so highs and lows alternate.
     * @return array<int, array{type:string, i:int, price:float}>
     */
    public static function swings(Series $s, int $len = 3): array
    {
        $n = $s->count();
        $raw = [];
        for ($i = $len; $i < $n - $len; $i++) {
            $isHigh = true;
            $isLow = true;
            for ($k = 1; $k <= $len; $k++) {
                if ($s->h[$i - $k] > $s->h[$i] || $s->h[$i + $k] >= $s->h[$i]) {
                    $isHigh = false;
                }
                if ($s->l[$i - $k] < $s->l[$i] || $s->l[$i + $k] <= $s->l[$i]) {
                    $isLow = false;
                }
            }
            if ($isHigh) {
                $raw[] = ['type' => 'high', 'i' => $i, 'price' => $s->h[$i]];
            }
            if ($isLow) {
                $raw[] = ['type' => 'low', 'i' => $i, 'price' => $s->l[$i]];
            }
        }

        $out = [];
        foreach ($raw as $p) {
            $last = end($out);
            if ($last !== false && $last['type'] === $p['type']) {
                $better = $p['type'] === 'high' ? $p['price'] > $last['price'] : $p['price'] < $last['price'];
                if ($better) {
                    $out[count($out) - 1] = $p;
                }
                continue;
            }
            $out[] = $p;
        }
        return $out;
    }

    /**
     * Walks the candles and records every break of the last confirmed swing.
     * A break in the trend direction is a BOS, a break against it is a CHoCH.
     *
     * @return array{trend:string, events:array, labels:array}
     */
    public static function analyze(Series $s, array $swings, int $len = 3): array
    {
        $n = $s->count();
        $labels = [];
        $prevHigh = null;
        $prevLow = null;
        foreach ($swings as $sw) {
            if ($sw['type'] === 'high') {
                $labels[] = $sw + ['label' => $prevHigh === null ? 'H' : ($sw['price'] > $prevHigh ? 'HH' : 'LH')];
                $prevHigh = $sw['price'];
            } else {
                $labels[] = $sw + ['label' => $prevLow === null ? 'L' : ($sw['price'] > $prevLow ? 'HL' : 'LL')];
                $prevLow = $sw['price'];
            }
        }

        $events = [];
        $trend = 0;
        $lastHigh = null;
        $lastLow = null;
        $si = 0;
        $swingCount = count($swings);
        for ($i = 0; $i < $n; $i++) {
            // A swing becomes usable once its right-hand confirmation candles have closed.
            while ($si < $swingCount && $swings[$si]['i'] + $len <= $i) {
                $sw = $swings[$si++];
                if ($sw['type'] === 'high') {
                    $lastHigh = $sw + ['broken' => false];
                } else {
                    $lastLow = $sw + ['broken' => false];
                }
            }
            if ($lastHigh !== null && !$lastHigh['broken'] && $s->c[$i] > $lastHigh['price']) {
                $events[] = ['type' => $trend === -1 ? 'CHoCH' : 'BOS', 'dir' => 'up', 'level' => $lastHigh['price'], 'from' => $lastHigh['i'], 'to' => $i];
                $lastHigh['broken'] = true;
                $trend = 1;
            }
            if ($lastLow !== null && !$lastLow['broken'] && $s->c[$i] < $lastLow['price']) {
                $events[] = ['type' => $trend === 1 ? 'CHoCH' : 'BOS', 'dir' => 'down', 'level' => $lastLow['price'], 'from' => $lastLow['i'], 'to' => $i];
                $lastLow['broken'] = true;
                $trend = -1;
            }
        }

        // Combine the last break direction with the latest swing sequence.
        $lastLabels = array_slice($labels, -4);
        $bull = 0;
        $bear = 0;
        foreach ($lastLabels as $lb) {
            if (in_array($lb['label'], ['HH', 'HL'], true)) {
                $bull++;
            } elseif (in_array($lb['label'], ['LH', 'LL'], true)) {
                $bear++;
            }
        }
        $name = 'range';
        if ($trend === 1 && $bull >= $bear) {
            $name = 'bullish';
        } elseif ($trend === -1 && $bear >= $bull) {
            $name = 'bearish';
        } elseif ($bull >= 3) {
            $name = 'bullish';
        } elseif ($bear >= 3) {
            $name = 'bearish';
        }

        return ['trend' => $name, 'break_dir' => $trend, 'events' => $events, 'labels' => $labels];
    }

    /**
     * Regular RSI divergence on the two most recent swing lows/highs.
     * @return array{type:string, a:array, b:array}|null
     */
    public static function rsiDivergence(Series $s, array $swings, array $rsi, int $maxAge = 30): ?array
    {
        $n = $s->count();
        $lows = array_values(array_filter($swings, static fn ($p) => $p['type'] === 'low'));
        $highs = array_values(array_filter($swings, static fn ($p) => $p['type'] === 'high'));
        $check = static function (array $pts, string $kind) use ($rsi, $n, $maxAge): ?array {
            $c = count($pts);
            if ($c < 2) {
                return null;
            }
            [$a, $b] = [$pts[$c - 2], $pts[$c - 1]];
            if ($n - 1 - $b['i'] > $maxAge || $rsi[$a['i']] === null || $rsi[$b['i']] === null) {
                return null;
            }
            if ($kind === 'bullish' && $b['price'] < $a['price'] && $rsi[$b['i']] > $rsi[$a['i']] + 2) {
                return ['type' => 'bullish', 'a' => $a, 'b' => $b];
            }
            if ($kind === 'bearish' && $b['price'] > $a['price'] && $rsi[$b['i']] < $rsi[$a['i']] - 2) {
                return ['type' => 'bearish', 'a' => $a, 'b' => $b];
            }
            return null;
        };
        $bull = $check($lows, 'bullish');
        $bear = $check($highs, 'bearish');
        if ($bull && $bear) {
            return $bull['b']['i'] > $bear['b']['i'] ? $bull : $bear;
        }
        return $bull ?? $bear;
    }
}

}

namespace App {

use App\Ai\Gemini;
use App\Analysis\Analyzer;
use App\Market\MarketData;
use App\Render\Caption;
use App\Render\Card;

/**
 * Full pipeline for one request:
 * engine analysis -> Gemini review (sees numbers + chart) -> validation -> final chart + caption.
 */
final class AnalysisService
{
    private MarketData $market;
    private Analyzer $analyzer;
    private Gemini $gemini;
    private Card $card;
    private string $outDir;
    private Texts $texts;

    /** Result of the last Gemini call: 'ok', 'off' or an error message. */
    public string $aiStatus = 'off';

    public function __construct(private array $config, private string $brainNotes = '', ?Texts $texts = null)
    {
        $this->market = new MarketData($config['market'] ?? [], app_storage('cache'));
        $this->analyzer = new Analyzer($this->market, app_brain(), HUB_ROOT . '/brain/indicators');
        $this->gemini = new Gemini((string) ($config['gemini']['api_key'] ?? ''), $config['gemini']['model'] ?? 'gemini-3.5-flash', (string) ($config['gemini']['proxy'] ?? ''));
        $this->card = new Card($config['brand'] ?? []);
        $this->outDir = app_storage('out');
        $this->texts = $texts ?? new Texts(new Storage(app_storage() . '/bot.sqlite'));
    }

    /**
     * @return array{image: string, caption: string, extra: string, analysis: array}
     */
    public function analyze(string $base, string $tf): array
    {
        $a = $this->analyzer->run($base, $tf);
        $a['ai'] = ['used' => false];
        $a['exchange_label'] = trim(strip_tags($this->texts->get('exchange_label'))) ?: 'OURBIT';

        if ($this->gemini->enabled()) {
            $draft = $this->outDir . '/draft_' . $a['symbol'] . '_' . getmypid() . '.jpg';
            $this->card->render($a, $draft, false);
            $ai = $this->gemini->analyze($this->facts($a), $this->candles($a), $draft, $this->brainNotes);
            @unlink($draft);
            $this->aiStatus = $ai !== null ? 'ok' : ($this->gemini->lastError ?: 'unknown error');
            if ($ai !== null) {
                $a = $this->mergeAi($a, $ai);
            }
        }

        $image = $this->outDir . '/' . $a['symbol'] . '_' . $a['timeframe'] . '_' . date('Ymd_His') . '.png';
        $this->card->render($a, $image);
        $this->cleanup();
        [$caption, $extra] = Caption::build($a, $this->texts);

        return ['image' => $image, 'caption' => $caption, 'extra' => $extra, 'analysis' => $a];
    }

    /**
     * Accepts Gemini's plan only if it is internally consistent; otherwise keeps the engine plan.
     */
    private function mergeAi(array $a, array $ai): array
    {
        $atr = $a['atr'];
        $price = $a['price'];
        $side = ($ai['side'] ?? '') === 'short' ? 'short' : 'long';
        $sign = $side === 'long' ? 1 : -1;
        $lo = (float) ($ai['entry_low'] ?? 0);
        $hi = (float) ($ai['entry_high'] ?? 0);
        if ($lo > $hi) {
            [$lo, $hi] = [$hi, $lo];
        }
        $stop = (float) ($ai['stop'] ?? 0);
        $targets = array_values(array_filter(array_map('floatval', (array) ($ai['targets'] ?? [])), static fn ($t) => $t > 0));
        usort($targets, static fn ($x, $y) => ($x <=> $y) * $sign);
        $targets = array_slice($targets, 0, 3);
        if (count($targets) === 2) {
            $targets[] = $targets[1] + ($targets[1] - $targets[0]);
        }

        $mid = ($lo + $hi) / 2;
        $risk = ($mid - $stop) * $sign;
        $problems = [];
        if ($lo <= 0 || $hi <= 0 || count($targets) < 3) {
            $problems[] = 'missing levels';
        } else {
            if (($side === 'long' ? $lo - $stop : $stop - $hi) <= 0) {
                $problems[] = 'stop on wrong side';
            }
            if ($risk < 0.25 * $atr || $risk > 6 * $atr) {
                $problems[] = 'risk size';
            }
            if (($targets[0] - ($side === 'long' ? $hi : $lo)) * $sign <= 0) {
                $problems[] = 'target on wrong side';
            }
            if ($risk > 0 && ($targets[0] - $mid) * $sign / $risk < 0.8) {
                $problems[] = 'first target RR < 0.8';
            }
            if (abs($mid - $price) > 8 * $atr || abs($targets[2] - $price) > 15 * $atr) {
                $problems[] = 'levels too far from price';
            }
        }

        $planFromAi = !$problems;
        if ($planFromAi) {
            // Keep the AI's first target; space the others at least 0.6 ATR apart,
            // borrowing engine targets (or R multiples) when the AI clustered them.
            $pool = array_merge(array_slice($targets, 1), $a['plan']['targets']);
            usort($pool, static fn ($x, $y) => ($x <=> $y) * $sign);
            $final = [$targets[0]];
            foreach ($pool as $t) {
                if (count($final) < 3 && ($t - end($final)) * $sign >= 0.6 * $atr) {
                    $final[] = $t;
                }
            }
            while (count($final) < 3) {
                $final[] = end($final) + $sign * max($risk, 0.8 * $atr);
            }
            $targets = $final;
            $a['plan'] = Analyzer::finalizePlan($side, $lo, $hi, $stop, $targets, $price, $atr) + ['entry_kind' => 'ai'];
            $a['bias'] = $side;
        } else {
            app_log('gemini plan rejected (' . implode(', ', $problems) . ') ' . json_encode(['side' => $side, 'entry' => [$lo, $hi], 'stop' => $stop, 'targets' => $targets]));
        }

        // Use the AI text only when it describes the plan we are actually publishing.
        $textMatches = $side === $a['plan']['side'];
        $conf = (int) ($ai['confidence'] ?? $a['confidence']);
        $a['ai'] = [
            'used' => $textMatches,
            'model' => $ai['model'] ?? '',
            'plan_from_ai' => $planFromAi,
            'summary' => $textMatches ? trim((string) ($ai['summary'] ?? '')) : '',
            'invalidation' => $textMatches ? trim((string) ($ai['invalidation'] ?? '')) : '',
            'reasons' => $textMatches ? array_values(array_filter(array_map('trim', (array) ($ai['reasons'] ?? [])))) : [],
        ];
        if ($textMatches) {
            // Blend the AI confidence with the engine's so a single source cannot dominate.
            $a['confidence'] = (int) round(max(5, min(95, 0.6 * $conf + 0.4 * $a['confidence'])));
        }
        return $a;
    }

    /** Compact engine output for the prompt. */
    private function facts(array $a): array
    {
        $r = static function (?float $p): ?float {
            if ($p === null || $p <= 0) {
                return $p;
            }
            return round($p, max(2, 3 - (int) floor(log10($p))) + 1);
        };
        $plan = $a['plan'];
        return [
            'symbol' => $a['symbol'],
            'timeframe' => $a['timeframe'],
            'higher_tf' => $a['htf'],
            'lower_tf' => $a['ltf'],
            'price' => $r($a['price']),
            'change_24h_pct' => round($a['change24h'], 2),
            'high_24h' => $r($a['high24h']),
            'low_24h' => $r($a['low24h']),
            'atr14' => $r($a['atr']),
            'rsi14' => round($a['rsi'], 1),
            'macd_hist' => $a['macd_hist'] !== null ? $r(abs($a['macd_hist'])) * ($a['macd_hist'] < 0 ? -1 : 1) : null,
            'ema' => array_map($r, $a['ema']),
            'trend' => $a['trend'],
            'structure_breaks' => array_map(static fn ($e) => ['type' => $e['type'], 'dir' => $e['dir'], 'level' => $r($e['level']), 'bars_ago' => $a['series']->count() - 1 - $e['to']], $a['events']),
            'swings' => array_map(static fn ($l) => ['label' => $l['label'], 'price' => $r($l['price']), 'bars_ago' => $a['series']->count() - 1 - $l['i']], array_slice($a['labels'], -8)),
            'support_zones' => array_map(static fn ($z) => ['low' => $r($z['lo']), 'high' => $r($z['hi']), 'touches' => $z['touches'], 'higher_tf' => $z['htf'], 'strength' => $z['score']], $a['zones']['support']),
            'resistance_zones' => array_map(static fn ($z) => ['low' => $r($z['lo']), 'high' => $r($z['hi']), 'touches' => $z['touches'], 'higher_tf' => $z['htf'], 'strength' => $z['score']], $a['zones']['resistance']),
            'key_levels' => [
                'support' => array_map(static fn ($z) => $r($z['mid']), $a['key_levels']['support']),
                'resistance' => array_map(static fn ($z) => $r($z['mid']), $a['key_levels']['resistance']),
            ],
            'order_blocks' => array_map(static fn ($o) => ['dir' => $o['dir'], 'top' => $r($o['top']), 'bottom' => $r($o['bottom']), 'tested' => $o['tested'], 'from' => $o['event']], $a['order_blocks']),
            'fair_value_gaps' => array_map(static fn ($g) => ['dir' => $g['dir'], 'top' => $r($g['top']), 'bottom' => $r($g['bottom'])], $a['fvg']),
            'liquidity' => array_map(static fn ($l) => ['side' => $l['side'] === 'buy' ? 'buy_side_above' : 'sell_side_below', 'price' => $r($l['price']), 'kind' => $l['kind']], $a['liquidity']),
            'orderbook_walls' => array_map(static fn ($w) => ['side' => $w['side'], 'price' => $r($w['price']), 'usd' => (int) $w['notional']], $a['walls']),
            'rsi_divergence' => $a['divergence']['type'] ?? null,
            'engine_score' => $a['score'],
            'engine_reasons' => array_map(static fn ($x) => $x['fa'], array_slice($a['reasons'], 0, 8)),
            'draft_plan' => [
                'side' => $plan['side'],
                'entry_low' => $r($plan['entry'][0]),
                'entry_high' => $r($plan['entry'][1]),
                'stop' => $r($plan['stop']),
                'targets' => array_map($r, $plan['targets']),
            ],
        ];
    }

    private function candles(array $a): array
    {
        $rows = static function ($s, int $n): array {
            $out = [];
            $count = $s->count();
            for ($i = max(0, $count - $n); $i < $count; $i++) {
                $out[] = [$s->o[$i], $s->h[$i], $s->l[$i], $s->c[$i], round($s->v[$i])];
            }
            return $out;
        };
        return [$a['timeframe'] => $rows($a['series'], 80), $a['htf'] => $rows($a['htf_series'], 40)];
    }

    /** Removes images older than a day. */
    private function cleanup(): void
    {
        foreach (glob($this->outDir . '/*.{png,jpg}', GLOB_BRACE) ?: [] as $f) {
            if (filemtime($f) < time() - 86400) {
                @unlink($f);
            }
        }
    }
}

}

namespace App {

use App\Market\MarketUnavailable;
use App\Market\SymbolNotFound;
use App\Support\Fa;
use App\Support\SymbolParser;
use App\Telegram\Client;

/**
 * Routes Telegram updates: channel direct messages (and optionally private chats)
 * get analyses within the weekly quota on the allowed days; admins get commands.
 */
final class Bot
{
    private Client $tg;
    private Storage $db;
    private Texts $texts;

    public function __construct(private array $config, ?Client $client = null, ?Storage $storage = null)
    {
        $this->tg = $client ?? new Client((string) $config['bot_token']);
        $this->db = $storage ?? new Storage(app_storage() . '/bot.sqlite');
        $this->texts = new Texts($this->db);
    }

    public function handle(array $update): void
    {
        if (isset($update['update_id']) && !$this->db->claimUpdate((int) $update['update_id'])) {
            return;
        }
        if (isset($update['callback_query'])) {
            $cq = $update['callback_query'];
            $data = (string) ($cq['data'] ?? '');
            if ($this->isAdmin((int) ($cq['from']['id'] ?? 0)) && (str_starts_with($data, 'an:') || str_starts_with($data, 'p:'))) {
                $this->panel()->callback($cq);
            } else {
                $this->tg->answerCallback((string) $cq['id']);
            }
            return;
        }
        $msg = $update['message'] ?? null;
        if (!is_array($msg) || empty($msg['from']) || !empty($msg['from']['is_bot'])) {
            return;
        }
        $chat = $msg['chat'];
        $from = $msg['from'];
        $userId = (int) $from['id'];
        $isAdmin = $this->isAdmin($userId);
        $isDm = !empty($chat['is_direct_messages']);
        $isPrivate = ($chat['type'] ?? '') === 'private';
        if (!$isDm && !$isPrivate) {
            return;
        }
        // In the channel's direct messages, skip messages posted by the channel itself / its admins.
        if ($isDm && (!empty($msg['sender_chat']) || $isAdmin)) {
            return;
        }

        $to = [
            'chat_id' => $chat['id'],
            'topic_id' => $msg['direct_messages_topic']['topic_id'] ?? null,
            'reply_to' => $msg['message_id'] ?? null,
        ];
        $text = trim((string) ($msg['text'] ?? $msg['caption'] ?? ''));
        $this->db->touchUser($from);

        if ($isPrivate && $isAdmin) {
            $to['reply_to'] = null;
            if ($this->panel()->handleState($to, $msg)) {
                return;
            }
            if (str_starts_with($text, '/')) {
                $this->adminCommand($to, $text);
                return;
            }
        }
        if ($isPrivate && !$isAdmin && empty($this->config['allow_private_chat'])) {
            $this->tg->sendMessage($to, '🙏 برای دریافت تحلیل به دایرکت کانال ' . htmlspecialchars($this->config['brand']['handle'] ?? '') . ' پیام بدهید.');
            return;
        }
        $this->userMessage($to, $from, $text, $isPrivate, $isAdmin);
    }

    // ---------------------------------------------------------------- users

    private function userMessage(array $to, array $from, string $text, bool $isPrivate, bool $isAdmin): void
    {
        $lower = mb_strtolower($text);
        if (str_starts_with($text, '/start') || $text === 'شروع') {
            $this->tg->sendMessage($to, $this->texts->render('welcome', ['name' => htmlspecialchars((string) ($from['first_name'] ?? ''))]));
            return;
        }
        if ($text === '/help' || str_contains($lower, 'راهنما')) {
            $this->tg->sendMessage($to, $this->helpText());
            return;
        }
        if (preg_match('/سهمیه|اعتبار من|چند\s*تا\s*(?:تحلیل\s*)?(?:مونده|مانده)/u', $text)) {
            $this->tg->sendMessage($to, $this->quotaText((int) $from['id']));
            return;
        }

        $req = SymbolParser::parse($text);
        if ($req === null) {
            if ($isPrivate) {
                $this->tg->sendMessage($to, $this->texts->render('private_hint'));
            }
            // In channel DMs, anything that is not an analysis request is left for the admin.
            return;
        }

        $user = $this->db->user((int) $from['id']);
        if (!empty($user['banned'])) {
            return;
        }
        if ($this->db->get('paused') === '1' && !$isAdmin) {
            $this->tg->sendMessage($to, $this->texts->render('paused'));
            return;
        }
        if (!$isAdmin && !$this->isAnalysisDay()) {
            $this->tg->sendMessage($to, $this->closedText());
            return;
        }

        $tf = $req['tf'] ?? ($this->config['market']['default_timeframe'] ?? '4h');
        if (!in_array($tf, SymbolParser::TIMEFRAMES, true)) {
            $tf = '4h';
        }
        $this->runAnalysis($to, $from, $req['base'], $tf, $isAdmin);
    }

    /**
     * @param bool $publish true = post to the channel set in /panel (if any) instead of replying here
     */
    private function runAnalysis(array $to, array $from, string $base, string $tf, bool $unlimited, bool $publish = true): void
    {
        $userId = (int) $from['id'];
        $period = $this->periodKey();
        $limit = $unlimited ? -1 : AdminPanel::quota($this->config, $this->db);
        $usageId = $this->db->reserve($userId, $period, $limit, $base, $tf);
        if ($usageId === null) {
            $this->tg->sendMessage($to, $this->quotaText($userId, true));
            return;
        }

        $wait = $this->tg->sendMessage($to, $this->texts->render('waiting', ['symbol' => htmlspecialchars($base), 'tf' => Fa::tf($tf)]));
        $ok = false;
        try {
            $config = $this->config;
            if (!AdminPanel::geminiOn($config, $this->db)) {
                $config['gemini']['api_key'] = '';
            }
            $service = new AnalysisService($config, (string) $this->db->get('brain_notes', ''), $this->texts);
            $result = $service->analyze($base, $tf);
            if ($config['gemini']['api_key'] !== '') {
                $this->db->set('gemini_status', date('Y-m-d H:i') . ' | ' . $service->aiStatus);
            }
            $userLimit = $limit + (int) ($this->db->user($userId)['bonus'] ?? 0);
            $remaining = $unlimited ? null : max(0, $userLimit - $this->db->used($userId, $period));
            $remainingNote = $remaining !== null
                ? $this->texts->render('quota_left', ['left' => Fa::digits((string) $remaining), 'limit' => Fa::digits((string) $userLimit)])
                : '';

            $channel = $publish ? AdminPanel::channel($this->db) : null;
            if ($channel !== null) {
                $post = $this->deliver(['chat_id' => $channel['id']], $result['image'], $result['caption'], $result['extra']);
                if ($post !== null) {
                    $ok = true;
                    if (AdminPanel::dmNotice($this->db)) {
                        $link = $this->postLink($channel, (int) ($post['message_id'] ?? 0));
                        $this->tg->sendMessage($to, $this->texts->render('published', [
                            'symbol' => htmlspecialchars($base),
                            'tf' => Fa::tf($tf),
                            'post_link' => $link !== '' ? '<a href="' . htmlspecialchars($link) . '">مشاهده تحلیل</a>' : '',
                            'remaining' => $remaining !== null ? Fa::digits((string) $remaining) : '∞',
                        ]));
                    }
                } else {
                    $this->notifyAdmins('⚠️ ارسال تحلیل به کانال <b>' . htmlspecialchars((string) $channel['title']) . '</b> ناموفق بود؛ تحلیل در دایرکت کاربر ارسال شد. دسترسی ادمین ربات در کانال را بررسی کنید (/panel).');
                }
            }
            if (!$ok) {
                $caption = $result['caption'];
                $extra = $result['extra'];
                if ($remainingNote !== '') {
                    if ($caption !== '' && Render\Caption::length($caption . "\n\n" . $remainingNote) <= 1024) {
                        $caption .= "\n\n" . $remainingNote;
                    } else {
                        $extra = trim($extra . "\n\n" . $remainingNote);
                    }
                }
                $ok = $this->deliver($to, $result['image'], $caption, $extra) !== null;
            }
            if ($ok) {
                $this->adminLog($from, $result);
            }
        } catch (SymbolNotFound $e) {
            $this->tg->sendMessage($to, $this->texts->render('not_found', ['symbol' => htmlspecialchars($base)]));
        } catch (MarketUnavailable $e) {
            $this->tg->sendMessage($to, $this->texts->render('error'));
            app_log('market unavailable: ' . $e->getMessage());
        } catch (\Throwable $e) {
            app_log('analysis failed: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
            $this->tg->sendMessage($to, $this->texts->render('error'));
        } finally {
            // Failed analyses do not use up the quota.
            $this->db->finish($usageId, $ok);
            if ($wait !== null && isset($wait['message_id'])) {
                $this->tg->deleteMessage($to['chat_id'], (int) $wait['message_id']);
            }
        }
    }

    /** Sends the chart with its caption (+ follow-up text). Returns the photo message or null. */
    private function deliver(array $to, string $image, string $caption, string $extra): ?array
    {
        $sent = $this->tg->sendPhoto($to, $image, $caption);
        if ($sent === null && $caption !== '') {
            // Retry without HTML in case the formatting was rejected
            $sent = $this->tg->sendPhoto($to, $image, html_entity_decode(strip_tags($caption), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        }
        if ($sent !== null && $extra !== '') {
            $this->tg->sendMessage(['chat_id' => $to['chat_id'], 'topic_id' => $to['topic_id'] ?? null, 'reply_to' => $sent['message_id'] ?? null], $extra);
        }
        return $sent;
    }

    private function postLink(array $channel, int $messageId): string
    {
        if ($messageId <= 0) {
            return '';
        }
        if (!empty($channel['username'])) {
            return 'https://t.me/' . $channel['username'] . '/' . $messageId;
        }
        $id = (string) $channel['id'];
        return str_starts_with($id, '-100') ? 'https://t.me/c/' . substr($id, 4) . '/' . $messageId : '';
    }

    private function notifyAdmins(string $html): void
    {
        foreach ($this->config['admin_ids'] ?? [] as $admin) {
            $this->tg->sendMessage(['chat_id' => $admin], $html);
        }
    }

    private function panel(): AdminPanel
    {
        return new AdminPanel($this->config, $this->tg, $this->db);
    }

    // ---------------------------------------------------------------- admin

    private function adminCommand(array $to, string $text): void
    {
        $parts = preg_split('/\s+/u', trim($text), 3);
        $cmd = strtolower(preg_replace('/@\w+$/', '', $parts[0]));
        $arg1 = $parts[1] ?? '';
        $arg2 = $parts[2] ?? '';
        $period = $this->periodKey();

        switch ($cmd) {
            case '/start':
            case '/panel':
                $this->panel()->show($to);
                return;

            case '/help':
            case '/admin':
                $this->tg->sendMessage($to, $this->adminHelp());
                return;

            case '/test':
            case '/analyze':
                $req = SymbolParser::parse('تحلیل ' . $arg1 . ' ' . $arg2);
                if ($req === null) {
                    $this->tg->sendMessage($to, 'مثال: <code>/test BTC 4h</code>');
                    return;
                }
                $tf = $req['tf'] ?? ($this->config['market']['default_timeframe'] ?? '4h');
                $this->runAnalysis($to, ['id' => $this->config['admin_ids'][0] ?? 0, 'first_name' => 'admin'], $req['base'], $tf, true, false);
                return;

            case '/stats':
                $s = $this->db->stats($period);
                $top = implode('، ', array_map(static fn ($r) => $r['symbol'] . ' (' . $r['n'] . ')', $s['top'])) ?: '-';
                $this->tg->sendMessage($to, "📊 <b>آمار ربات</b>\n"
                    . 'کاربران: ' . $s['users'] . "\n"
                    . 'تحلیل‌های این دوره: ' . $s['period_done'] . ' (برای ' . $s['period_users'] . " نفر)\n"
                    . 'کل تحلیل‌ها: ' . $s['total_done'] . "\n"
                    . 'پرتکرارها: ' . htmlspecialchars($top) . "\n"
                    . 'وضعیت: ' . ($this->db->get('paused') === '1' ? '⏸ متوقف' : '✅ فعال') . "\n"
                    . 'امروز روز تحلیل است؟ ' . ($this->isAnalysisDay() ? 'بله' : 'خیر'));
                return;

            case '/user':
            case '/quota':
                $u = $this->db->findUser($arg1);
                if (!$u) {
                    $this->tg->sendMessage($to, 'کاربر پیدا نشد. مثال: <code>/user 123456789</code> یا <code>/user @username</code>');
                    return;
                }
                $this->tg->sendMessage($to, '👤 ' . htmlspecialchars(trim(($u['first_name'] ?? '') . ' @' . ($u['username'] ?? ''))) . ' (<code>' . $u['user_id'] . "</code>)\n"
                    . 'استفاده در این دوره: ' . $this->db->used((int) $u['user_id'], $period) . ' از ' . (AdminPanel::quota($this->config, $this->db) + (int) $u['bonus']) . "\n"
                    . 'مسدود: ' . ($u['banned'] ? 'بله' : 'خیر'));
                return;

            case '/addquota':
            case '/bonus':
                $u = $this->db->findUser($arg1);
                $n = (int) ($arg2 ?: 1);
                if (!$u) {
                    $this->tg->sendMessage($to, 'مثال: <code>/addquota 123456789 2</code>');
                    return;
                }
                $this->db->addBonus((int) $u['user_id'], $n);
                $this->tg->sendMessage($to, "✅ {$n} تحلیل اضافه به کاربر <code>{$u['user_id']}</code> داده شد.");
                return;

            case '/reset':
                $u = $this->db->findUser($arg1);
                if (!$u) {
                    $this->tg->sendMessage($to, 'مثال: <code>/reset 123456789</code>');
                    return;
                }
                $this->db->resetUsage((int) $u['user_id'], $period);
                $this->tg->sendMessage($to, "♻️ سهمیه کاربر <code>{$u['user_id']}</code> در این دوره صفر شد.");
                return;

            case '/ban':
            case '/unban':
                $u = $this->db->findUser($arg1);
                if (!$u) {
                    $this->tg->sendMessage($to, 'مثال: <code>' . $cmd . ' 123456789</code>');
                    return;
                }
                $this->db->setBanned((int) $u['user_id'], $cmd === '/ban');
                $this->tg->sendMessage($to, $cmd === '/ban' ? '🚫 کاربر مسدود شد.' : '✅ کاربر آزاد شد.');
                return;

            case '/off':
                $this->db->set('paused', '1');
                $this->tg->sendMessage($to, '⏸ ربات برای کاربران متوقف شد. برای فعال‌سازی: /on');
                return;

            case '/on':
                $this->db->set('paused', null);
                $this->tg->sendMessage($to, '✅ ربات فعال شد.');
                return;

            case '/brain':
                $notes = trim(mb_substr($text, mb_strlen($parts[0])));
                if ($notes === '') {
                    $cur = (string) $this->db->get('brain_notes', '');
                    $this->tg->sendMessage($to, "🧠 <b>دستورالعمل فعلی مغز ربات:</b>\n" . ($cur !== '' ? htmlspecialchars($cur) : '(خالی)') . "\n\nبرای افزودن: <code>/brain متن دستورالعمل</code>\nبرای پاک کردن: /brain_clear");
                    return;
                }
                $cur = trim((string) $this->db->get('brain_notes', ''));
                $this->db->set('brain_notes', trim($cur . "\n- " . $notes));
                $this->tg->sendMessage($to, "🧠 به مغز ربات اضافه شد. از تحلیل بعدی Gemini این دستورالعمل را رعایت می‌کند.");
                return;

            case '/logs':
                $file = app_storage('logs') . '/bot-' . date('Y-m-d') . '.log';
                $lines = is_file($file) ? array_slice(file($file, FILE_IGNORE_NEW_LINES) ?: [], -25) : [];
                $body = $lines ? implode("\n", $lines) : '(امروز خطایی ثبت نشده)';
                $this->tg->sendMessage($to, "🧾 <b>آخرین لاگ‌های امروز</b>\n<pre>" . htmlspecialchars(mb_substr($body, -3500)) . '</pre>');
                return;

            case '/brain_clear':
                $this->db->set('brain_notes', null);
                $this->tg->sendMessage($to, '🧠 دستورالعمل‌های مغز ربات پاک شد.');
                return;
        }
        $this->tg->sendMessage($to, 'دستور ناشناخته. /help');
    }

    private function adminLog(array $from, array $result): void
    {
        if ($this->db->get('admin_log') !== 'on') {
            return;
        }
        $a = $result['analysis'];
        if ($this->isAdmin((int) $from['id'])) {
            return;
        }
        $who = htmlspecialchars(trim(($from['first_name'] ?? '') . (isset($from['username']) ? ' @' . $from['username'] : '')));
        $text = '📝 تحلیل <b>' . $a['base'] . '</b> ' . strtoupper($a['timeframe']) . ' برای ' . $who . ' (<code>' . $from['id'] . '</code>)'
            . "\n" . ($a['plan']['side'] === 'long' ? '🟢 Long' : '🔴 Short') . ' | اعتبار ' . $a['confidence'] . '% | منبع ' . $a['source']
            . ' | Gemini: ' . (!empty($a['ai']['used']) ? ($a['ai']['plan_from_ai'] ? 'پلن + متن' : 'فقط متن') : 'خیر');
        foreach ($this->config['admin_ids'] ?? [] as $admin) {
            $this->tg->sendMessage(['chat_id' => $admin], $text);
        }
    }

    // ---------------------------------------------------------------- helpers

    private function isAdmin(int $id): bool
    {
        return in_array($id, array_map('intval', $this->config['admin_ids'] ?? []), true);
    }

    private function isAnalysisDay(): bool
    {
        return in_array((int) date('w'), AdminPanel::days($this->config, $this->db), true);
    }

    /** Quota period id; weeks start on Saturday. */
    public function periodKey(?int $ts = null): string
    {
        $ts ??= time();
        return match ($this->config['quota_period'] ?? 'week') {
            'day' => 'd:' . date('Y-m-d', $ts),
            'lifetime' => 'all',
            default => 'w:' . date('Y-m-d', strtotime('-' . (((int) date('w', $ts) + 1) % 7) . ' days', $ts)),
        };
    }

    private function dayNames(): string
    {
        $days = AdminPanel::days($this->config, $this->db);
        usort($days, static fn ($a, $b) => (($a + 1) % 7) <=> (($b + 1) % 7)); // week starts on Saturday
        return $days ? implode(' و ', array_map(static fn ($d) => Fa::weekday($d), $days)) : '(فعلاً هیچ روزی)';
    }

    private function closedText(): string
    {
        $days = AdminPanel::days($this->config, $this->db);
        $today = (int) date('w');
        if (!$days) {
            return $this->texts->render('paused');
        }
        $wait = 7;
        foreach ($days as $d) {
            $wait = min($wait, ($d - $today + 7) % 7 ?: 7);
        }
        return $this->texts->render('closed', [
            'days' => $this->dayNames(),
            'next_day' => Fa::weekday(($today + $wait) % 7),
            'wait' => Fa::digits((string) $wait),
        ]);
    }

    private function quotaText(int $userId, bool $exhausted = false): string
    {
        $limit = AdminPanel::quota($this->config, $this->db) + (int) ($this->db->user($userId)['bonus'] ?? 0);
        $left = max(0, $limit - $this->db->used($userId, $this->periodKey()));
        return $this->texts->render($exhausted ? 'quota_done' : 'quota_left', [
            'left' => Fa::digits((string) $left),
            'limit' => Fa::digits((string) $limit),
        ]);
    }

    private function helpText(): string
    {
        return $this->texts->render('help', [
            'days' => $this->dayNames(),
            'quota' => Fa::digits((string) AdminPanel::quota($this->config, $this->db)),
        ]);
    }

    private function adminHelp(): string
    {
        return "🛠 <b>دستورات مدیر</b>\n\n"
            . "<code>/panel</code> پنل تنظیمات (کانال انتشار، سهمیه، روزها، Gemini)\n"
            . "<code>/test BTC 4h</code> تحلیل فوری در همین چت (بدون محدودیت روز و سهمیه)\n"
            . "<code>/stats</code> آمار\n"
            . "<code>/user 123</code> وضعیت کاربر (آیدی عددی یا @یوزرنیم)\n"
            . "<code>/addquota 123 2</code> سهمیه اضافه\n"
            . "<code>/reset 123</code> صفر کردن سهمیه این هفته\n"
            . "<code>/ban 123</code> / <code>/unban 123</code>\n"
            . "<code>/off</code> / <code>/on</code> توقف و فعال‌سازی ربات\n"
            . "<code>/brain متن</code> آموزش سبک تحلیل به Gemini\n"
            . "<code>/brain</code> نمایش آموزش‌ها، <code>/brain_clear</code> پاک کردن\n"
            . "<code>/logs</code> آخرین لاگ‌ها (برای عیب‌یابی)";
    }
}

}

namespace App {

use App\Support\Fa;
use App\Support\Http;
use App\Telegram\Client;

/**
 * Entry points shared by webhook.php / poll.php / tools/* and the single-file build.
 */
final class Entry
{
    /** Handles a Telegram webhook request. */
    public static function webhook(array $config): void
    {
        $secret = (string) ($config['webhook_secret'] ?? '');
        if ($secret !== '' && !hash_equals($secret, (string) ($_SERVER['HTTP_X_TELEGRAM_BOT_API_SECRET_TOKEN'] ?? ''))) {
            http_response_code(403);
            exit('forbidden');
        }
        $update = json_decode((string) file_get_contents('php://input'), true);
        if (!is_array($update)) {
            exit('ok');
        }

        // Answer Telegram right away; an analysis can take up to a minute.
        ignore_user_abort(true);
        set_time_limit(300);
        http_response_code(200);
        header('Content-Type: text/plain');
        header('Content-Length: 2');
        header('Connection: close');
        echo 'ok';
        if (function_exists('fastcgi_finish_request')) {
            fastcgi_finish_request();
        } elseif (function_exists('litespeed_finish_request')) {
            litespeed_finish_request();
        } else {
            while (ob_get_level() > 0) {
                ob_end_flush();
            }
            flush();
        }

        try {
            (new Hub($config))->handle($update);
        } catch (\Throwable $e) {
            app_log('webhook error: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
        }
    }

    /** Long polling loop (CLI). */
    public static function poll(array $config, bool $deleteWebhook): void
    {
        $tg = new Client((string) $config['bot_token']);
        if ($deleteWebhook) {
            $tg->call('deleteWebhook');
            echo "Webhook removed.\n";
        }
        $me = $tg->call('getMe');
        if ($me === null) {
            exit("Bot token is invalid or Telegram is unreachable.\n");
        }
        echo 'Running as @' . $me['username'] . "\n";
        $bot = new Hub($config, $tg);
        $offset = 0;
        while (true) {
            $updates = $tg->call('getUpdates', ['offset' => $offset, 'timeout' => 50, 'allowed_updates' => ['message', 'callback_query', 'my_chat_member']]);
            if ($updates === null) {
                sleep(3);
                continue;
            }
            foreach ($updates as $u) {
                $offset = $u['update_id'] + 1;
                try {
                    $bot->handle($u);
                } catch (\Throwable $e) {
                    app_log('poll error: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
                    echo 'Error: ', $e->getMessage(), "\n";
                }
            }
        }
    }

    /** @return string[] human readable check results */
    public static function check(array $config): array
    {
        $out = [];
        $ok = static function (bool $c, string $label, string $hint = '') use (&$out): void {
            $out[] = ($c ? '[OK]   ' : '[FAIL] ') . $label . ($c || $hint === '' ? '' : "  -> $hint");
        };
        $ok(PHP_VERSION_ID >= 80000, 'PHP ' . PHP_VERSION, 'PHP 8.0 or newer is required');
        foreach (['curl', 'gd', 'mbstring', 'pdo_sqlite', 'json', 'simplexml'] as $ext) {
            $ok(extension_loaded($ext), "extension $ext", "enable php-$ext on the host");
        }
        $ok(function_exists('imagettftext'), 'GD FreeType support', 'GD must be built with FreeType');
        $dir = app_storage();
        $ok(is_writable($dir), 'storage writable (' . basename($dir) . ')', 'chmod 775 on the storage folder');
        $font = app_font('Bold');
        $ok(is_file($font) && filesize($font) > 50000, 'fonts', 'could not download Vazirmatn fonts; upload them to ' . dirname($font));

        $tg = new Client((string) $config['bot_token']);
        $me = $tg->call('getMe');
        $ok($me !== null, 'Telegram bot token' . ($me ? ' (@' . $me['username'] . ')' : ''), 'check bot_token / server access to api.telegram.org');
        if ($me) {
            $info = $tg->call('getWebhookInfo');
            $out[] = '       webhook: ' . (($info['url'] ?? '') ?: '(none)')
                . (!empty($info['pending_update_count']) ? ' | pending: ' . $info['pending_update_count'] : '')
                . (isset($info['last_error_message']) ? ' | last error: ' . $info['last_error_message'] : '');
        }

        $market = new Market\MarketData($config['market'] ?? [], app_storage('cache'));
        try {
            $s = $market->candles('BTC', '4h', 50);
            $ok(true, 'market data (' . $market->lastProvider . ', BTC ' . Fa::price($s->lastClose()) . ')');
        } catch (\Throwable $e) {
            $ok(false, 'market data', 'no exchange API reachable from this server; set "proxy" in config or use another host');
        }

        // Modules
        $ok(Modules::installed(Modules::BANNER), 'banner module (modules/banner/nikto-bot.php)', 'upload the modules/banner folder');
        $signalFiles = is_file(Modules::signalDir() . '/bot.php');
        $ok($signalFiles && PHP_VERSION_ID >= 80100, 'signal module (modules/signal)', $signalFiles ? 'the signal bot needs PHP 8.1 or newer' : 'upload the modules/signal folder');
        $last = is_file(app_storage() . '/cron.last') ? (string) file_get_contents(app_storage() . '/cron.last') : '';
        $lastTs = $last !== '' ? strtotime(substr($last, 0, 19)) : false;
        $ok($lastTs !== false && $lastTs > time() - 180, 'cron' . ($last !== '' ? ' (last run ' . substr($last, 0, 19) . ')' : ' (never ran)'),
            'add a cron job every minute: php ' . HUB_ROOT . '/cron.php');

        $key = (string) ($config['gemini']['api_key'] ?? '');
        if ($key === '') {
            $out[] = '[--]   Gemini disabled (no api_key)';
        } else {
            $res = Http::request('GET', 'https://generativelanguage.googleapis.com/v1beta/models?pageSize=1', ['headers' => ['x-goog-api-key: ' . $key]]);
            $ok($res['status'] === 200, 'Gemini API key', 'HTTP ' . $res['status'] . ' ' . substr($res['body'], 0, 150));
        }
        return $out;
    }

    public static function setWebhook(array $config, string $url): string
    {
        $tg = new Client((string) $config['bot_token']);
        $res = $tg->call('setWebhook', [
            'url' => $url,
            'secret_token' => $config['webhook_secret'],
            'allowed_updates' => ['message', 'callback_query', 'my_chat_member'],
            'max_connections' => 20,
        ]);
        return $res !== null ? "Webhook set: $url" : 'setWebhook failed (see logs in the storage folder)';
    }

    /** Public URL of the running script, e.g. https://example.com/bot/bot.php */
    public static function selfUrl(): string
    {
        $host = $_SERVER['HTTP_X_FORWARDED_HOST'] ?? ($_SERVER['HTTP_HOST'] ?? 'localhost');
        $path = strtok((string) ($_SERVER['REQUEST_URI'] ?? $_SERVER['SCRIPT_NAME'] ?? '/'), '?');
        return 'https://' . $host . $path;
    }
}

}

namespace App {

use App\Telegram\Client;

/**
 * Single entry point for all Telegram updates. /panel shows three buttons (analysis,
 * banner, signal); every button press and admin message is routed to the module that owns it.
 *
 * Routing rules:
 *  - callback data "hub:*"      → hub menu
 *  - callback data "an:*"/"p:*" → analysis module
 *  - callback data "admin:*"    → signal module
 *  - banner panel codes (m, j:, ch, s, st, lg, hp, sc, nop) → banner module
 *  - admin text while a module waits for input → that module (the last one the admin used)
 *  - module specific commands (/test, /send, ...) → their module
 *  - everything from users (private chat, channel direct messages) → analysis module
 *  - my_chat_member → signal module (channel access checks)
 */
final class Hub
{
    private const BANNER_HEADS = ['m', 'nop', 'j', 'sc', 'ch', 's', 'st', 'lg', 'hp'];
    private const ANALYSIS_COMMANDS = ['/test', '/analyze', '/stats', '/user', '/quota', '/addquota', '/bonus', '/reset', '/ban', '/unban', '/off', '/on', '/brain', '/brain_clear', '/logs'];
    private const BANNER_COMMANDS = ['/send', '/status', '/id'];

    private const TITLES = [
        Modules::ANALYSIS => '📊 ربات تحلیل',
        Modules::BANNER => '🖼 ربات بنر',
        Modules::SIGNAL => '📡 ربات سیگنال',
    ];

    private Client $tg;
    private Storage $db;
    private string $timezone;

    public function __construct(private array $config, ?Client $client = null, ?Storage $storage = null)
    {
        $this->tg = $client ?? new Client((string) $config['bot_token']);
        $this->db = $storage ?? new Storage(app_storage() . '/bot.sqlite');
        $this->timezone = (string) ($config['timezone'] ?? 'Asia/Tehran');
    }

    public function handle(array $update): void
    {
        if (isset($update['update_id']) && !$this->db->claimUpdate((int) $update['update_id'])) {
            return;
        }
        unset($update['update_id']); // already de-duplicated here

        if (isset($update['callback_query'])) {
            $this->onCallback($update);
            return;
        }
        if (isset($update['my_chat_member'])) {
            if (Modules::installed(Modules::SIGNAL)) {
                $this->dispatch(Modules::SIGNAL, $update);
            }
            return;
        }
        if (isset($update['message'])) {
            $this->onMessage($update);
        }
    }

    // ------------------------------------------------------------------ routing

    private function onCallback(array $update): void
    {
        $cq = $update['callback_query'];
        $data = (string) ($cq['data'] ?? '');
        $userId = (int) ($cq['from']['id'] ?? 0);

        if (str_starts_with($data, 'hub:')) {
            $this->hubCallback($cq);
            return;
        }
        $module = match (true) {
            str_starts_with($data, 'admin:') => Modules::SIGNAL,
            str_starts_with($data, 'an:'), str_starts_with($data, 'p:') => Modules::ANALYSIS,
            in_array(explode(':', $data)[0], self::BANNER_HEADS, true) => Modules::BANNER,
            default => $this->active($userId),
        };
        if (!Modules::installed($module)) {
            $this->tg->answerCallback((string) $cq['id'], 'این بخش نصب نشده است.');
            return;
        }
        if ($this->isAdmin($userId)) {
            $this->setActive($userId, $module);
        }
        $this->dispatch($module, $update);
    }

    private function onMessage(array $update): void
    {
        $msg = $update['message'];
        $userId = (int) ($msg['from']['id'] ?? 0);
        $private = ($msg['chat']['type'] ?? '') === 'private';

        if (!$private || !$this->isAdmin($userId) || !empty($msg['from']['is_bot'])) {
            // Users (private chat or the channel's direct messages) talk to the analysis bot.
            $this->dispatch(Modules::ANALYSIS, $update);
            return;
        }

        $text = trim((string) ($msg['text'] ?? ''));
        $cmd = str_starts_with($text, '/') ? strtolower((string) preg_replace('/@\w+$/', '', strtok($text, " \n") ?: '')) : '';

        if (in_array($cmd, ['/panel', '/start', '/admin', '/menu'], true)) {
            $this->showMenu(['chat_id' => $msg['chat']['id']]);
            return;
        }
        if ($cmd === '/help') {
            $this->tg->sendMessage(['chat_id' => $msg['chat']['id']], $this->helpText());
            return;
        }
        if (in_array($cmd, self::ANALYSIS_COMMANDS, true)) {
            $this->setActive($userId, Modules::ANALYSIS);
            $this->dispatch(Modules::ANALYSIS, $update);
            return;
        }
        if (in_array($cmd, self::BANNER_COMMANDS, true) && Modules::installed(Modules::BANNER)) {
            $this->setActive($userId, Modules::BANNER);
            $this->dispatch(Modules::BANNER, $update);
            return;
        }

        // Input for a settings prompt, /cancel, or a forwarded channel post goes to the module in use.
        $active = $this->active($userId);
        $forwarded = isset($msg['forward_origin']) || isset($msg['forward_from_chat']);
        if ($active !== Modules::ANALYSIS && Modules::installed($active)
            && ($cmd === '/cancel' || $forwarded || $this->awaitingInput($active, $userId))) {
            $this->dispatch($active, $update);
            return;
        }
        $this->dispatch(Modules::ANALYSIS, $update);
    }

    private function hubCallback(array $cq): void
    {
        $userId = (int) ($cq['from']['id'] ?? 0);
        $chatId = $cq['message']['chat']['id'] ?? $userId;
        $messageId = (int) ($cq['message']['message_id'] ?? 0);
        $id = (string) ($cq['id'] ?? '');
        if (!$this->isAdmin($userId)) {
            $this->tg->answerCallback($id, 'دسترسی ندارید.');
            return;
        }
        $parts = explode(':', (string) $cq['data']);
        $action = $parts[1] ?? 'home';

        if ($action === 'open') {
            $module = (string) ($parts[2] ?? '');
            if (!isset(self::TITLES[$module])) {
                $this->tg->answerCallback($id);
                return;
            }
            if (!Modules::installed($module)) {
                $this->tg->answerCallback($id, $module === Modules::SIGNAL && PHP_VERSION_ID < 80100
                    ? 'ربات سیگنال PHP 8.1 یا بالاتر لازم دارد.'
                    : 'فایل‌های این بخش آپلود نشده است.');
                return;
            }
            $this->setActive($userId, $module);
            if ($module === Modules::ANALYSIS) {
                $this->tg->answerCallback($id);
                (new AdminPanel($this->config, $this->tg, $this->db))->show(['chat_id' => $chatId], $messageId ?: null);
                return;
            }
            // Open the module's own main screen in place of the hub menu.
            $cq['data'] = $module === Modules::SIGNAL ? 'admin:main' : 'm';
            $this->dispatch($module, ['callback_query' => $cq]);
            return;
        }

        // hub:home
        $this->tg->answerCallback($id);
        $this->showMenu(['chat_id' => $chatId], $messageId ?: null);
    }

    private function dispatch(string $module, array $update): void
    {
        try {
            switch ($module) {
                case Modules::BANNER:
                    Modules::dispatchBanner($this->config, $update);
                    break;
                case Modules::SIGNAL:
                    Modules::dispatchSignal($update);
                    break;
                default:
                    date_default_timezone_set($this->timezone);
                    (new Bot($this->config, $this->tg, $this->db))->handle($update);
            }
        } catch (\Throwable $e) {
            app_log("hub: {$module} failed: " . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
        } finally {
            date_default_timezone_set($this->timezone);
        }
    }

    private function awaitingInput(string $module, int $userId): bool
    {
        try {
            return match ($module) {
                Modules::BANNER => Modules::bannerAwaitingInput($this->config, $userId),
                Modules::SIGNAL => Modules::signalAwaitingInput($userId),
                default => (string) $this->db->get('admin_state_' . $userId, '') !== '',
            };
        } catch (\Throwable $e) {
            app_log("hub: state check for {$module} failed: " . $e->getMessage());
            return false;
        } finally {
            date_default_timezone_set($this->timezone);
        }
    }

    // ------------------------------------------------------------------ menu

    public function showMenu(array $to, ?int $editId = null): void
    {
        $text = "🛠 <b>پنل مدیریت</b>\n\nبخش مورد نظر را انتخاب کنید. تنظیمات هر بخش کاملاً جداست.\n\n"
            . self::TITLES[Modules::ANALYSIS] . ' — تحلیل درخواستی کاربران از دایرکت کانال' . "\n"
            . self::TITLES[Modules::BANNER] . ' — ارسال زمان‌بندی‌شده بنرهای بازار' . $this->badge(Modules::BANNER) . "\n"
            . self::TITLES[Modules::SIGNAL] . ' — اسکن بازار و سیگنال خودکار' . $this->badge(Modules::SIGNAL);
        $kb = [];
        foreach (self::TITLES as $module => $title) {
            $kb[] = [['text' => $title, 'callback_data' => 'hub:open:' . $module]];
        }
        if ($editId !== null && $this->tg->editMessage($to['chat_id'], $editId, $text, $kb) !== null) {
            return;
        }
        $this->tg->sendMessage($to, $text, ['reply_markup' => ['inline_keyboard' => $kb]]);
    }

    private function badge(string $module): string
    {
        return Modules::installed($module) ? '' : ' <i>(نصب نشده)</i>';
    }

    private function helpText(): string
    {
        return "🛠 <b>راهنمای مدیر</b>\n\n"
            . "<code>/panel</code> منوی اصلی با سه بخش\n\n"
            . "<b>📊 تحلیل</b>\n"
            . "<code>/test BTC 4h</code> تحلیل فوری · <code>/stats</code> آمار · <code>/logs</code> لاگ‌ها\n"
            . "<code>/user</code> <code>/addquota</code> <code>/reset</code> <code>/ban</code> <code>/brain</code>\n\n"
            . "<b>🖼 بنر</b>\n"
            . "<code>/send prices</code> ارسال فوری یک کارت · <code>/status</code> وضعیت\n\n"
            . "<b>📡 سیگنال</b>\n"
            . "همه تنظیمات از دکمه «ربات سیگنال» در <code>/panel</code>\n\n"
            . '<code>/cancel</code> لغو ورودی در حال انتظار';
    }

    // ------------------------------------------------------------------ helpers

    private function isAdmin(int $id): bool
    {
        return in_array($id, array_map('intval', (array) ($this->config['admin_ids'] ?? [])), true);
    }

    private function active(int $userId): string
    {
        $m = (string) $this->db->get('hub_active_' . $userId, Modules::ANALYSIS);
        return isset(self::TITLES[$m]) ? $m : Modules::ANALYSIS;
    }

    private function setActive(int $userId, string $module): void
    {
        if ($this->active($userId) !== $module) {
            $this->db->set('hub_active_' . $userId, $module);
        }
    }
}

}

namespace App\Market {

/**
 * Deterministic synthetic market (random walk with trending regimes and volatility clusters).
 * Used for testing the bot and the card design without internet access.
 */
final class DemoMarket
{
    private const BASE_PRICES = [
        'BTC' => 98450.0, 'ETH' => 3650.0, 'SOL' => 186.4, 'BNB' => 712.0, 'XRP' => 2.41,
        'DOGE' => 0.238, 'TON' => 5.82, 'ADA' => 0.89, 'AVAX' => 34.7, 'LINK' => 21.3,
        'PEPE' => 0.00001834, 'SHIB' => 0.00002291, 'TRX' => 0.271, 'DOT' => 6.95,
    ];

    private static array $hourly = [];

    public static function series(string $base, string $quote, string $tf, int $limit): Series
    {
        $tfSec = Series::timeframeSeconds($tf);
        $hours = self::hourly($base);
        $rows = [];
        if ($tfSec < 3600) {
            // Not used for real analysis; split hours so the call still works.
            foreach ($hours as $h) {
                $rows[] = $h;
            }
        } else {
            $bucket = null;
            foreach ($hours as $h) {
                $key = intdiv(intdiv($h[0], 1000), $tfSec);
                if ($bucket === null || $bucket[6] !== $key) {
                    if ($bucket !== null) {
                        $rows[] = array_slice($bucket, 0, 6);
                    }
                    $bucket = [$key * $tfSec * 1000, $h[1], $h[2], $h[3], $h[4], $h[5], $key];
                    continue;
                }
                $bucket[2] = max($bucket[2], $h[2]);
                $bucket[3] = min($bucket[3], $h[3]);
                $bucket[4] = $h[4];
                $bucket[5] += $h[5];
            }
            if ($bucket !== null) {
                $rows[] = array_slice($bucket, 0, 6);
            }
        }
        return Series::fromRows($base . $quote, $tf, 'demo', array_slice($rows, -$limit));
    }

    public static function orderBook(string $base, string $quote): array
    {
        $hours = self::hourly($base);
        $price = $hours[count($hours) - 1][4];
        mt_srand(crc32($base . 'book'));
        $bids = [];
        $asks = [];
        for ($i = 1; $i <= 400; $i++) {
            $step = $price * 0.0002 * $i;
            $bq = (mt_rand(1, 100) / 10) * (mt_rand(0, 40) === 0 ? 25 : 1);
            $aq = (mt_rand(1, 100) / 10) * (mt_rand(0, 40) === 0 ? 25 : 1);
            $bids[] = [$price - $step, $bq * 50000 / $price];
            $asks[] = [$price + $step, $aq * 50000 / $price];
        }
        mt_srand();
        return ['bids' => $bids, 'asks' => $asks];
    }

    /** One year of hourly candles ending at the current hour. */
    private static function hourly(string $base): array
    {
        if (isset(self::$hourly[$base])) {
            return self::$hourly[$base];
        }
        $n = 24 * 400;
        mt_srand(crc32($base));
        $gauss = static function (): float {
            $u = max(mt_rand() / mt_getrandmax(), 1e-12);
            $v = mt_rand() / mt_getrandmax();
            return sqrt(-2 * log($u)) * cos(2 * M_PI * $v);
        };

        $baseVol = 0.0038;
        $var = $baseVol ** 2;
        $drift = 0.0;
        $regimeLeft = 0;
        $logP = 0.0;
        $raw = [];
        for ($i = 0; $i < $n; $i++) {
            if ($regimeLeft-- <= 0) {
                $regimeLeft = mt_rand(60, 320);
                $drift = (mt_rand(-100, 100) / 100) * 0.0011;
            }
            $sigma = sqrt($var);
            $r = $drift + $sigma * $gauss();
            if (mt_rand(0, 400) === 0) {
                $r += (mt_rand(0, 1) ? 1 : -1) * $sigma * mt_rand(4, 8);
            }
            $var = 0.000002 + 0.08 * $r * $r + 0.88 * $var;
            $var = min(max($var, ($baseVol * 0.4) ** 2), ($baseVol * 3) ** 2);
            $open = $logP;
            $logP += $r;
            $close = $logP;
            $hi = max($open, $close) + abs($gauss()) * $sigma * 0.55;
            $lo = min($open, $close) - abs($gauss()) * $sigma * 0.55;
            $vol = exp($gauss() * 0.35) * (1 + 2.5 * abs($r) / $baseVol);
            $raw[] = [$open, $hi, $lo, $close, $vol];
        }
        mt_srand();

        $target = self::BASE_PRICES[$base] ?? (1 + (crc32($base) % 5000) / 1000);
        $shift = log($target) - $raw[$n - 1][3];
        $end = intdiv(time(), 3600) * 3600;
        $start = $end - ($n - 1) * 3600;
        $volScale = 1500000 / $target;
        $rows = [];
        foreach ($raw as $i => [$o, $h, $l, $c, $v]) {
            $rows[] = [($start + $i * 3600) * 1000, exp($o + $shift), exp($h + $shift), exp($l + $shift), exp($c + $shift), $v * $volScale];
        }
        return self::$hourly[$base] = $rows;
    }
}

}

namespace App\Market {

use App\Support\Http;

/**
 * Fetches candles and order books from public exchange APIs (no API key needed).
 * Providers are tried in order; the first one that knows the symbol wins.
 */
final class MarketData
{
    private string $quote;
    private array $providers;
    private bool $demo;
    private string $cacheDir;
    private int $cacheTtl = 60;
    public string $lastProvider = '';

    public function __construct(array $marketConfig, string $cacheDir)
    {
        $this->quote = strtoupper($marketConfig['quote'] ?? 'USDT');
        $this->providers = $marketConfig['providers'] ?? ['binance', 'bybit', 'okx', 'kucoin'];
        $this->demo = (bool) ($marketConfig['demo'] ?? false);
        $this->cacheDir = $cacheDir;
        if (!is_dir($cacheDir)) {
            @mkdir($cacheDir, 0775, true);
        }
    }

    public function quote(): string
    {
        return $this->quote;
    }

    public function candles(string $base, string $tf, int $limit = 300): Series
    {
        $base = strtoupper($base);
        if ($this->demo) {
            $this->lastProvider = 'demo';
            return DemoMarket::series($base, $this->quote, $tf, $limit);
        }

        $notFound = 0;
        foreach ($this->providers as $provider) {
            $cacheKey = "{$provider}_{$base}{$this->quote}_{$tf}_{$limit}";
            $rows = $this->cacheGet($cacheKey);
            if ($rows === null) {
                try {
                    $rows = $this->fetchCandles($provider, $base, $tf, $limit);
                } catch (SymbolNotFound $e) {
                    $notFound++;
                    continue;
                }
                if ($rows === null || count($rows) < 30) {
                    continue;
                }
                $this->cachePut($cacheKey, $rows);
            }
            $this->lastProvider = $provider;
            return Series::fromRows($base . $this->quote, $tf, $provider, $rows);
        }

        if ($notFound > 0) {
            throw new SymbolNotFound($base);
        }
        throw new MarketUnavailable('No market data provider responded');
    }

    /**
     * Order book of the provider that served the last candles.
     * @return array{bids: array<array{0:float,1:float}>, asks: array<array{0:float,1:float}>}|null
     */
    public function orderBook(string $base): ?array
    {
        $base = strtoupper($base);
        if ($this->demo) {
            return DemoMarket::orderBook($base, $this->quote);
        }
        $order = array_unique(array_merge([$this->lastProvider], $this->providers));
        foreach ($order as $provider) {
            $book = $this->fetchOrderBook($provider, $base);
            if ($book !== null && $book['bids'] && $book['asks']) {
                return $book;
            }
        }
        return null;
    }

    private function fetchCandles(string $provider, string $base, string $tf, int $limit): ?array
    {
        $q = $this->quote;
        switch ($provider) {
            case 'binance':
            case 'binance_vision':
                $host = $provider === 'binance' ? 'https://api.binance.com' : 'https://data-api.binance.vision';
                $res = Http::request('GET', "$host/api/v3/klines?symbol={$base}{$q}&interval={$tf}&limit=" . min($limit, 1000));
                if ($res['status'] === 400 && str_contains($res['body'], 'Invalid symbol')) {
                    throw new SymbolNotFound($base);
                }
                $data = json_decode($res['body'], true);
                if ($res['status'] !== 200 || !is_array($data)) {
                    return null;
                }
                return array_map(static fn ($k) => [(int) $k[0], (float) $k[1], (float) $k[2], (float) $k[3], (float) $k[4], (float) $k[5]], $data);

            case 'bybit':
                $map = ['1m' => '1', '3m' => '3', '5m' => '5', '15m' => '15', '30m' => '30', '1h' => '60', '2h' => '120', '4h' => '240', '6h' => '360', '12h' => '720', '1d' => 'D', '1w' => 'W'];
                if (!isset($map[$tf])) {
                    return null;
                }
                $data = Http::getJson("https://api.bybit.com/v5/market/kline?category=spot&symbol={$base}{$q}&interval={$map[$tf]}&limit=" . min($limit, 1000));
                if ($data === null) {
                    return null;
                }
                if (($data['retCode'] ?? 0) !== 0 || empty($data['result']['list'])) {
                    throw new SymbolNotFound($base);
                }
                return array_map(static fn ($k) => [(int) $k[0], (float) $k[1], (float) $k[2], (float) $k[3], (float) $k[4], (float) $k[5]], $data['result']['list']);

            case 'okx':
                $map = ['1m' => '1m', '3m' => '3m', '5m' => '5m', '15m' => '15m', '30m' => '30m', '1h' => '1H', '2h' => '2H', '4h' => '4H', '6h' => '6Hutc', '12h' => '12Hutc', '1d' => '1Dutc', '1w' => '1Wutc'];
                if (!isset($map[$tf])) {
                    return null;
                }
                $data = Http::getJson("https://www.okx.com/api/v5/market/candles?instId={$base}-{$q}&bar={$map[$tf]}&limit=" . min($limit, 300));
                if ($data === null) {
                    return null;
                }
                if (($data['code'] ?? '0') !== '0' || empty($data['data'])) {
                    throw new SymbolNotFound($base);
                }
                return array_map(static fn ($k) => [(int) $k[0], (float) $k[1], (float) $k[2], (float) $k[3], (float) $k[4], (float) $k[5]], $data['data']);

            case 'kucoin':
                $map = ['1m' => '1min', '3m' => '3min', '5m' => '5min', '15m' => '15min', '30m' => '30min', '1h' => '1hour', '2h' => '2hour', '4h' => '4hour', '6h' => '6hour', '12h' => '12hour', '1d' => '1day', '1w' => '1week'];
                if (!isset($map[$tf])) {
                    return null;
                }
                $data = Http::getJson("https://api.kucoin.com/api/v1/market/candles?type={$map[$tf]}&symbol={$base}-{$q}");
                if ($data === null) {
                    return null;
                }
                if (($data['code'] ?? '') !== '200000' || empty($data['data'])) {
                    throw new SymbolNotFound($base);
                }
                // KuCoin row order: time(sec), open, close, high, low, volume
                $rows = array_map(static fn ($k) => [(int) $k[0] * 1000, (float) $k[1], (float) $k[3], (float) $k[4], (float) $k[2], (float) $k[5]], $data['data']);
                return array_slice($rows, 0, $limit);
        }
        return null;
    }

    private function fetchOrderBook(string $provider, string $base): ?array
    {
        $q = $this->quote;
        $norm = static fn (array $side) => array_map(static fn ($r) => [(float) $r[0], (float) $r[1]], $side);
        switch ($provider) {
            case 'binance':
            case 'binance_vision':
                $host = $provider === 'binance' ? 'https://api.binance.com' : 'https://data-api.binance.vision';
                $d = Http::getJson("$host/api/v3/depth?symbol={$base}{$q}&limit=1000");
                return $d ? ['bids' => $norm($d['bids'] ?? []), 'asks' => $norm($d['asks'] ?? [])] : null;
            case 'bybit':
                $d = Http::getJson("https://api.bybit.com/v5/market/orderbook?category=spot&symbol={$base}{$q}&limit=200");
                return $d && isset($d['result']['b']) ? ['bids' => $norm($d['result']['b']), 'asks' => $norm($d['result']['a'])] : null;
            case 'okx':
                $d = Http::getJson("https://www.okx.com/api/v5/market/books?instId={$base}-{$q}&sz=400");
                return $d && isset($d['data'][0]) ? ['bids' => $norm($d['data'][0]['bids']), 'asks' => $norm($d['data'][0]['asks'])] : null;
            case 'kucoin':
                $d = Http::getJson("https://api.kucoin.com/api/v1/market/orderbook/level2_100?symbol={$base}-{$q}");
                return $d && isset($d['data']['bids']) ? ['bids' => $norm($d['data']['bids']), 'asks' => $norm($d['data']['asks'])] : null;
        }
        return null;
    }

    private function cacheGet(string $key): ?array
    {
        $file = $this->cacheDir . '/' . $key . '.json';
        if (is_file($file) && filemtime($file) > time() - $this->cacheTtl) {
            $data = json_decode((string) file_get_contents($file), true);
            return is_array($data) ? $data : null;
        }
        return null;
    }

    private function cachePut(string $key, array $rows): void
    {
        @file_put_contents($this->cacheDir . '/' . $key . '.json', json_encode($rows));
    }
}

