namespace App {

/**
 * Loads the banner (Nikto) and signal modules on demand and hands them Telegram updates.
 * Each module keeps its own code, database, panel and settings; only the bot token,
 * admins and timezone are shared through the main config.php.
 */
final class Modules
{
    public const ANALYSIS = 'analysis';
    public const BANNER = 'banner';
    public const SIGNAL = 'signal';

    public static function bannerFile(): string
    {
        return HUB_ROOT . '/modules/banner/nikto-bot.php';
    }

    public static function signalDir(): string
    {
        return HUB_ROOT . '/modules/signal';
    }

    public static function installed(string $module): bool
    {
        return match ($module) {
            self::ANALYSIS => true,
            self::BANNER => is_file(self::bannerFile()),
            self::SIGNAL => is_file(self::signalDir() . '/bot.php') && PHP_VERSION_ID >= 80100,
            default => false,
        };
    }

    // ------------------------------------------------------------------ banner

    public static function bannerConfig(array $config): array
    {
        $admins = array_values(array_map('intval', (array) ($config['admin_ids'] ?? [])));
        $banner = (array) ($config['banner'] ?? []);
        return [
            'bot_token' => (string) ($config['bot_token'] ?? ''),
            'owner_id' => $admins[0] ?? 0,
            'admins' => $admins,
            'webhook_url' => (string) ($config['webhook_url'] ?? ''),
            'webhook_secret' => (string) ($config['webhook_secret'] ?? ''),
            'timezone' => (string) ($config['timezone'] ?? 'Asia/Tehran'),
            'brand' => (string) ($banner['brand'] ?? 'NIKTO CRYPTO'),
            'http_proxy' => (string) ($config['proxy'] ?? ''),
            'data_proxy' => (string) ($banner['data_proxy'] ?? ''),
            'coinglass_key' => (string) ($banner['coinglass_key'] ?? ''),
            'coingecko_key' => (string) ($banner['coingecko_key'] ?? ''),
            // Module data lives inside the hub's protected data folder.
            'root' => app_storage('banner'),
        ];
    }

    public static function loadBanner(array $config): void
    {
        if (class_exists(\Nikto\Telegram\Panel::class, false)) {
            return;
        }
        if (!defined('NIKTO_LIBRARY')) {
            define('NIKTO_LIBRARY', true);
        }
        if (!defined('NIKTO_CONFIG')) {
            define('NIKTO_CONFIG', self::bannerConfig($config));
        }
        require self::bannerFile();
        \Nikto\Core\Db::migrate();
        \Nikto\Jobs\Registry::all();
    }

    public static function dispatchBanner(array $config, array $update): void
    {
        self::loadBanner($config);
        date_default_timezone_set('UTC'); // the module works in UTC internally
        (new \Nikto\Telegram\Panel(new \Nikto\Telegram\Api()))->handleUpdate($update);
    }

    public static function bannerAwaitingInput(array $config, int $userId): bool
    {
        self::loadBanner($config);
        return \Nikto\Telegram\State::get($userId)['action'] !== '';
    }

    /** Runs the banner scheduler once (cron). */
    public static function bannerTick(array $config): int
    {
        self::loadBanner($config);
        date_default_timezone_set('UTC');
        return \Nikto\Bundle\Runtime::handleCli(['cron', 'cron']);
    }

    // ------------------------------------------------------------------ signal

    public static function loadSignal(): void
    {
        if (class_exists('BotApplication', false)) {
            return;
        }
        require_once self::signalDir() . '/bot.php';
        \Database::migrate();
    }

    public static function dispatchSignal(array $update): void
    {
        self::loadSignal();
        date_default_timezone_set(\Config::appTimezone());
        (new \BotApplication(new \TelegramClient(), new \ExchangeManager()))->handleUpdate($update);
    }

    public static function signalAwaitingInput(int $userId): bool
    {
        self::loadSignal();
        return (new \AdminStateStore())->get($userId) !== null;
    }

    /** Runs the signal worker for one cron cycle (CLI only, ~50 seconds). */
    public static function signalWorker(): void
    {
        if (!defined('WORKER_BOOTSTRAP_ONLY')) {
            define('WORKER_BOOTSTRAP_ONLY', true);
        }
        require_once self::signalDir() . '/worker.php';
        date_default_timezone_set(\Config::appTimezone());
        (new \Worker())->run();
    }
}

}

namespace App\Render {

use GdImage;

/**
 * Small drawing layer over GD. Everything is drawn at $scale× resolution and
 * downsampled on save, which gives smooth (anti-aliased) shapes and lines.
 * All coordinates passed in are logical (final image) pixels.
 */
final class Canvas
{
    public GdImage $im;
    private array $colors = [];
    private string $fontDir;

    public function __construct(public int $w, public int $h, private int $s = 2, string $fontDir = '')
    {
        $this->im = imagecreatetruecolor($w * $s, $h * $s);
        imagealphablending($this->im, true);
        imagesavealpha($this->im, false);
        $this->fontDir = $fontDir;
    }

    /** @param float $opacity 0..1 */
    public function color(string $hex, float $opacity = 1.0): int
    {
        $key = $hex . '|' . $opacity;
        if (isset($this->colors[$key])) {
            return $this->colors[$key];
        }
        $hex = ltrim($hex, '#');
        [$r, $g, $b] = [hexdec(substr($hex, 0, 2)), hexdec(substr($hex, 2, 2)), hexdec(substr($hex, 4, 2))];
        $alpha = 127 - (int) round(max(0, min(1, $opacity)) * 127);
        return $this->colors[$key] = imagecolorallocatealpha($this->im, $r, $g, $b, $alpha);
    }

    public static function mix(string $a, string $b, float $t): string
    {
        $a = ltrim($a, '#');
        $b = ltrim($b, '#');
        $out = '#';
        for ($i = 0; $i < 3; $i++) {
            $x = hexdec(substr($a, $i * 2, 2));
            $y = hexdec(substr($b, $i * 2, 2));
            $out .= sprintf('%02x', (int) round($x + ($y - $x) * $t));
        }
        return $out;
    }

    private function p(float $v): int
    {
        return (int) round($v * $this->s);
    }

    // ------------------------------------------------------------------ shapes

    public function rect(float $x1, float $y1, float $x2, float $y2, int $color): void
    {
        if ($x2 < $x1) {
            [$x1, $x2] = [$x2, $x1];
        }
        if ($y2 < $y1) {
            [$y1, $y2] = [$y2, $y1];
        }
        imagefilledrectangle($this->im, $this->p($x1), $this->p($y1), max($this->p($x1), $this->p($x2) - 1), max($this->p($y1), $this->p($y2) - 1), $color);
    }

    /**
     * Rounded rectangle filled row by row (each pixel painted once, so translucent fills stay even).
     * $fill may be a color or a [hexTop, hexBottom, opacityTop, opacityBottom] vertical gradient,
     * or ['h', hexLeft, hexRight, opLeft, opRight] for a horizontal one.
     */
    public function roundRect(float $x, float $y, float $w, float $h, float $r, int|array $fill): void
    {
        $X = $this->p($x);
        $Y = $this->p($y);
        $W = $this->p($w);
        $H = $this->p($h);
        $R = min($this->p($r), intdiv($W, 2), intdiv($H, 2));
        $horizontal = is_array($fill) && $fill[0] === 'h';
        if ($horizontal) {
            // Horizontal gradient: draw columns, inset by the corner radius at top/bottom.
            for ($col = 0; $col < $W; $col++) {
                $inset = 0;
                if ($col < $R) {
                    $dx = $R - $col - 0.5;
                    $inset = (int) round($R - sqrt(max(0, $R * $R - $dx * $dx)));
                } elseif ($col >= $W - $R) {
                    $dx = $col - ($W - $R) + 0.5;
                    $inset = (int) round($R - sqrt(max(0, $R * $R - $dx * $dx)));
                }
                $t = $W > 1 ? $col / ($W - 1) : 0;
                $c = $this->color(self::mix($fill[1], $fill[2], $t), $fill[3] + ($fill[4] - $fill[3]) * $t);
                imageline($this->im, $X + $col, $Y + $inset, $X + $col, $Y + $H - 1 - $inset, $c);
            }
            return;
        }
        for ($row = 0; $row < $H; $row++) {
            $inset = 0;
            if ($row < $R) {
                $dy = $R - $row - 0.5;
                $inset = (int) round($R - sqrt(max(0, $R * $R - $dy * $dy)));
            } elseif ($row >= $H - $R) {
                $dy = $row - ($H - $R) + 0.5;
                $inset = (int) round($R - sqrt(max(0, $R * $R - $dy * $dy)));
            }
            if (is_array($fill)) {
                $t = $H > 1 ? $row / ($H - 1) : 0;
                $c = $this->color(self::mix($fill[0], $fill[1], $t), $fill[2] + ($fill[3] - $fill[2]) * $t);
            } else {
                $c = $fill;
            }
            imageline($this->im, $X + $inset, $Y + $row, $X + $W - 1 - $inset, $Y + $row, $c);
        }
    }

    /** Rounded outline drawn as a thin ring (outer fill minus inner fill is not possible with alpha, so we draw strokes). */
    public function roundRectStroke(float $x, float $y, float $w, float $h, float $r, int $color, float $width = 1): void
    {
        $pts = [];
        $seg = 10;
        $corners = [[$x + $w - $r, $y + $r, -90], [$x + $w - $r, $y + $h - $r, 0], [$x + $r, $y + $h - $r, 90], [$x + $r, $y + $r, 180]];
        foreach ($corners as [$cx, $cy, $start]) {
            for ($i = 0; $i <= $seg; $i++) {
                $a = deg2rad($start + 90 * $i / $seg);
                $pts[] = [$cx + $r * cos($a), $cy + $r * sin($a)];
            }
        }
        $pts[] = $pts[0];
        $this->polyline($pts, $color, $width, false);
    }

    public function line(float $x1, float $y1, float $x2, float $y2, int $color, float $width = 1): void
    {
        $t = max(1, $this->p($width));
        if ($t <= 1) {
            imagesetthickness($this->im, 1);
            imageline($this->im, $this->p($x1), $this->p($y1), $this->p($x2), $this->p($y2), $color);
            return;
        }
        // Thick line as a polygon so translucent strokes blend once.
        $dx = $x2 - $x1;
        $dy = $y2 - $y1;
        $len = sqrt($dx * $dx + $dy * $dy);
        if ($len < 0.01) {
            return;
        }
        $nx = -$dy / $len * $width / 2;
        $ny = $dx / $len * $width / 2;
        $this->polygon([[$x1 + $nx, $y1 + $ny], [$x2 + $nx, $y2 + $ny], [$x2 - $nx, $y2 - $ny], [$x1 - $nx, $y1 - $ny]], $color);
    }

    public function dashed(float $x1, float $y1, float $x2, float $y2, int $color, float $width = 1, float $dash = 8, float $gap = 6): void
    {
        $dx = $x2 - $x1;
        $dy = $y2 - $y1;
        $len = sqrt($dx * $dx + $dy * $dy);
        if ($len < 0.01) {
            return;
        }
        $ux = $dx / $len;
        $uy = $dy / $len;
        for ($d = 0; $d < $len; $d += $dash + $gap) {
            $e = min($len, $d + $dash);
            $this->line($x1 + $ux * $d, $y1 + $uy * $d, $x1 + $ux * $e, $y1 + $uy * $e, $color, $width);
        }
    }

    public function polyline(array $pts, int $color, float $width = 1, bool $roundJoins = true): void
    {
        $c = count($pts);
        for ($i = 1; $i < $c; $i++) {
            $this->line($pts[$i - 1][0], $pts[$i - 1][1], $pts[$i][0], $pts[$i][1], $color, $width);
        }
        if ($roundJoins && $width > 1.5) {
            for ($i = 1; $i < $c - 1; $i++) {
                $this->circle($pts[$i][0], $pts[$i][1], $width / 2, $color);
            }
        }
    }

    public function dashedPolyline(array $pts, int $color, float $width = 2, float $dash = 10, float $gap = 7): void
    {
        $c = count($pts);
        for ($i = 1; $i < $c; $i++) {
            $this->dashed($pts[$i - 1][0], $pts[$i - 1][1], $pts[$i][0], $pts[$i][1], $color, $width, $dash, $gap);
        }
    }

    public function polygon(array $pts, int $color): void
    {
        $flat = [];
        foreach ($pts as [$x, $y]) {
            $flat[] = $this->p($x);
            $flat[] = $this->p($y);
        }
        if (count($flat) >= 6) {
            imagefilledpolygon($this->im, $flat, $color);
        }
    }

    public function circle(float $cx, float $cy, float $r, int $color): void
    {
        $d = max(1, $this->p($r * 2));
        imagefilledellipse($this->im, $this->p($cx), $this->p($cy), $d, $d, $color);
    }

    /** Thick arc (ring segment). Angles in degrees, 0 = 3 o'clock, clockwise. */
    public function arc(float $cx, float $cy, float $r, float $width, float $from, float $to, int $color): void
    {
        $outer = [];
        $inner = [];
        $steps = max(8, (int) (abs($to - $from) / 3));
        for ($i = 0; $i <= $steps; $i++) {
            $a = deg2rad($from + ($to - $from) * $i / $steps);
            $outer[] = [$cx + ($r + $width / 2) * cos($a), $cy + ($r + $width / 2) * sin($a)];
            $inner[] = [$cx + ($r - $width / 2) * cos($a), $cy + ($r - $width / 2) * sin($a)];
        }
        $this->polygon(array_merge($outer, array_reverse($inner)), $color);
        // round caps
        $a0 = deg2rad($from);
        $a1 = deg2rad($to);
        $this->circle($cx + $r * cos($a0), $cy + $r * sin($a0), $width / 2, $color);
        $this->circle($cx + $r * cos($a1), $cy + $r * sin($a1), $width / 2, $color);
    }

    /** Soft radial glow made of stacked translucent discs. */
    public function glow(float $cx, float $cy, float $r, string $hex, float $opacity = 0.25, int $steps = 18): void
    {
        for ($i = $steps; $i >= 1; $i--) {
            $this->circle($cx, $cy, $r * $i / $steps, $this->color($hex, $opacity / $steps));
        }
    }

    public function triangle(float $cx, float $cy, float $size, bool $up, int $color): void
    {
        $h = $size * 0.9;
        $this->polygon($up
            ? [[$cx, $cy - $h / 2], [$cx + $size / 2, $cy + $h / 2], [$cx - $size / 2, $cy + $h / 2]]
            : [[$cx, $cy + $h / 2], [$cx + $size / 2, $cy - $h / 2], [$cx - $size / 2, $cy - $h / 2]], $color);
    }

    public function arrowHead(float $x, float $y, float $angle, float $size, int $color): void
    {
        $a1 = $angle + deg2rad(150);
        $a2 = $angle - deg2rad(150);
        $this->polygon([
            [$x + cos($angle) * $size * 0.35, $y + sin($angle) * $size * 0.35],
            [$x + cos($a1) * $size, $y + sin($a1) * $size],
            [$x + cos($a2) * $size, $y + sin($a2) * $size],
        ], $color);
    }

    public function check(float $cx, float $cy, float $size, int $color, float $width = 2.4): void
    {
        $this->polyline([[$cx - $size * 0.45, $cy], [$cx - $size * 0.1, $cy + $size * 0.35], [$cx + $size * 0.5, $cy - $size * 0.35]], $color, $width);
    }

    // -------------------------------------------------------------------- text

    public function font(string $weight): string
    {
        return $this->fontDir !== '' ? $this->fontDir . '/Vazirmatn-' . $weight . '.ttf' : app_font($weight);
    }

    /** @return array{0: float, 1: float} width and height in logical px */
    public function measure(string $text, float $size, string $weight = 'Regular'): array
    {
        $v = Persian::visual($text);
        $box = imagettfbbox($size * $this->s, 0, $this->font($weight), $v);
        return [($box[2] - $box[0]) / $this->s, ($box[1] - $box[7]) / $this->s];
    }

    /**
     * Draws text with its baseline at $y. $align: left | right | center.
     * Returns the drawn width.
     */
    public function text(float $x, float $y, string $text, float $size, int $color, string $weight = 'Regular', string $align = 'left'): float
    {
        if ($text === '') {
            return 0;
        }
        $v = Persian::visual($text);
        $font = $this->font($weight);
        $box = imagettfbbox($size * $this->s, 0, $font, $v);
        $w = ($box[2] - $box[0]) / $this->s;
        $sx = match ($align) {
            'right' => $x - $w,
            'center' => $x - $w / 2,
            default => $x,
        };
        imagettftext($this->im, $size * $this->s, 0, $this->p($sx) - $box[0], $this->p($y), $color, $font, $v);
        return $w;
    }

    /** Height of a capital letter, used to center text vertically. */
    public function capHeight(float $size, string $weight = 'Regular'): float
    {
        $box = imagettfbbox($size * $this->s, 0, $this->font($weight), 'H');
        return ($box[1] - $box[7]) / $this->s;
    }

    /** Shortens text with an ellipsis until it fits $maxWidth. */
    public function fit(string $text, float $size, string $weight, float $maxWidth): string
    {
        if ($this->measure($text, $size, $weight)[0] <= $maxWidth) {
            return $text;
        }
        $words = preg_split('/\s+/u', $text);
        while (count($words) > 1) {
            array_pop($words);
            $candidate = implode(' ', $words) . '…';
            if ($this->measure($candidate, $size, $weight)[0] <= $maxWidth) {
                return $candidate;
            }
        }
        return mb_substr($text, 0, 12) . '…';
    }

    /** Pill-shaped label; returns its width. */
    public function pill(float $x, float $y, string $text, float $size, int $textColor, int|array $bg, string $weight = 'Bold', string $align = 'left', float $padX = 12, float $h = 0): float
    {
        [$tw] = $this->measure($text, $size, $weight);
        $h = $h ?: $size * 1.9;
        $w = $tw + $padX * 2;
        $left = match ($align) {
            'right' => $x - $w,
            'center' => $x - $w / 2,
            default => $x,
        };
        $this->roundRect($left, $y, $w, $h, $h / 2, $bg);
        $this->text($left + $padX, $y + $h / 2 + $this->capHeight($size, $weight) / 2, $text, $size, $textColor, $weight);
        return $w;
    }

    public function save(string $path): void
    {
        $out = imagecreatetruecolor($this->w, $this->h);
        imagecopyresampled($out, $this->im, 0, 0, 0, 0, $this->w, $this->h, $this->w * $this->s, $this->h * $this->s);
        $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
        if ($ext === 'jpg' || $ext === 'jpeg') {
            imagejpeg($out, $path, 93);
        } else {
            imagepng($out, $path, 6);
        }
        imagedestroy($out);
    }
}

}

namespace App\Render {

use App\Support\Fa;
use App\Texts;

/**
 * Builds the analysis caption from the editable 'caption' template (see Texts).
 * Telegram allows 1024 visible characters in a photo caption, so optional parts
 * are dropped when needed; if it still does not fit the text goes in a separate message.
 */
final class Caption
{
    private const LIMIT = 1024;
    private const LRM = "\u{200E}";

    /** @return array{0: string, 1: string} [caption, extra message ('' if none)] */
    public static function build(array $a, Texts $texts): array
    {
        $vars = self::vars($a);
        $template = $texts->get('caption');

        $attempts = [
            [],
            ['liquidity' => ''],
            ['liquidity' => '', 'summary' => ''],
            ['liquidity' => '', 'summary' => '', 'reasons' => self::reasons($a, 3)],
            ['liquidity' => '', 'summary' => '', 'reasons' => self::reasons($a, 2), 'summary_text' => '', 'invalidation' => ''],
        ];
        foreach ($attempts as $override) {
            $html = Texts::fill($template, array_merge($vars, $override));
            if (self::length($html) <= self::LIMIT) {
                return [$html, ''];
            }
        }
        // Too long even when trimmed: photo without caption, full text as its own message.
        return ['', Texts::fill($template, $vars)];
    }

    /** @return array<string, string> */
    public static function vars(array $a): array
    {
        $plan = $a['plan'];
        $long = $plan['side'] === 'long';
        $neutral = $a['bias'] === 'neutral';
        $e = static fn (string $s) => htmlspecialchars($s, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $pct = static fn (float $v) => self::LRM . Fa::pct($v, 1);
        $entry = $plan['entry_mid'];
        $ai = $a['ai'] ?? [];

        $vars = [
            'side_icon' => $neutral ? '🟡' : ($long ? '🟢' : '🔴'),
            'base' => $e($a['base']),
            'quote' => $e($a['quote']),
            'tf' => $e(Fa::tf($a['timeframe'])),
            'scenario' => $neutral
                ? 'بازار رنج؛ ' . ($long ? 'خرید از کف محدوده' : 'فروش از سقف محدوده')
                : ($long ? 'سناریوی صعودی (Long)' : 'سناریوی نزولی (Short)'),
            'confidence' => Fa::digits((string) $a['confidence']),
            'price' => Fa::price($a['price']),
            'change' => $pct($a['change24h']),
            'entry_low' => Fa::price($plan['entry'][0]),
            'entry_high' => Fa::price($plan['entry'][1]),
            'stop' => Fa::price($plan['stop']),
            'stop_pct' => $pct(($plan['stop'] - $entry) / $entry * 100),
            'rr' => number_format($plan['rr'][1] ?? $plan['rr'][0], 1),
        ];
        foreach ($plan['targets'] as $k => $t) {
            $n = $k + 1;
            $vars["tp{$n}"] = Fa::price($t);
            $vars["tp{$n}_pct"] = $pct(($t - $entry) / $entry * 100);
            $vars["tp{$n}_rr"] = number_format($plan['rr'][$k], 1);
        }

        $summaryText = !empty($ai['used']) ? trim((string) ($ai['summary'] ?? '')) : '';
        $invalidation = !empty($ai['used']) ? trim((string) ($ai['invalidation'] ?? '')) : '';
        $vars['summary_text'] = $e($summaryText);
        $vars['invalidation'] = $e($invalidation);
        $vars['summary'] = $summaryText !== ''
            ? '🧠 <b>خلاصه:</b> ' . $e($summaryText) . ($invalidation !== '' ? "\n❌ <b>ابطال:</b> " . $e($invalidation) : '')
            : '';
        $vars['reasons'] = self::reasons($a, 5);

        $liq = [];
        foreach ($a['liquidity'] as $l) {
            $liq[] = ($l['side'] === 'buy' ? 'BSL ' : 'SSL ') . '<code>' . Fa::price($l['price']) . '</code>';
        }
        $walls = [];
        foreach ($a['walls'] as $w) {
            $walls[] = ($w['side'] === 'bid' ? 'دیوار خرید ' : 'دیوار فروش ') . '<code>' . Fa::price($w['price']) . '</code> (' . self::LRM . '$' . Fa::compact($w['notional']) . ')';
        }
        $vars['liquidity'] = '';
        if ($liq || $walls) {
            $vars['liquidity'] = '💧 <b>نقدینگی:</b> ' . implode(' | ', array_slice($liq, 0, 3))
                . ($walls ? "\n🧱 " . implode(' | ', array_slice($walls, 0, 2)) : '');
        }
        return $vars;
    }

    private static function reasons(array $a, int $max): string
    {
        $ai = $a['ai'] ?? [];
        $long = $a['plan']['side'] === 'long';
        $list = !empty($ai['used']) && !empty($ai['reasons'])
            ? $ai['reasons']
            : array_map(static fn ($r) => $r['fa'], array_values(array_filter($a['reasons'], static fn ($r) => ($r['w'] > 0) === $long)));
        $list = array_slice($list, 0, $max);
        return $list ? '• ' . implode("\n• ", array_map(static fn ($s) => htmlspecialchars((string) $s, ENT_QUOTES | ENT_HTML5, 'UTF-8'), $list)) : '-';
    }

    /** Visible length in UTF-16 code units, the way Telegram counts it. */
    public static function length(string $html): int
    {
        $text = html_entity_decode(strip_tags($html), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        return intdiv(strlen(mb_convert_encoding($text, 'UTF-16LE', 'UTF-8')), 2);
    }
}

}

namespace App\Render {

use App\Support\Fa;

/**
 * Renders the analysis chart image (PNG): a compact header and the annotated chart
 * (zones, order blocks, liquidity, structure breaks and the projected path).
 * All numbers and explanations go in the message caption.
 */
final class Card
{
    // 1600 x 900 (16:9), same frame as the signal cards; Telegram shows it at 1280 x 720.
    private const W = 1600;
    private const H = 900;
    private const M = 32;

    // Frame: black / white / orange. Meaning colours (candles, levels, path) stay semantic.
    private const BG_TOP = '#000000';
    private const BG_BOTTOM = '#000000';
    private const PANEL = '#0B0B0B';
    private const PANEL_2 = '#0B0B0B';
    private const STROKE = '#2A2A2A';
    private const ORANGE = '#FF8A00';
    private const ORANGE_SOFT = '#FFBA66';
    private const CANDLE_UP = '#FFFFFF';
    private const CANDLE_DOWN = '#FF2D2D';
    private const OB = '#4FC3F7';         // sky blue
    private const PATH_UP = '#00E000';    // strong green
    private const PATH_DOWN = '#FF1A1A';  // strong red
    private const TEXT = '#FFFFFF';
    private const TEXT_2 = '#B4B4B4';
    private const MUTED = '#6E6E6E';
    private const GREEN = '#17C784';
    private const RED = '#F0464F';
    private const AMBER = '#F5B94A';
    private const CYAN = '#38C6E8';
    private const VIOLET = '#9B7BFF';

    private Canvas $c;
    private array $a;
    private string $accent;
    private string $side;
    private bool $withPath = true;

    public function __construct(private array $brand = [], private string $fontDir = '')
    {
        $this->accent = $brand['accent'] ?? '#7C5CFF';
    }

    /** @param bool $withPath false = no projected path (draft image for the AI review) */
    public function render(array $analysis, string $path, bool $withPath = true): string
    {
        $this->a = $analysis;
        $this->withPath = $withPath;
        $this->c = new Canvas(self::W, self::H, 2, $this->fontDir);
        $bias = $analysis['bias'];
        $this->side = $bias === 'neutral' ? self::AMBER : ($analysis['plan']['side'] === 'long' ? self::GREEN : self::RED);

        $this->background();
        $this->header(26);
        $this->chart(126, self::H - 126 - self::M);

        $this->c->save($path);
        return $path;
    }

    // ------------------------------------------------------------ sections

    private function background(): void
    {
        $c = $this->c;
        $c->roundRect(0, 0, self::W, self::H, 0, [self::BG_TOP, self::BG_BOTTOM, 1, 1]);
        $c->glow(110, 70, 420, self::ORANGE, 0.16);
        $c->glow(self::W - 60, self::H, 520, self::ORANGE, 0.08);
    }

    private function header(float $y): void
    {
        $c = $this->c;
        $a = $this->a;
        $M = self::M;

        // coin badge
        $cx = $M + 40;
        $cy = $y + 46;
        $c->circle($cx, $cy, 46, $c->color(self::ORANGE, 0.12));
        $c->circle($cx, $cy, 39, $c->color(self::ORANGE));
        $c->circle($cx, $cy, 35.5, $c->color('#000000'));
        $initials = mb_substr($a['base'], 0, strlen($a['base']) > 4 ? 3 : 4);
        $size = strlen($initials) >= 4 ? 13 : (strlen($initials) === 3 ? 16 : 20);
        $c->text($cx, $cy + $c->capHeight($size, 'Black') / 2, $initials, $size, $c->color('#FFFFFF'), 'Black', 'center');

        $x = $M + 100;
        $w = $c->text($x, $y + 44, $a['base'], 32, $c->color(self::TEXT), 'Black');
        $c->text($x + $w + 6, $y + 44, '/' . $a['quote'], 20, $c->color(self::MUTED), 'Bold');

        $chipY = $y + 58;
        $cx2 = $x;
        $cx2 += $c->pill($cx2, $chipY, strtoupper($a['timeframe']), 12, $c->color('#000000'), $c->color(self::ORANGE), 'Black', 'left', 12, 28) + 8;
        $w2 = $c->pill($cx2, $chipY, strtoupper($a['exchange_label'] ?? 'OURBIT'), 12, $c->color(self::ORANGE_SOFT), $c->color(self::ORANGE, 0.10), 'Bold', 'left', 12, 28);
        $c->roundRectStroke($cx2, $chipY, $w2, 28, 14, $c->color(self::ORANGE, 0.7), 1.2);
        $cx2 += $w2 + 8;
        $w3 = $c->pill($cx2, $chipY, Fa::jalaliDate($a['time']), 12, $c->color(self::TEXT_2), $c->color('#FFFFFF', 0.06), 'Medium', 'left', 12, 28);
        $c->roundRectStroke($cx2, $chipY, $w3, 28, 14, $c->color('#FFFFFF', 0.18), 1);

        // price + change
        $R = self::W - $M;
        $c->text($R, $y + 44, Fa::price($a['price']), 32, $c->color(self::TEXT), 'ExtraBold', 'right');
        $up = $a['change24h'] >= 0;
        $chg = Fa::pct($a['change24h']);
        $col = $up ? self::GREEN : self::RED;
        [$tw] = $c->measure($chg, 13, 'Bold');
        $pw = $tw + 50;
        $px = $R - $pw;
        $c->roundRect($px, $chipY, $pw, 28, 14, $c->color($col, 0.16));
        $c->triangle($px + 17, $chipY + 14, 10, $up, $c->color($col));
        $c->text($px + 29, $chipY + 14 + $c->capHeight(13, 'Bold') / 2, $chg, 13, $c->color($col), 'Bold');
        $c->text($px - 10, $chipY + 14 + $c->capHeight(12, 'Medium') / 2, 'تغییر ۲۴ ساعته', 12, $c->color(self::MUTED), 'Medium', 'right');
    }

    private function chart(float $y, float $h): void
    {
        $c = $this->c;
        $a = $this->a;
        $s = $a['series'];
        $plan = $a['plan'];
        $M = self::M;
        $pw = self::W - 2 * $M;

        $c->roundRect($M, $y, $pw, $h, 24, $c->color(self::PANEL));
        $c->roundRectStroke($M, $y, $pw, $h, 24, $c->color(self::STROKE), 1.2);
        $c->roundRect($M + 130, $y - 1.5, 120, 3, 1.5, $c->color(self::ORANGE));

        $x0 = $M + 22;
        $x1 = $M + $pw - 104; // right axis
        $y0 = $y + 58;
        $y1 = $y + $h - 46;
        $volH = ($y1 - $y0) * 0.13;

        $n = $s->count();
        $N = min(100, $n);
        $start = $n - $N;
        $pathMax = max(array_column($plan['path'], 0));
        $F = (int) max(34, min(60, ceil($pathMax * 1.6)));
        $step = ($x1 - $x0) / ($N + $F);
        $bx = static fn (float $i) => $x0 + ($i - $start + 0.5) * $step; // candle index -> x
        $nowX = $bx($n - 1);

        // price range
        $withPathPrices = $this->withPath ? array_column($plan['path'], 1) : [];
        $lo = min(array_slice($s->l, $start));
        $hi = max(array_slice($s->h, $start));
        foreach ($withPathPrices as $p) {
            $lo = min($lo, $p);
            $hi = max($hi, $p);
        }
        $pad = ($hi - $lo) * 0.07;
        $lo -= $pad;
        $hi += $pad;
        $py = static fn (float $p) => $y1 - $volH - ($p - $lo) / ($hi - $lo) * ($y1 - $volH - $y0);
        $inView = static fn (float $p) => $p >= $lo && $p <= $hi;

        // source
        $c->text($M + $pw - 22, $y + 36, $a['symbol'] . ' · ' . strtoupper($a['timeframe']) . ' · ' . strtoupper($a['exchange_label'] ?? 'OURBIT'), 12, $c->color(self::ORANGE_SOFT), 'Bold', 'right');

        // grid + axis labels on round numbers
        $gridCol = $c->color('#FFFFFF', 0.05);
        $tick = self::niceStep(($hi - $lo) / 6);
        $priceY = $py($a['price']);
        for ($p = ceil($lo / $tick) * $tick; $p <= $hi; $p += $tick) {
            $gy = $py($p);
            if ($gy < $y0 - 4) {
                continue;
            }
            $c->dashed($x0, $gy, $x1, $gy, $gridCol, 1, 3, 5);
            if (abs($gy - $priceY) > 18) {
                $c->text($x1 + 12, $gy + 5, Fa::price($p), 11, $c->color(self::MUTED), 'Medium');
            }
        }
        // date labels
        for ($k = 0; $k < 4; $k++) {
            $i = $start + (int) round($N * (0.12 + 0.25 * $k));
            if ($i >= $n) {
                continue;
            }
            $ts = intdiv($s->t[$i], 1000);
            [$jy, $jm, $jd] = Fa::jalali((int) date('Y', $ts), (int) date('n', $ts), (int) date('j', $ts));
            $months = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
            $c->text($bx($i), $y1 + 30, Fa::digits($jd . ' ' . $months[$jm - 1]), 11, $c->color(self::MUTED), 'Medium', 'center');
        }

        // labels drawn last so candles never cover them
        $edge = [];   // right edge of the plot, stacked without overlap
        $free = [];   // fixed positions
        // key support / resistance levels (only the strong ones)
        foreach (['support' => self::GREEN, 'resistance' => self::RED] as $kind => $col) {
            foreach ($a['key_levels'][$kind] ?? [] as $k => $z) {
                if (!$inView($z['mid'])) {
                    continue;
                }
                // Fine dotted line at the zone's level
                $zy = $py($z['mid']);
                for ($dx = $x0; $dx < $x1; $dx += 7) {
                    $c->circle($dx, $zy, 1.3, $c->color($col));
                }
                $tag = ($kind === 'support' ? 'حمایت ' : 'مقاومت ') . Fa::digits((string) ($k + 1)) . '  ' . Fa::price($z['mid']);
                $edge[] = ['y' => $zy, 'text' => $tag, 'fg' => $c->color('#FFFFFF'), 'bg' => $c->color(Canvas::mix($col, '#000000', 0.2), 0.95), 'weight' => 'Bold'];
            }
        }

        // liquidity
        foreach ($a['liquidity'] as $l) {
            if (!$inView($l['price'])) {
                continue;
            }
            $ly = $py($l['price']);
            $lx = $l['i'] >= $start ? $bx($l['i']) : $x0;
            $c->dashed($lx, $ly, $x1, $ly, $c->color(self::ORANGE, 0.85), 1.4, 2, 4);
            $tag = ($l['side'] === 'buy' ? 'BSL' : 'SSL') . ' $$$';
            $edge[] = ['y' => $ly, 'text' => $tag, 'fg' => $c->color('#000000'), 'bg' => $c->color(self::ORANGE), 'weight' => 'Black'];
        }

        // structure events
        foreach (array_slice($a['events'], -3) as $ev) {
            if ($ev['to'] < $start || !$inView($ev['level'])) {
                continue;
            }
            $ex0 = $bx(max($ev['from'], $start));
            $ex1 = $bx($ev['to']);
            $ey = $py($ev['level']);
            $col = $ev['dir'] === 'up' ? self::GREEN : self::RED;
            $c->dashed($ex0, $ey, $ex1, $ey, $c->color($col, 0.9), 1.4, 5, 4);
            $c->text(($ex0 + $ex1) / 2, $ey + ($ev['dir'] === 'up' ? -7 : 17), $ev['type'], 11, $c->color($col), 'Black', 'center');
        }

        // volume
        $vis = array_slice($s->v, $start);
        $vmax = max($vis) ?: 1;
        for ($i = $start; $i < $n; $i++) {
            $vh = $s->v[$i] / $vmax * $volH;
            $col = $s->c[$i] >= $s->o[$i] ? self::CANDLE_UP : self::CANDLE_DOWN;
            $c->rect($bx($i) - $step * 0.32, $y1 - $vh, $bx($i) + $step * 0.32, $y1, $c->color($col, 0.18));
        }

        // candles
        for ($i = $start; $i < $n; $i++) {
            $up = $s->c[$i] >= $s->o[$i];
            $col = $c->color($up ? self::CANDLE_UP : self::CANDLE_DOWN);
            $x = $bx($i);
            $c->line($x, $py($s->h[$i]), $x, $py($s->l[$i]), $col, 1.3);
            $top = $py(max($s->o[$i], $s->c[$i]));
            $bot = $py(min($s->o[$i], $s->c[$i]));
            if ($bot - $top < 1.2) {
                $bot = $top + 1.2;
            }
            $c->rect($x - $step * 0.34, $top, $x + $step * 0.34, $bot, $col);
        }

        // order blocks: short dashed line at the 50% level, starting from the middle of the block's candle
        foreach ($a['order_blocks'] as $ob) {
            $mid = ($ob['top'] + $ob['bottom']) / 2;
            if (!$inView($mid)) {
                continue;
            }
            $col = $c->color(self::OB);
            $ox = $ob['i'] >= $start ? $bx($ob['i']) : $x0;
            $oxEnd = max($ox + 8 * $step, min($ox + 22 * $step, $nowX));
            $my = $py($mid);
            $c->dashed($ox, $my, $oxEnd, $my, $col, 2, 9, 5);
            $c->circle($ox, $my, 3.2, $col);
            $free[] = ['x' => $oxEnd, 'y' => $my - 21, 'align' => 'right', 'text' => '50% OB', 'fg' => $c->color('#001A26'), 'bg' => $c->color(self::OB, 0.95), 'h' => 18, 'size' => 9];
        }

        // swing labels
        foreach ($a['labels'] as $lb) {
            if ($lb['i'] < $start + 2 || !in_array($lb['label'], ['HH', 'HL', 'LH', 'LL'], true)) {
                continue;
            }
            $isHigh = $lb['type'] === 'high';
            $c->text($bx($lb['i']), $py($lb['price']) + ($isHigh ? -9 : 20), $lb['label'], 10, $c->color(self::TEXT_2, 0.85), 'Bold', 'center');
        }

        $fx0 = $nowX + $step * 0.5;

        // projected path (dashed): strong green when bullish, strong red when bearish
        if ($this->withPath) {
            $last = count($plan['path']) - 1;
            $xScale = ($x1 - 175 - $nowX) / max(1, $plan['path'][$last][0]);
            $pts = [];
            foreach ($plan['path'] as [$bars, $p]) {
                $pts[] = [$nowX + $bars * $xScale, $py($p)];
            }
            $pathCol = $c->color($plan['side'] === 'long' ? self::PATH_UP : self::PATH_DOWN);
            $c->dashedPolyline($pts, $pathCol, 3.4, 12, 7);
            foreach ($pts as $k => [$px, $pyy]) {
                if ($k > 0 && $k < $last) {
                    $c->circle($px, $pyy, 5, $pathCol);
                }
            }
            $angle = atan2($pts[$last][1] - $pts[$last - 1][1], $pts[$last][0] - $pts[$last - 1][0]);
            $c->arrowHead($pts[$last][0], $pts[$last][1], $angle, 20, $pathCol);
        }

        foreach ($free as $l) {
            $c->pill($l['x'], $l['y'], $l['text'], $l['size'] ?? 10, $l['fg'], $l['bg'], 'Bold', $l['align'] ?? 'left', 8, $l['h'] ?? 20);
        }
        usort($edge, static fn ($p, $q) => $p['y'] <=> $q['y']);
        $prev = -INF;
        foreach ($edge as $l) {
            $ly = max($l['y'], $prev + 24);
            $prev = $ly;
            $w = $c->pill($x1 - 8, $ly - 10, $l['text'], 10, $l['fg'], $l['bg'], $l['weight'] ?? 'Bold', 'right', 9, 20);
            if (isset($l['border'])) {
                $c->roundRectStroke($x1 - 8 - $w, $ly - 10, $w, 20, 10, $c->color($l['border'], 0.6), 1);
            }
        }

        // current price line
        $cy = $py($a['price']);
        $c->dashed($x0, $cy, $x1, $cy, $c->color('#FFFFFF', 0.35), 1, 2, 3);

        // current price tag
        $col = $a['change24h'] >= 0 ? self::GREEN : self::RED;
        $c->roundRect($x1 + 4, $cy - 13, 112, 27, 7, $c->color($col));
        $c->text($x1 + 60, $cy + 6, Fa::price($a['price']), 12, $c->color('#FFFFFF'), 'Black', 'center');
    }

    private static function niceStep(float $raw): float
    {
        if ($raw <= 0) {
            return 1;
        }
        $mag = 10 ** floor(log10($raw));
        foreach ([1, 2, 2.5, 5, 10] as $m) {
            if ($raw <= $m * $mag) {
                return $m * $mag;
            }
        }
        return 10 * $mag;
    }

    private function coinColor(string $base): string
    {
        $known = ['BTC' => '#F7931A', 'ETH' => '#627EEA', 'SOL' => '#9945FF', 'BNB' => '#F3BA2F', 'XRP' => '#23292F', 'DOGE' => '#C2A633', 'TON' => '#0098EA', 'ADA' => '#0033AD', 'AVAX' => '#E84142', 'LINK' => '#2A5ADA', 'TRX' => '#EB0029', 'DOT' => '#E6007A', 'PEPE' => '#3D9A3B', 'SHIB' => '#FFA409'];
        if (isset($known[$base])) {
            return $known[$base];
        }
        $h = crc32($base) % 360;
        // HSL(h, 65%, 55%) -> hex
        $s = 0.65;
        $l = 0.55;
        $k = static fn ($n) => fmod($n + $h / 30, 12);
        $f = static fn ($n) => $l - $s * min($l, 1 - $l) * max(-1, min($k($n) - 3, 9 - $k($n), 1));
        return sprintf('#%02x%02x%02x', (int) round($f(0) * 255), (int) round($f(8) * 255), (int) round($f(4) * 255));
    }
}

}

namespace App\Render {

/**
 * GD draws glyphs left-to-right without Arabic shaping, so Persian text has to be
 * converted to presentation forms (connected letters) and reordered visually first.
 */
final class Persian
{
    // char => [isolated, final, initial, medial]; two forms = joins only to the previous letter
    private const FORMS = [
        0x0621 => [0xFE80],
        0x0622 => [0xFE81, 0xFE82],
        0x0623 => [0xFE83, 0xFE84],
        0x0624 => [0xFE85, 0xFE86],
        0x0625 => [0xFE87, 0xFE88],
        0x0626 => [0xFE89, 0xFE8A, 0xFE8B, 0xFE8C],
        0x0627 => [0xFE8D, 0xFE8E],
        0x0628 => [0xFE8F, 0xFE90, 0xFE91, 0xFE92],
        0x0629 => [0xFE93, 0xFE94],
        0x062A => [0xFE95, 0xFE96, 0xFE97, 0xFE98],
        0x062B => [0xFE99, 0xFE9A, 0xFE9B, 0xFE9C],
        0x062C => [0xFE9D, 0xFE9E, 0xFE9F, 0xFEA0],
        0x062D => [0xFEA1, 0xFEA2, 0xFEA3, 0xFEA4],
        0x062E => [0xFEA5, 0xFEA6, 0xFEA7, 0xFEA8],
        0x062F => [0xFEA9, 0xFEAA],
        0x0630 => [0xFEAB, 0xFEAC],
        0x0631 => [0xFEAD, 0xFEAE],
        0x0632 => [0xFEAF, 0xFEB0],
        0x0633 => [0xFEB1, 0xFEB2, 0xFEB3, 0xFEB4],
        0x0634 => [0xFEB5, 0xFEB6, 0xFEB7, 0xFEB8],
        0x0635 => [0xFEB9, 0xFEBA, 0xFEBB, 0xFEBC],
        0x0636 => [0xFEBD, 0xFEBE, 0xFEBF, 0xFEC0],
        0x0637 => [0xFEC1, 0xFEC2, 0xFEC3, 0xFEC4],
        0x0638 => [0xFEC5, 0xFEC6, 0xFEC7, 0xFEC8],
        0x0639 => [0xFEC9, 0xFECA, 0xFECB, 0xFECC],
        0x063A => [0xFECD, 0xFECE, 0xFECF, 0xFED0],
        0x0641 => [0xFED1, 0xFED2, 0xFED3, 0xFED4],
        0x0642 => [0xFED5, 0xFED6, 0xFED7, 0xFED8],
        0x0643 => [0xFED9, 0xFEDA, 0xFEDB, 0xFEDC],
        0x0644 => [0xFEDD, 0xFEDE, 0xFEDF, 0xFEE0],
        0x0645 => [0xFEE1, 0xFEE2, 0xFEE3, 0xFEE4],
        0x0646 => [0xFEE5, 0xFEE6, 0xFEE7, 0xFEE8],
        0x0647 => [0xFEE9, 0xFEEA, 0xFEEB, 0xFEEC],
        0x0648 => [0xFEED, 0xFEEE],
        0x0649 => [0xFEEF, 0xFEF0],
        0x064A => [0xFEF1, 0xFEF2, 0xFEF3, 0xFEF4],
        0x067E => [0xFB56, 0xFB57, 0xFB58, 0xFB59],
        0x0686 => [0xFB7A, 0xFB7B, 0xFB7C, 0xFB7D],
        0x0698 => [0xFB8A, 0xFB8B],
        0x06A9 => [0xFB8E, 0xFB8F, 0xFB90, 0xFB91],
        0x06AF => [0xFB92, 0xFB93, 0xFB94, 0xFB95],
        0x06CC => [0xFBFC, 0xFBFD, 0xFBFE, 0xFBFF],
        0x0640 => [0x0640, 0x0640, 0x0640, 0x0640],
    ];

    // lam + alef variants => [isolated, final]
    private const LAM_ALEF = [
        0x0622 => [0xFEF5, 0xFEF6],
        0x0623 => [0xFEF7, 0xFEF8],
        0x0625 => [0xFEF9, 0xFEFA],
        0x0627 => [0xFEFB, 0xFEFC],
    ];

    private const MIRROR = ['(' => ')', ')' => '(', '[' => ']', ']' => '[', '{' => '}', '}' => '{', '«' => '»', '»' => '«', '<' => '>', '>' => '<'];

    public static function hasRtl(string $text): bool
    {
        return (bool) preg_match('/[\x{0600}-\x{06FF}\x{FB50}-\x{FEFF}]/u', $text);
    }

    /** Shapes and reorders a single line for left-to-right glyph drawing. */
    public static function visual(string $text): string
    {
        if (!self::hasRtl($text)) {
            return $text;
        }
        return self::reorder(self::shape($text));
    }

    private static function isTransparent(int $cp): bool
    {
        return ($cp >= 0x064B && $cp <= 0x065F) || $cp === 0x0670;
    }

    private static function shape(string $text): string
    {
        $cps = array_values(unpack('N*', mb_convert_encoding($text, 'UCS-4BE', 'UTF-8')));
        $n = count($cps);
        $out = [];
        $joinsNext = static fn (int $cp): bool => isset(self::FORMS[$cp]) && count(self::FORMS[$cp]) === 4;

        for ($i = 0; $i < $n; $i++) {
            $cp = $cps[$i];
            if (!isset(self::FORMS[$cp])) {
                if ($cp !== 0x200C) { // ZWNJ only breaks joining
                    $out[] = $cp;
                }
                continue;
            }
            // previous non-transparent char
            $p = $i - 1;
            while ($p >= 0 && self::isTransparent($cps[$p])) {
                $p--;
            }
            $prevJoins = $p >= 0 && $joinsNext($cps[$p]);

            // lam-alef ligature
            if ($cp === 0x0644) {
                $q = $i + 1;
                while ($q < $n && self::isTransparent($cps[$q])) {
                    $q++;
                }
                if ($q < $n && isset(self::LAM_ALEF[$cps[$q]])) {
                    $out[] = self::LAM_ALEF[$cps[$q]][$prevJoins ? 1 : 0];
                    $i = $q;
                    continue;
                }
            }

            $q = $i + 1;
            while ($q < $n && self::isTransparent($cps[$q])) {
                $q++;
            }
            $nextJoinable = $q < $n && isset(self::FORMS[$cps[$q]]);
            $forms = self::FORMS[$cp];
            $dual = count($forms) === 4;
            if ($prevJoins && $nextJoinable && $dual) {
                $out[] = $forms[3];
            } elseif ($prevJoins && count($forms) > 1) {
                $out[] = $forms[1];
            } elseif ($nextJoinable && $dual) {
                $out[] = $forms[2];
            } else {
                $out[] = $forms[0];
            }
        }
        return mb_convert_encoding(pack('N*', ...$out), 'UTF-8', 'UCS-4BE');
    }

    /**
     * Simplified Unicode bidi for an RTL paragraph. Types: R (Persian), L (Latin), E (digits), N (neutral).
     * LTR runs (words, numbers like "98,450.20", "+2.4%", "BTC/USDT") keep their internal order.
     */
    private static function reorder(string $text): string
    {
        $chars = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY);
        $n = count($chars);
        $types = [];
        foreach ($chars as $ch) {
            if (preg_match('/[0-9\x{06F0}-\x{06F9}\x{0660}-\x{0669}]/u', $ch)) {
                $types[] = 'E';
            } elseif (preg_match('/[\x{0600}-\x{06FF}\x{FB50}-\x{FEFF}]/u', $ch)) {
                $types[] = 'R';
            } elseif (preg_match('/[A-Za-z\x{00C0}-\x{024F}]/u', $ch)) {
                $types[] = 'L';
            } else {
                $types[] = 'N';
            }
        }

        // Number parts: separators between digits, %, and leading sign / currency.
        for ($i = 0; $i < $n; $i++) {
            if ($types[$i] !== 'N') {
                continue;
            }
            $c = $chars[$i];
            $prevE = $i > 0 && $types[$i - 1] === 'E';
            $nextE = $i + 1 < $n && $types[$i + 1] === 'E';
            if ($prevE && $nextE && in_array($c, [',', '.', ':', '/', '٫', '٬'], true)) {
                $types[$i] = 'E';
            } elseif ($prevE && in_array($c, ['%', '٪', 'x', '×'], true)) {
                $types[$i] = 'E';
            } elseif ($nextE && in_array($c, ['+', '-', '−', '$'], true) && ($i === 0 || $types[$i - 1] === 'N')) {
                $types[$i] = 'E';
            }
        }

        // Digits that follow Latin text belong to it (EMA200, RSI14).
        $strong = 'R';
        for ($i = 0; $i < $n; $i++) {
            if ($types[$i] === 'L' || $types[$i] === 'R') {
                $strong = $types[$i];
            } elseif ($types[$i] === 'E' && $strong === 'L') {
                $types[$i] = 'L';
            }
        }

        // Digits glued to a following Latin word belong to it too (4H, 1D).
        for ($i = $n - 2; $i >= 0; $i--) {
            if ($types[$i] === 'E' && $types[$i + 1] === 'L') {
                $types[$i] = 'L';
            }
        }

        // Neutrals take the direction of their neighbours when both agree (numbers count as R).
        for ($i = 0; $i < $n; $i++) {
            if ($types[$i] !== 'N') {
                continue;
            }
            $j = $i;
            while ($j < $n && $types[$j] === 'N') {
                $j++;
            }
            $left = $i > 0 ? $types[$i - 1] : 'R';
            $right = $j < $n ? $types[$j] : 'R';
            $dir = ($left === 'L' && $right === 'L') ? 'L' : 'R';
            for ($k = $i; $k < $j; $k++) {
                $types[$k] = $dir;
            }
            $i = $j - 1;
        }

        $runs = [];
        foreach ($chars as $i => $ch) {
            $t = $types[$i];
            if ($runs && $runs[count($runs) - 1][0] === $t) {
                $runs[count($runs) - 1][1][] = $ch;
            } else {
                $runs[] = [$t, [$ch]];
            }
        }
        $out = '';
        foreach (array_reverse($runs) as [$t, $cs]) {
            if ($t === 'R') {
                $cs = array_map(static fn ($c) => self::MIRROR[$c] ?? $c, array_reverse($cs));
            }
            $out .= implode('', $cs);
        }
        return $out;
    }
}

}

namespace App {

use PDO;

/**
 * SQLite storage: users, quota usage, processed updates and settings.
 */
final class Storage
{
    private PDO $db;

    public function __construct(string $file)
    {
        $dir = dirname($file);
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }
        $this->db = new PDO('sqlite:' . $file);
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $this->db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
        $this->db->exec('PRAGMA journal_mode = WAL');
        $this->db->exec('PRAGMA busy_timeout = 5000');
        $this->db->exec('CREATE TABLE IF NOT EXISTS users (
            user_id INTEGER PRIMARY KEY,
            first_name TEXT, username TEXT,
            bonus INTEGER NOT NULL DEFAULT 0,
            banned INTEGER NOT NULL DEFAULT 0,
            created_at INTEGER NOT NULL
        )');
        $this->db->exec('CREATE TABLE IF NOT EXISTS usage (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL, period TEXT NOT NULL,
            symbol TEXT NOT NULL, timeframe TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT \'pending\',
            created_at INTEGER NOT NULL
        )');
        $this->db->exec('CREATE INDEX IF NOT EXISTS usage_user_period ON usage(user_id, period)');
        $this->db->exec('CREATE TABLE IF NOT EXISTS updates (update_id INTEGER PRIMARY KEY, created_at INTEGER NOT NULL)');
        $this->db->exec('CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)');
    }

    /** Returns false if this update was already handled (Telegram retries webhooks). */
    public function claimUpdate(int $updateId): bool
    {
        $st = $this->db->prepare('INSERT OR IGNORE INTO updates (update_id, created_at) VALUES (?, ?)');
        $st->execute([$updateId, time()]);
        if (random_int(1, 200) === 1) {
            $this->db->prepare('DELETE FROM updates WHERE created_at < ?')->execute([time() - 7 * 86400]);
        }
        return $st->rowCount() === 1;
    }

    public function touchUser(array $from): void
    {
        $this->db->prepare('INSERT INTO users (user_id, first_name, username, created_at) VALUES (?, ?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET first_name = excluded.first_name, username = excluded.username')
            ->execute([(int) $from['id'], $from['first_name'] ?? '', $from['username'] ?? '', time()]);
    }

    public function user(int $id): ?array
    {
        $st = $this->db->prepare('SELECT * FROM users WHERE user_id = ?');
        $st->execute([$id]);
        return $st->fetch() ?: null;
    }

    public function findUser(string $ref): ?array
    {
        $ref = ltrim(trim($ref), '@');
        $st = ctype_digit($ref)
            ? $this->db->prepare('SELECT * FROM users WHERE user_id = ?')
            : $this->db->prepare('SELECT * FROM users WHERE lower(username) = lower(?)');
        $st->execute([$ref]);
        return $st->fetch() ?: null;
    }

    /** Counts pending + done requests so parallel messages cannot exceed the quota. */
    public function used(int $userId, string $period): int
    {
        $st = $this->db->prepare("SELECT COUNT(*) FROM usage WHERE user_id = ? AND period = ? AND status IN ('pending', 'done')");
        $st->execute([$userId, $period]);
        return (int) $st->fetchColumn();
    }

    /** Atomically reserves one analysis if the user still has quota. Returns the usage id or null. */
    public function reserve(int $userId, string $period, int $limit, string $symbol, string $tf): ?int
    {
        $this->db->exec('BEGIN IMMEDIATE');
        try {
            $user = $this->user($userId);
            $allowed = $limit + (int) ($user['bonus'] ?? 0);
            if ($limit >= 0 && $this->used($userId, $period) >= $allowed) {
                $this->db->exec('ROLLBACK');
                return null;
            }
            $this->db->prepare('INSERT INTO usage (user_id, period, symbol, timeframe, created_at) VALUES (?, ?, ?, ?, ?)')
                ->execute([$userId, $period, $symbol, $tf, time()]);
            $id = (int) $this->db->lastInsertId();
            $this->db->exec('COMMIT');
            return $id;
        } catch (\Throwable $e) {
            $this->db->exec('ROLLBACK');
            throw $e;
        }
    }

    public function finish(int $usageId, bool $ok): void
    {
        $this->db->prepare('UPDATE usage SET status = ? WHERE id = ?')->execute([$ok ? 'done' : 'failed', $usageId]);
    }

    public function addBonus(int $userId, int $n): void
    {
        $this->db->prepare('INSERT INTO users (user_id, bonus, created_at) VALUES (?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET bonus = bonus + excluded.bonus')->execute([$userId, $n, time()]);
    }

    public function resetUsage(int $userId, string $period): void
    {
        $this->db->prepare("UPDATE usage SET status = 'reset' WHERE user_id = ? AND period = ?")->execute([$userId, $period]);
        $this->db->prepare('UPDATE users SET bonus = 0 WHERE user_id = ?')->execute([$userId]);
    }

    public function setBanned(int $userId, bool $banned): void
    {
        $this->db->prepare('INSERT INTO users (user_id, banned, created_at) VALUES (?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET banned = excluded.banned')->execute([$userId, $banned ? 1 : 0, time()]);
    }

    public function stats(string $period): array
    {
        $q = fn (string $sql, array $p = []) => (function () use ($sql, $p) {
            $st = $this->db->prepare($sql);
            $st->execute($p);
            return $st;
        })();
        return [
            'users' => (int) $q('SELECT COUNT(*) FROM users')->fetchColumn(),
            'period_done' => (int) $q("SELECT COUNT(*) FROM usage WHERE period = ? AND status = 'done'", [$period])->fetchColumn(),
            'period_users' => (int) $q("SELECT COUNT(DISTINCT user_id) FROM usage WHERE period = ? AND status = 'done'", [$period])->fetchColumn(),
            'total_done' => (int) $q("SELECT COUNT(*) FROM usage WHERE status = 'done'")->fetchColumn(),
            'top' => $q("SELECT symbol, COUNT(*) n FROM usage WHERE period = ? AND status = 'done' GROUP BY symbol ORDER BY n DESC LIMIT 5", [$period])->fetchAll(),
        ];
    }

    public function get(string $key, ?string $default = null): ?string
    {
        $st = $this->db->prepare('SELECT value FROM settings WHERE key = ?');
        $st->execute([$key]);
        $v = $st->fetchColumn();
        return $v === false ? $default : (string) $v;
    }

    public function set(string $key, ?string $value): void
    {
        if ($value === null) {
            $this->db->prepare('DELETE FROM settings WHERE key = ?')->execute([$key]);
            return;
        }
        $this->db->prepare('INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value')->execute([$key, $value]);
    }
}

}

namespace App\Support {

/** Persian formatting helpers. */
final class Fa
{
    private const DIGITS_FA = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
    private const DIGITS_AR = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];

    public static function digits(string $s): string
    {
        return str_replace(range(0, 9), self::DIGITS_FA, $s);
    }

    public static function latinDigits(string $s): string
    {
        $latin = array_map('strval', range(0, 9));
        return str_replace(self::DIGITS_AR, $latin, str_replace(self::DIGITS_FA, $latin, $s));
    }

    public static function tf(string $tf): string
    {
        return match ($tf) {
            '1m' => '۱ دقیقه',
            '5m' => '۵ دقیقه',
            '15m' => '۱۵ دقیقه',
            '30m' => '۳۰ دقیقه',
            '1h' => '۱ ساعته',
            '2h' => '۲ ساعته',
            '4h' => '۴ ساعته',
            '6h' => '۶ ساعته',
            '12h' => '۱۲ ساعته',
            '1d' => 'روزانه',
            '1w' => 'هفتگی',
            default => $tf,
        };
    }

    public static function trend(string $trend): string
    {
        return match ($trend) {
            'bullish' => 'صعودی',
            'bearish' => 'نزولی',
            default => 'رنج',
        };
    }

    /** Price with precision that adapts to the magnitude (about 4 significant digits minimum). */
    public static function price(float $p): string
    {
        if ($p <= 0) {
            return '0';
        }
        $dec = max(2, 3 - (int) floor(log10($p)));
        $dec = min($dec, 10);
        return number_format($p, $dec, '.', ',');
    }

    public static function pct(float $v, int $dec = 2): string
    {
        return ($v >= 0 ? '+' : '') . number_format($v, $dec) . '%';
    }

    public static function compact(float $v): string
    {
        $abs = abs($v);
        return match (true) {
            $abs >= 1e9 => number_format($v / 1e9, 2) . 'B',
            $abs >= 1e6 => number_format($v / 1e6, 2) . 'M',
            $abs >= 1e3 => number_format($v / 1e3, 1) . 'K',
            default => number_format($v, 0),
        };
    }

    /** @return array{0:int,1:int,2:int} Jalali year, month, day */
    public static function jalali(int $gy, int $gm, int $gd): array
    {
        $gdm = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
        $gy2 = $gm > 2 ? $gy + 1 : $gy;
        $days = 355666 + (365 * $gy) + intdiv($gy2 + 3, 4) - intdiv($gy2 + 99, 100) + intdiv($gy2 + 399, 400) + $gd + $gdm[$gm - 1];
        $jy = -1595 + (33 * intdiv($days, 12053));
        $days %= 12053;
        $jy += 4 * intdiv($days, 1461);
        $days %= 1461;
        if ($days > 365) {
            $jy += intdiv($days - 1, 365);
            $days = ($days - 1) % 365;
        }
        if ($days < 186) {
            $jm = 1 + intdiv($days, 31);
            $jd = 1 + ($days % 31);
        } else {
            $jm = 7 + intdiv($days - 186, 30);
            $jd = 1 + (($days - 186) % 30);
        }
        return [$jy, $jm, $jd];
    }

    public static function jalaliDate(?int $ts = null, bool $withTime = true): string
    {
        $ts ??= time();
        [$y, $m, $d] = self::jalali((int) date('Y', $ts), (int) date('n', $ts), (int) date('j', $ts));
        $months = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
        $s = $d . ' ' . $months[$m - 1] . ' ' . $y;
        if ($withTime) {
            $s .= ' - ' . date('H:i', $ts);
        }
        return self::digits($s);
    }

    public static function weekday(int $w): string
    {
        return ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'][$w];
    }
}

}

namespace App\Support {

final class Http
{
    public static string $proxy = '';

    /**
     * @return array{status:int, body:string, error:string}
     */
    public static function request(string $method, string $url, array $options = []): array
    {
        $ch = curl_init($url);
        $headers = $options['headers'] ?? [];
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_MAXREDIRS => 3,
            CURLOPT_CONNECTTIMEOUT => $options['connect_timeout'] ?? 6,
            CURLOPT_TIMEOUT => $options['timeout'] ?? 15,
            CURLOPT_USERAGENT => 'Mozilla/5.0 (compatible; AnalystBot/1.0)',
            CURLOPT_ENCODING => '',
            CURLOPT_CUSTOMREQUEST => $method,
        ]);
        $proxy = (string) ($options['proxy'] ?? self::$proxy);
        if ($proxy !== '') {
            curl_setopt($ch, CURLOPT_PROXY, $proxy);
        }
        if (array_key_exists('json', $options)) {
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($options['json'], JSON_UNESCAPED_UNICODE));
            $headers[] = 'Content-Type: application/json';
        } elseif (array_key_exists('form', $options)) {
            curl_setopt($ch, CURLOPT_POSTFIELDS, $options['form']);
        }
        if ($headers) {
            curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        }
        $body = curl_exec($ch);
        $error = curl_error($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        curl_close($ch);
        return ['status' => $status, 'body' => is_string($body) ? $body : '', 'error' => $error];
    }

    public static function getJson(string $url, array $options = []): ?array
    {
        $res = self::request('GET', $url, $options);
        if ($res['status'] !== 200) {
            return null;
        }
        $data = json_decode($res['body'], true);
        return is_array($data) ? $data : null;
    }
}

}

namespace App\Support {

/**
 * Understands requests like "تحلیل BTC", "btc 1h", "تحلیل بیت کوین روزانه", "ETH/USDT h4".
 */
final class SymbolParser
{
    public const TIMEFRAMES = ['15m', '30m', '1h', '2h', '4h', '6h', '12h', '1d', '1w'];

    private const NAMES = [
        'بیت کوین' => 'BTC', 'بیتکوین' => 'BTC', 'بیت' => 'BTC', 'اتریوم' => 'ETH', 'اتریم' => 'ETH', 'اتر' => 'ETH',
        'سولانا' => 'SOL', 'ریپل' => 'XRP', 'دوج کوین' => 'DOGE', 'دوجکوین' => 'DOGE', 'دوج' => 'DOGE',
        'تون کوین' => 'TON', 'تونکوین' => 'TON', 'تون' => 'TON', 'کاردانو' => 'ADA', 'بایننس کوین' => 'BNB', 'بی ان بی' => 'BNB',
        'شیبا' => 'SHIB', 'پپه' => 'PEPE', 'ترون' => 'TRX', 'لایت کوین' => 'LTC', 'لایتکوین' => 'LTC',
        'آوالانچ' => 'AVAX', 'اوالانچ' => 'AVAX', 'چین لینک' => 'LINK', 'چینلینک' => 'LINK', 'پولکادات' => 'DOT',
        'نات کوین' => 'NOT', 'نات' => 'NOT', 'سویی' => 'SUI', 'سوئی' => 'SUI', 'اپتوس' => 'APT', 'آربیتروم' => 'ARB',
        'اپتیمیزم' => 'OP', 'کازماس' => 'ATOM', 'یونی سواپ' => 'UNI', 'استلار' => 'XLM', 'مونرو' => 'XMR',
        'اتریوم کلاسیک' => 'ETC', 'فایل کوین' => 'FIL', 'بیت کوین کش' => 'BCH', 'ترامپ' => 'TRUMP', 'هایپر لیکوئید' => 'HYPE',
        'طلا' => 'PAXG',
    ];

    private const TRIGGERS = ['تحلیل', 'انالیز', 'آنالیز', 'سیگنال', 'چارت', 'analysis', 'analyze', 'analyse', 'signal', 'chart'];

    private const STOP = ['USDT', 'USD', 'BUSD', 'USDC', 'IRT', 'TMN', 'PLEASE', 'PLS', 'THE', 'AND', 'FOR', 'OK', 'HI', 'TF', 'BOT',
        'ANALYSIS', 'ANALYZE', 'ANALYSE', 'SIGNAL', 'CHART', 'LONG', 'SHORT', 'SPOT', 'FUTURES', 'TP', 'SL'];

    /**
     * @return array{base: string, tf: ?string, explicit: bool}|null
     *   explicit = the message contains a trigger word such as "تحلیل"
     */
    public static function parse(string $text): ?array
    {
        $text = Fa::latinDigits(str_replace(["\u{200C}", "\u{200F}", "\u{200E}"], ' ', $text));
        $text = str_replace(['ي', 'ك'], ['ی', 'ک'], $text);
        $lower = mb_strtolower(trim($text));
        if ($lower === '' || mb_strlen($lower) > 160) {
            return null;
        }
        $explicit = false;
        foreach (self::TRIGGERS as $t) {
            if (str_contains($lower, $t)) {
                $explicit = true;
                break;
            }
        }

        $tf = self::timeframe($lower);
        $clean = preg_replace('/\b(?:\d{1,2}\s*(?:m|min|h|d|w)|[hHdDwWmM]\d{1,2})\b/u', ' ', $text);

        $base = null;
        // Persian names first (longest first so "بیت کوین کش" wins over "بیت کوین")
        $names = self::NAMES;
        uksort($names, static fn ($a, $b) => mb_strlen($b) <=> mb_strlen($a));
        foreach ($names as $name => $sym) {
            if (preg_match('/(?<![\p{L}])' . preg_quote($name, '/') . '(?![\p{L}])/u', $clean)) {
                $base = $sym;
                break;
            }
        }
        if ($base === null && preg_match_all('/(?<![A-Za-z0-9])\$?([A-Za-z][A-Za-z0-9]{1,14})(?:\s*[\/\-]?\s*(?:USDT|usdt|USD|usd))?(?![A-Za-z0-9])/u', $clean, $m)) {
            foreach ($m[1] as $tok) {
                $tok = strtoupper($tok);
                $tok = preg_replace('/(USDT|BUSD|USDC)$/', '', $tok) ?: $tok;
                if (strlen($tok) < 2 || in_array($tok, self::STOP, true)) {
                    continue;
                }
                $base = $tok;
                break;
            }
        }
        if ($base === null) {
            return null;
        }
        if (!$explicit) {
            // Without a trigger word only accept short messages that are basically just a symbol.
            $words = preg_split('/\s+/u', trim($lower));
            if (count($words) > 3) {
                return null;
            }
        }
        return ['base' => $base, 'tf' => $tf, 'explicit' => $explicit];
    }

    public static function timeframe(string $lower): ?string
    {
        $map = [
            '/(?<![a-z0-9])(?:15\s*m(?:in)?|m15)(?![a-z])|15\s*دقیقه/u' => '15m',
            '/(?<![a-z0-9])(?:30\s*m(?:in)?|m30)(?![a-z])|30\s*دقیقه|نیم\s*ساعت/u' => '30m',
            '/(?<![a-z0-9])(?:12\s*h|h12)(?![a-z])|12\s*ساعت/u' => '12h',
            '/(?<![a-z0-9])(?:6\s*h|h6)(?![a-z])|6\s*ساعت/u' => '6h',
            '/(?<![a-z0-9])(?:4\s*h|h4)(?![a-z])|4\s*ساعت|چهار\s*ساعت/u' => '4h',
            '/(?<![a-z0-9])(?:2\s*h|h2)(?![a-z])|2\s*ساعت|دو\s*ساعت/u' => '2h',
            '/(?<![a-z0-9])(?:1\s*h|h1)(?![a-z])|1\s*ساعت|یک\s*ساعت|ساعتی/u' => '1h',
            '/(?<![a-z0-9])(?:1\s*d|d1|daily)(?![a-z])|روزانه|دیلی|یک\s*روزه/u' => '1d',
            '/(?<![a-z0-9])(?:1\s*w|w1|weekly)(?![a-z])|هفتگی|ویکلی/u' => '1w',
        ];
        foreach ($map as $re => $tf) {
            if (preg_match($re, $lower)) {
                return $tf;
            }
        }
        return null;
    }
}

}

namespace App\Telegram {

use App\Support\Http;
use CURLFile;

/**
 * Minimal Telegram Bot API client. In dry-run mode calls are logged instead of sent.
 */
final class Client
{
    public array $sent = [];
    /** Dry-run only: canned results per method name. */
    public array $fake = [];

    public function __construct(private string $token, private bool $dryRun = false)
    {
    }

    public function call(string $method, array $params = []): ?array
    {
        if ($this->dryRun) {
            $this->sent[] = [$method, $params];
            if (array_key_exists($method, $this->fake)) {
                return $this->fake[$method];
            }
            return ['message_id' => count($this->sent), 'chat' => ['id' => $params['chat_id'] ?? 0]];
        }
        $hasFile = false;
        foreach ($params as $k => $v) {
            if ($v instanceof CURLFile) {
                $hasFile = true;
            } elseif (is_array($v)) {
                $params[$k] = json_encode($v, JSON_UNESCAPED_UNICODE);
            } elseif (is_bool($v)) {
                $params[$k] = $v ? 'true' : 'false';
            }
        }
        $url = (defined('TG_API_BASE') ? TG_API_BASE : 'https://api.telegram.org') . "/bot{$this->token}/{$method}";
        $res = Http::request('POST', $url, ['form' => $params, 'timeout' => $hasFile ? 60 : 20]);
        $data = json_decode($res['body'], true);
        if (!is_array($data) || empty($data['ok'])) {
            app_log("telegram {$method} failed: HTTP {$res['status']} " . substr($res['body'], 0, 300) . $res['error']);
            return null;
        }
        return is_array($data['result']) ? $data['result'] : ['value' => $data['result']];
    }

    /** Adds the direct-messages topic (channel DMs) to the target when present. */
    private static function target(array $to): array
    {
        $p = ['chat_id' => $to['chat_id']];
        if (!empty($to['topic_id'])) {
            $p['direct_messages_topic_id'] = $to['topic_id'];
        }
        if (!empty($to['reply_to'])) {
            $p['reply_parameters'] = ['message_id' => $to['reply_to'], 'allow_sending_without_reply' => true];
        }
        return $p;
    }

    public function sendMessage(array $to, string $html, array $extra = []): ?array
    {
        $send = fn (string $text) => $this->call('sendMessage', self::target($to) + [
            'text' => $text,
            'parse_mode' => 'HTML',
            'link_preview_options' => ['is_disabled' => true],
        ] + $extra);
        $res = $send($html);
        if ($res === null && str_contains($html, '<tg-emoji')) {
            // Premium emoji need a Premium bot owner; fall back to the plain emoji.
            $res = $send(Entities::stripCustomEmoji($html));
        }
        return $res;
    }

    public function sendPhoto(array $to, string $path, string $caption, array $extra = []): ?array
    {
        $send = fn (string $text) => $this->call('sendPhoto', self::target($to) + [
            'photo' => $this->dryRun ? $path : new CURLFile($path, 'image/png', basename($path)),
            'caption' => $text,
            'parse_mode' => 'HTML',
        ] + $extra);
        $res = $send($caption);
        if ($res === null && str_contains($caption, '<tg-emoji')) {
            $res = $send(Entities::stripCustomEmoji($caption));
        }
        return $res;
    }

    /** The bot's own user id is the part of the token before the colon. */
    public function botId(): int
    {
        return (int) strtok($this->token, ':');
    }

    public function editMessage(int|string $chatId, int $messageId, string $html, ?array $keyboard = null): ?array
    {
        $p = ['chat_id' => $chatId, 'message_id' => $messageId, 'text' => $html, 'parse_mode' => 'HTML', 'link_preview_options' => ['is_disabled' => true]];
        if ($keyboard !== null) {
            $p['reply_markup'] = ['inline_keyboard' => $keyboard];
        }
        $res = $this->call('editMessageText', $p);
        if ($res === null && str_contains($html, '<tg-emoji')) {
            $p['text'] = Entities::stripCustomEmoji($html);
            $res = $this->call('editMessageText', $p);
        }
        return $res;
    }

    public function answerCallback(string $id, string $text = ''): void
    {
        $this->call('answerCallbackQuery', ['callback_query_id' => $id] + ($text !== '' ? ['text' => $text] : []));
    }

    public function deleteMessage(int|string $chatId, int $messageId): void
    {
        $this->call('deleteMessage', ['chat_id' => $chatId, 'message_id' => $messageId]);
    }

    public function chatAction(array $to, string $action = 'upload_photo'): void
    {
        $p = ['chat_id' => $to['chat_id'], 'action' => $action];
        $this->call('sendChatAction', $p);
    }
}

}

namespace App\Telegram {

/**
 * Converts a Telegram message (text + entities) to HTML so formatting typed in the
 * Telegram app (bold, quote, spoiler, links, premium emoji, ...) can be stored and resent.
 */
final class Entities
{
    public static function toHtml(string $text, array $entities): string
    {
        // Entity offsets are in UTF-16 code units.
        $u16 = mb_convert_encoding($text, 'UTF-16LE', 'UTF-8');
        $len = intdiv(strlen($u16), 2);
        $opens = [];
        $closes = [];
        usort($entities, static fn ($a, $b) => [$a['offset'], -$a['length']] <=> [$b['offset'], -$b['length']]);
        foreach ($entities as $i => $e) {
            $tags = self::tags($e);
            if ($tags === null) {
                continue;
            }
            $start = (int) $e['offset'];
            $end = min($len, $start + (int) $e['length']);
            $opens[$start][] = [$i, $tags[0]];
            $closes[$end][] = [$i, $tags[1]];
        }

        $html = '';
        $stack = [];
        $segStart = 0;
        for ($pos = 0; $pos <= $len; $pos++) {
            if (!isset($opens[$pos]) && !isset($closes[$pos])) {
                continue;
            }
            $html .= self::escape(self::slice($u16, $segStart, $pos));
            $segStart = $pos;
            if (isset($closes[$pos])) {
                // Close in reverse opening order; reopen anything that was closed only to keep nesting valid.
                $ending = array_column($closes[$pos], 1, 0);
                $reopen = [];
                while ($ending && $stack) {
                    [$id, $close, $open] = array_pop($stack);
                    $html .= $close;
                    if (isset($ending[$id])) {
                        unset($ending[$id]);
                    } else {
                        $reopen[] = [$id, $close, $open];
                    }
                }
                foreach (array_reverse($reopen) as $r) {
                    $html .= $r[2];
                    $stack[] = $r;
                }
            }
            foreach ($opens[$pos] ?? [] as [$id, $open]) {
                $html .= $open;
                $closeTag = self::closingFor($open);
                $stack[] = [$id, $closeTag, $open];
            }
        }
        $html .= self::escape(self::slice($u16, $segStart, $len));
        while ($stack) {
            $html .= array_pop($stack)[1];
        }
        return $html;
    }

    /** @return array{0: string, 1: string}|null opening and closing tag */
    private static function tags(array $e): ?array
    {
        $attr = static fn (string $v) => htmlspecialchars($v, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        return match ($e['type'] ?? '') {
            'bold' => ['<b>', '</b>'],
            'italic' => ['<i>', '</i>'],
            'underline' => ['<u>', '</u>'],
            'strikethrough' => ['<s>', '</s>'],
            'spoiler' => ['<tg-spoiler>', '</tg-spoiler>'],
            'code' => ['<code>', '</code>'],
            'pre' => !empty($e['language'])
                ? ['<pre><code class="language-' . $attr((string) $e['language']) . '">', '</code></pre>']
                : ['<pre>', '</pre>'],
            'text_link' => ['<a href="' . $attr((string) ($e['url'] ?? '')) . '">', '</a>'],
            'text_mention' => ['<a href="tg://user?id=' . (int) ($e['user']['id'] ?? 0) . '">', '</a>'],
            'custom_emoji' => ['<tg-emoji emoji-id="' . $attr((string) ($e['custom_emoji_id'] ?? '')) . '">', '</tg-emoji>'],
            'blockquote' => ['<blockquote>', '</blockquote>'],
            'expandable_blockquote' => ['<blockquote expandable>', '</blockquote>'],
            default => null,
        };
    }

    private static function closingFor(string $open): string
    {
        if (str_starts_with($open, '<pre><code')) {
            return '</code></pre>';
        }
        preg_match('/^<([a-z\-]+)/', $open, $m);
        return '</' . $m[1] . '>';
    }

    private static function slice(string $u16, int $from, int $to): string
    {
        return $to > $from ? mb_convert_encoding(substr($u16, $from * 2, ($to - $from) * 2), 'UTF-8', 'UTF-16LE') : '';
    }

    private static function escape(string $s): string
    {
        return htmlspecialchars($s, ENT_NOQUOTES | ENT_HTML5, 'UTF-8');
    }

    /** Removes premium emoji tags but keeps their fallback emoji. */
    public static function stripCustomEmoji(string $html): string
    {
        return preg_replace('~<tg-emoji[^>]*>(.*?)</tg-emoji>~su', '$1', $html) ?? $html;
    }
}

}

namespace App {

/**
 * Every message the bot sends, as an HTML template editable from /panel.
 * {placeholders} are replaced with already-escaped values.
 */
final class Texts
{
    public const DEFS = [
        'welcome' => [
            'title' => 'خوش‌آمد (/start)',
            'vars' => '{name}',
            'default' => "👋 سلام {name}، خوش آمدید!\n\n🤖 من ربات تحلیلگر هستم. نام ارز را بفرستید تا تحلیل تکنیکال کامل با چارت دریافت کنید.\n\nمثال: <code>تحلیل BTC</code>\nراهنما: /help",
        ],
        'help' => [
            'title' => 'راهنما',
            'vars' => '{days} {quota}',
            'default' => "🤖 <b>ربات تحلیلگر</b>\n\nبرای دریافت تحلیل، نام ارز را بفرستید:\n• <code>تحلیل BTC</code>\n• <code>تحلیل ETH 1h</code>\n• <code>تحلیل سولانا روزانه</code>\n\nتایم‌فریم‌ها: 15m، 30m، 1h، 4h (پیش‌فرض)، 1d، 1w\n📅 روزهای تحلیل: {days}\n🎟 سهمیه هر کاربر: {quota} تحلیل در هفته\nبرای دیدن سهمیه بنویسید: <code>سهمیه</code>",
        ],
        'waiting' => [
            'title' => 'در حال تحلیل',
